        fn decide_options(&mut self, _game: &GameState, ctx: &SelectOptionsContext) -> Vec<usize> {
            vec![
                ctx.options
                    .iter()
                    .find(|option| option.description.contains(self.name))
                    .unwrap_or_else(|| ctx.options.iter().find(|option| option.legal).unwrap())
                    .index,
            ]
        }
