#[test]
fn cr_201_5a_c_creator_named_token_abilities_and_their_copies_keep_the_original_source() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::continuous::{EffectTarget, Modification};
    use ironsmith::effect::OutcomeValue;
    use ironsmith::effects::{ApplyContinuousEffect, CreateTokenCopyEffect, CreateTokenEffect};
    use ironsmith::target::{ChooseSpecSurfaceHint, SourceReferenceSurface};
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, CounterType, PowerToughness, StaticAbility, Until,
        Value, Zone,
    };
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for shortened in [false, true] {
            for rename in [false, true] {
                for token_local in [false, true] {
                    let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                    let counter = CounterType::Charge;
                    let creator_def =
                        CardDefinitionBuilder::new(CardId::new(), "Creator, the Original")
                            .card_types(vec![CardType::Enchantment])
                            .build();
                    let source =
                        game.create_object_from_definition(&creator_def, actor, Zone::Battlefield);
                    let namesake =
                        game.create_object_from_definition(&creator_def, actor, Zone::Battlefield);
                    game.add_counters(source, counter, 2).unwrap();
                    game.add_counters(namesake, counter, 9).unwrap();
                    let count = if token_local {
                        Value::CountersOnSource(counter)
                    } else {
                        Value::CountersOn(
                            Box::new(ChooseSpec::Source.with_surface_hint(
                                ChooseSpecSurfaceHint::SourceReference(if shortened {
                                    SourceReferenceSurface::ShortName("Creator".into())
                                } else {
                                    SourceReferenceSurface::FullName("Creator, the Original".into())
                                }),
                            )),
                            Some(counter),
                        )
                    };
                    let token_def = CardDefinitionBuilder::new(CardId::new(), "Construct")
                        .token().card_types(vec![CardType::Creature])
                        .power_toughness(PowerToughness::fixed(0, 0))
                        .with_ability(Ability::static_ability(StaticAbility::from_model(
                            ironsmith::static_abilities::CompiledStaticAbility::characteristic_defining_pt(count.clone(), count)
                        ))).build();
                    let mut ctx = EffectContext::new_default(source, actor);
                    let OutcomeValue::Objects(created) = CreateTokenEffect::one(token_def)
                        .execute(&mut game, &mut ctx)
                        .unwrap()
                        .value
                    else {
                        panic!("created token receipt")
                    };
                    assert_eq!(created.len(), 1);
                    let original = created[0];
                    game.add_counters(original, counter, 4).unwrap();
                    let OutcomeValue::Objects(copied) =
                        CreateTokenCopyEffect::one(ChooseSpec::SpecificObject(original))
                            .execute(&mut game, &mut ctx)
                            .unwrap()
                            .value
                    else {
                        panic!("copy token receipt")
                    };
                    assert_eq!(copied.len(), 1);
                    let copy = copied[0];
                    game.add_counters(copy, counter, 6).unwrap();
                    if rename {
                        ApplyContinuousEffect::new(
                            EffectTarget::Specific(source),
                            Modification::SetName("Renamed creator".into()),
                            Until::EndOfTurn,
                        )
                        .execute(&mut game, &mut ctx)
                        .unwrap();
                    }
                    for increment in [0, 1, 3] {
                        if increment != 0 {
                            game.add_counters(source, counter, increment).unwrap();
                        }
                        game.refresh_continuous_state().unwrap();
                        let source_count = game.object(source).unwrap().counters[&counter] as i32;
                        for (subject, own_count) in [(original, 4), (copy, 6)] {
                            let expected = if token_local { own_count } else { source_count };
                            assert_eq!(
                                (game.current_power(subject), game.current_toughness(subject)),
                                (Some(expected), Some(expected)),
                                "CR 201.5a/c: actor={actor:?}, shortened={shortened}, rename={rename}, token_local={token_local}, copy={}",
                                subject == copy
                            );
                        }
                    }
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 16);
}

#[test]
fn cr_201_5b_c_borrowed_self_named_activated_abilities_act_on_the_new_bearer() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::continuous::{EffectTarget, Modification};
    use ironsmith::effects::{ApplyContinuousEffect, GrantObjectAbilityEffect, UntapEffect};
    use ironsmith::target::{ChooseSpecSurfaceHint, SourceReferenceSurface};
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, Effect, LegalAction, ObjectFilter, Phase, TotalCost,
        Until, Zone,
    };
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for same_controller in [false, true] {
            for shortened in [false, true] {
                for mode in 0..3 {
                    for rename in [false, true] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        game.turn.active_player = actor;
                        game.turn.priority_player = Some(actor);
                        game.turn.phase = Phase::FirstMain;
                        let ability = Ability::activated(
                            TotalCost::free(),
                            vec![Effect::new(UntapEffect::with_spec(
                                ChooseSpec::Source.with_surface_hint(
                                    ChooseSpecSurfaceHint::SourceReference(if shortened {
                                        SourceReferenceSurface::ShortName("Donor".into())
                                    } else {
                                        SourceReferenceSurface::FullName("Donor, the Named".into())
                                    }),
                                ),
                            ))],
                        );
                        let donor_def =
                            CardDefinitionBuilder::new(CardId::new(), "Donor, the Named")
                                .card_types(vec![CardType::Artifact])
                                .with_ability(ability.clone())
                                .build();
                        let holder = if same_controller {
                            actor
                        } else {
                            PlayerId::from_index(1 - actor.0)
                        };
                        let donor = game.create_object_from_definition(
                            &donor_def,
                            holder,
                            Zone::Battlefield,
                        );
                        let namesake = game.create_object_from_definition(
                            &donor_def,
                            holder,
                            Zone::Battlefield,
                        );
                        let recipient_def =
                            CardDefinitionBuilder::new(CardId::new(), "Different bearer")
                                .card_types(vec![CardType::Artifact])
                                .build();
                        let recipient = game.create_object_from_definition(
                            &recipient_def,
                            actor,
                            Zone::Battlefield,
                        );
                        let mut ctx = EffectContext::new_default(donor, holder);
                        match mode {
                            0 => {
                                GrantObjectAbilityEffect::new(
                                    ability,
                                    ChooseSpec::SpecificObject(recipient),
                                )
                                .execute(&mut game, &mut ctx)
                                .unwrap();
                            }
                            1 => {
                                ApplyContinuousEffect::new(
                                    EffectTarget::Specific(recipient),
                                    Modification::AddAbilityGeneric(ability),
                                    Until::EndOfTurn,
                                )
                                .execute(&mut game, &mut ctx)
                                .unwrap();
                            }
                            _ => {
                                ApplyContinuousEffect::new(
                                    EffectTarget::Specific(recipient),
                                    Modification::CopyActivatedAbilities {
                                        filter: ObjectFilter::specific(donor),
                                        counter: None,
                                        include_mana: true,
                                        only_loyalty: false,
                                        exclude_source_name: false,
                                        exclude_source_id: false,
                                        force_once_each_turn: false,
                                    },
                                    Until::EndOfTurn,
                                )
                                .execute(&mut game, &mut ctx)
                                .unwrap();
                            }
                        }
                        if rename {
                            ApplyContinuousEffect::new(
                                EffectTarget::Specific(recipient),
                                Modification::SetName("Renamed bearer".into()),
                                Until::EndOfTurn,
                            )
                            .execute(&mut game, &mut ctx)
                            .unwrap();
                        }
                        for id in [donor, namesake, recipient] {
                            game.tap(id);
                        }
                        game.refresh_continuous_state().unwrap();
                        let actions: Vec<_> = ironsmith::compute_legal_actions(&game, actor).unwrap().into_iter()
                            .filter(|a| matches!(a, LegalAction::ActivateAbility { source, .. } if *source == recipient)).collect();
                        assert_eq!(actions.len(), 1, "native ability menu mode={mode}");
                        cr_audit_complete_priority_action(&mut game, actor, actions[0].clone())
                            .unwrap();
                        assert_eq!(game.stack.len(), 1);
                        assert_eq!(game.stack.last().unwrap().object_id, recipient);
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        assert!(
                            !game.is_tapped(recipient),
                            "CR 201.5b/c: actor={actor:?}, same_controller={same_controller}, shortened={shortened}, mode={mode}, rename={rename}"
                        );
                        assert!(game.is_tapped(donor));
                        assert!(game.is_tapped(namesake));
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 48);
}

#[test]
fn cr_201_5_c_a_tokens_own_proper_name_in_its_cda_does_not_mean_its_creator() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::continuous::{EffectTarget, Modification};
    use ironsmith::effect::OutcomeValue;
    use ironsmith::effects::{ApplyContinuousEffect, CreateTokenCopyEffect, CreateTokenEffect};
    use ironsmith::target::{ChooseSpecSurfaceHint, SourceReferenceSurface};
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, CounterType, PowerToughness, StaticAbility, Until,
        Value, Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for shortened in [false, true] {
            for rename in [false, true] {
                for named in [false, true] {
                    let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                    let counter = CounterType::Charge;
                    let creator_def =
                        CardDefinitionBuilder::new(CardId::new(), "Unrelated token creator")
                            .card_types(vec![CardType::Enchantment])
                            .build();
                    let source =
                        game.create_object_from_definition(&creator_def, actor, Zone::Battlefield);
                    game.add_counters(source, counter, 2).unwrap();
                    // The ability's own named bearer is the token, not the
                    // source of the resolving token-creation instruction.
                    let spec = if named {
                        ChooseSpec::Source.with_surface_hint(
                            ChooseSpecSurfaceHint::SourceReference(if shortened {
                                SourceReferenceSurface::ShortName("Construct".into())
                            } else {
                                SourceReferenceSurface::FullName(
                                    "Construct, the Counter Bearer".into(),
                                )
                            }),
                        )
                    } else {
                        ChooseSpec::Source
                    };
                    let count = Value::CountersOn(Box::new(spec), Some(counter));
                    let token_def = CardDefinitionBuilder::new(CardId::new(), "Construct, the Counter Bearer")
                        .token().card_types(vec![CardType::Creature])
                        .power_toughness(PowerToughness::fixed(0, 0))
                        .with_ability(Ability::static_ability(StaticAbility::from_model(
                            ironsmith::static_abilities::CompiledStaticAbility::characteristic_defining_pt(count.clone(), count)
                        ))).build();
                    let mut ctx = EffectContext::new_default(source, actor);
                    let OutcomeValue::Objects(created) = CreateTokenEffect::one(token_def)
                        .execute(&mut game, &mut ctx)
                        .unwrap()
                        .value
                    else {
                        panic!("created token receipt")
                    };
                    assert_eq!(created.len(), 1);
                    let original = created[0];
                    game.add_counters(original, counter, 4).unwrap();
                    let OutcomeValue::Objects(copied) =
                        CreateTokenCopyEffect::one(ChooseSpec::SpecificObject(original))
                            .execute(&mut game, &mut ctx)
                            .unwrap()
                            .value
                    else {
                        panic!("copy token receipt")
                    };
                    assert_eq!(copied.len(), 1);
                    let copy = copied[0];
                    game.add_counters(copy, counter, 6).unwrap();
                    if rename {
                        for subject in [original, copy] {
                            ApplyContinuousEffect::new(
                                EffectTarget::Specific(subject),
                                Modification::SetName("Renamed self-referential token".into()),
                                Until::EndOfTurn,
                            )
                            .execute(&mut game, &mut ctx)
                            .unwrap();
                        }
                    }
                    for extra in [0, 1] {
                        if extra != 0 {
                            game.add_counters(source, counter, extra).unwrap();
                        }
                        game.refresh_continuous_state().unwrap();
                        for (subject, expected) in [(original, 4), (copy, 6)] {
                            let actual =
                                (game.current_power(subject), game.current_toughness(subject));
                            if actual != (Some(expected), Some(expected)) {
                                discrepancies.push(format!("actor={actor:?}, shortened={shortened}, rename={rename}, named={named}, extra_creator_counters={extra}, copy={}: {actual:?}, required {expected}/{expected}", subject == copy));
                            }
                        }
                    }
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 16);
    assert!(
        discrepancies.is_empty(),
        "CR 201.5/c: a token's own full or shortened name refers only to that token, including a copy and after name changes: {discrepancies:#?}"
    );
}

struct CrAuditSubtypeMenu {
    choice: usize,
    calls: usize,
    menu: Vec<(String, bool)>,
}

impl DecisionMaker for CrAuditSubtypeMenu {
    fn decide_options(&mut self, _game: &GameState, ctx: &SelectOptionsContext) -> Vec<usize> {
        assert_eq!(
            (ctx.min, ctx.max),
            (1, 1),
            "CR 205.3e: choose exactly one subtype"
        );
        self.calls += 1;
        let observed: Vec<_> = ctx
            .options
            .iter()
            .map(|o| (o.description.clone(), o.legal))
            .collect();
        if self.menu.is_empty() {
            self.menu = observed;
        } else {
            assert_eq!(
                self.menu, observed,
                "the same unrestricted subtype instruction has a stable menu"
            );
        }
        vec![ctx.options[self.choice].index]
    }
}

fn cr_audit_subtype_inventory_matches_rule(
    family: ironsmith::types::SubtypeFamily,
    rule: &str,
    expected: &[&str],
) {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::ChooseCreatureTypeEffect;
    use ironsmith::{CardId, CardType, Zone};
    use std::collections::BTreeSet;
    let normalize = |s: &str| s.replace('’', "'");
    let required: BTreeSet<_> = expected.iter().map(|s| normalize(s)).collect();
    assert_eq!(
        required.len(),
        expected.len(),
        "independent CR list has no duplicates"
    );
    let mut discrepancies = Vec::new();
    let mut selections = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
        let definition = CardDefinitionBuilder::new(CardId::new(), "Subtype choice source")
            .card_types(vec![CardType::Artifact])
            .build();
        let source = game.create_object_from_definition(&definition, actor, Zone::Battlefield);
        let mut dm = CrAuditSubtypeMenu {
            choice: 0,
            calls: 0,
            menu: vec![],
        };
        let effect = ChooseCreatureTypeEffect::for_family(PlayerFilter::You, family);
        effect
            .execute(&mut game, &mut EffectContext::new(source, actor, &mut dm))
            .unwrap();
        assert_eq!(dm.calls, 1);
        assert!(!dm.menu.is_empty());
        let offered: BTreeSet<_> = dm
            .menu
            .iter()
            .filter(|(_, legal)| *legal)
            .map(|(name, _)| normalize(name))
            .collect();
        assert_eq!(
            offered.len(),
            dm.menu.len(),
            "no duplicate or disabled choices in unrestricted family"
        );
        let missing: Vec<_> = required.difference(&offered).collect();
        let extra: Vec<_> = offered.difference(&required).collect();
        if !missing.is_empty() || !extra.is_empty() {
            discrepancies.push(format!(
                "actor={actor:?}, {family:?}: missing {missing:?}; illegal {extra:?}"
            ));
        }
        let menu = dm.menu.clone();
        for (index, (name, _)) in menu.iter().enumerate() {
            if index != 0 {
                dm.choice = index;
                effect
                    .execute(&mut game, &mut EffectContext::new(source, actor, &mut dm))
                    .unwrap();
            }
            let chosen = game
                .chosen_subtype(source)
                .expect("choice is committed to its source");
            assert_eq!(
                normalize(&chosen.to_string()),
                normalize(name),
                "actual selected option must be stored exactly"
            );
            selections += 1;
        }
        assert_eq!(dm.calls, menu.len());
    }
    assert!(selections > 0);
    assert!(
        discrepancies.is_empty(),
        "CR {rule} / 205.3e: every existing subtype in the requested family, and no other subtype, must be selectable; {selections} actual stored choices checked: {discrepancies:#?}"
    );
}

