#[test]
fn cr_205_1a_valid_dauthi_plan_and_omen_subtypes_survive_and_replace_as_their_families_require() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::continuous::{EffectTarget, Modification};
    use ironsmith::effects::ApplyContinuousEffect;
    use ironsmith::{CardId, CardType, StackEntry, Subtype, Until, Zone};
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for (support, suspect, control, replacement) in [
            (
                CardType::Creature,
                Subtype::Dauthi,
                Subtype::Goblin,
                Subtype::Elf,
            ),
            (
                CardType::Enchantment,
                Subtype::Plan,
                Subtype::Aura,
                Subtype::Shrine,
            ),
            (
                CardType::Instant,
                Subtype::Omen,
                Subtype::Arcane,
                Subtype::Trap,
            ),
            (
                CardType::Sorcery,
                Subtype::Omen,
                Subtype::Arcane,
                Subtype::Trap,
            ),
        ] {
            for use_suspect in [false, true] {
                for mode in 0..4 {
                    let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                    let original = if use_suspect { suspect } else { control };
                    let definition = CardDefinitionBuilder::new(
                        CardId::new(),
                        "Subtype family retention subject",
                    )
                    .card_types(vec![support, CardType::Artifact])
                    .subtypes(vec![original, Subtype::Equipment])
                    .build();
                    let zone = if matches!(support, CardType::Instant | CardType::Sorcery) {
                        Zone::Stack
                    } else {
                        Zone::Battlefield
                    };
                    let source = game.create_object_from_definition(&definition, actor, zone);
                    if zone == Zone::Stack {
                        game.stack.push(StackEntry::new(source, actor));
                    }
                    assert!(game.current_subtypes(source).unwrap().contains(&original));
                    let modification = match mode {
                        0 => Modification::SetCardTypes(vec![support]),
                        1 => Modification::RemoveCardTypes(vec![CardType::Artifact]),
                        2 => Modification::RemoveCardTypes(vec![support]),
                        _ => Modification::SetSubtypes(vec![replacement]),
                    };
                    ApplyContinuousEffect::new(
                        EffectTarget::Specific(source),
                        modification,
                        Until::EndOfTurn,
                    )
                    .execute(&mut game, &mut EffectContext::new_default(source, actor))
                    .unwrap();
                    let actual = game.current_subtypes(source).unwrap();
                    let mut expected = match mode {
                        0 | 1 => vec![original],
                        2 => vec![Subtype::Equipment],
                        _ => vec![replacement, Subtype::Equipment],
                    };
                    let mut observed = actual.clone();
                    expected.sort_by_key(|t| t.to_string());
                    observed.sort_by_key(|t| t.to_string());
                    if observed != expected {
                        discrepancies.push(format!("actor={actor:?}, support={support:?}, original={original:?}, mode={mode}: got {actual:?}; required {expected:?}"));
                    }
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 64);
    assert!(
        discrepancies.is_empty(),
        "CR 205.1a / 205.3h/k/m: retain subtypes whose supporting card type remains and replace only the requested subtype family: {discrepancies:#?}"
    );
}

#[test]
fn cr_702_73a_changeling_is_every_existing_creature_type_in_every_zone() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::{Ability, CardId, CardType, StackEntry, StaticAbility, Subtype, Zone};
    use std::collections::BTreeSet;
    let required: BTreeSet<_> = cr_audit_cr_creature_subtypes()
        .iter()
        .map(|s| s.replace('’', "'"))
        .collect();
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for zone in [
            Zone::Battlefield,
            Zone::Hand,
            Zone::Library,
            Zone::Graveyard,
            Zone::Stack,
            Zone::Exile,
            Zone::Command,
            Zone::Ante,
            Zone::OutsideGame,
        ] {
            for kindred in [false, true] {
                for changeling in [false, true] {
                    let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                    let mut builder =
                        CardDefinitionBuilder::new(CardId::new(), "Every creature type subject")
                            .card_types(if kindred {
                                vec![CardType::Kindred, CardType::Enchantment]
                            } else {
                                vec![CardType::Creature]
                            })
                            .subtypes(vec![Subtype::Goblin]);
                    if changeling {
                        builder = builder
                            .with_ability(Ability::static_ability(StaticAbility::changeling()));
                    }
                    let source = game.create_object_from_definition(&builder.build(), actor, zone);
                    if zone == Zone::Stack {
                        game.stack.push(StackEntry::new(source, actor));
                    }
                    game.refresh_continuous_state().unwrap();
                    let current = game.current_subtypes(source).unwrap();
                    let actual: BTreeSet<_> = current
                        .iter()
                        .map(|t| t.to_string().replace('’', "'"))
                        .collect();
                    let expected = if changeling {
                        required.clone()
                    } else {
                        BTreeSet::from(["Goblin".to_string()])
                    };
                    let missing: Vec<_> = expected.difference(&actual).collect();
                    let extra: Vec<_> = actual.difference(&expected).collect();
                    if !missing.is_empty() || !extra.is_empty() {
                        discrepancies.push(format!("actor={actor:?}, zone={zone:?}, kindred={kindred}, changeling={changeling}: missing {missing:?}; noncreature/obsolete types {extra:?}"));
                    }
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 72);
    assert!(
        discrepancies.is_empty(),
        "CR 702.73a / 205.3m: changeling grants every current creature type everywhere, including outside the game: {discrepancies:#?}"
    );
}

#[test]
fn cr_205_3i_native_land_type_choices_distinguish_all_basic_and_nonbasic_types() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::ChooseLandTypeEffect;
    use ironsmith::{CardId, CardType, Zone};
    use std::collections::BTreeSet;
    let all = [
        "Cave",
        "Desert",
        "Forest",
        "Gate",
        "Island",
        "Lair",
        "Locus",
        "Mine",
        "Mountain",
        "Plains",
        "Planet",
        "Power-Plant",
        "Sphere",
        "Swamp",
        "Tower",
        "Town",
        "Urza's",
    ];
    let basic = BTreeSet::from(["Forest", "Island", "Mountain", "Plains", "Swamp"]);
    let mut selections = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for mode in 0..3 {
            let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
            let definition = CardDefinitionBuilder::new(CardId::new(), "Land type choice source")
                .card_types(vec![CardType::Artifact])
                .build();
            let source = game.create_object_from_definition(&definition, actor, Zone::Battlefield);
            let effect = match mode {
                0 => ChooseLandTypeEffect::new(PlayerFilter::You, false),
                1 => ChooseLandTypeEffect::new(PlayerFilter::You, false).basic_only(),
                _ => ChooseLandTypeEffect::new(PlayerFilter::You, true),
            };
            let required: BTreeSet<_> = all
                .iter()
                .filter(|name| match mode {
                    1 => basic.contains(**name),
                    2 => !basic.contains(**name),
                    _ => true,
                })
                .map(|s| s.to_string())
                .collect();
            let mut dm = CrAuditSubtypeMenu {
                choice: 0,
                calls: 0,
                menu: vec![],
            };
            effect
                .execute(&mut game, &mut EffectContext::new(source, actor, &mut dm))
                .unwrap();
            let offered: BTreeSet<_> = dm
                .menu
                .iter()
                .filter(|(_, legal)| *legal)
                .map(|(name, _)| name.replace('’', "'"))
                .collect();
            assert_eq!(offered, required, "CR 205.3i: mode={mode}, actor={actor:?}");
            let menu = dm.menu.clone();
            for (index, (name, _)) in menu.iter().enumerate() {
                if index != 0 {
                    dm.choice = index;
                    effect
                        .execute(&mut game, &mut EffectContext::new(source, actor, &mut dm))
                        .unwrap();
                }
                let selected = game.chosen_land_type(source).unwrap();
                assert!(selected.is_land_subtype());
                assert_eq!(selected.to_string(), *name);
                assert_eq!(
                    selected.is_basic_land_type(),
                    basic.contains(selected.to_string().as_str())
                );
                selections += 1;
            }
            assert_eq!(dm.calls, menu.len());
        }
    }
    assert_eq!(selections, 68);
}

fn cr_audit_complete_card_type_inventory() -> &'static [ironsmith::CardType] {
    use ironsmith::CardType::*;
    &[
        Artifact,
        Battle,
        Conspiracy,
        Creature,
        Dungeon,
        Enchantment,
        Instant,
        Kindred,
        Land,
        Phenomenon,
        Plane,
        Planeswalker,
        Scheme,
        Sorcery,
        Vanguard,
    ]
}

struct CrAuditCardTypeChoice {
    chooser: PlayerId,
    position: usize,
    menu: Vec<(String, bool)>,
    calls: usize,
}

impl DecisionMaker for CrAuditCardTypeChoice {
    fn decide_options(&mut self, _game: &GameState, ctx: &SelectOptionsContext) -> Vec<usize> {
        assert_eq!(ctx.player, self.chooser);
        assert_eq!((ctx.min, ctx.max), (1, 1));
        let observed = ctx
            .options
            .iter()
            .map(|o| (o.description.clone(), o.legal))
            .collect::<Vec<_>>();
        if self.menu.is_empty() {
            self.menu = observed;
        } else {
            assert_eq!(self.menu, observed);
        }
        self.calls += 1;
        vec![ctx.options[self.position].index]
    }
}

fn cr_audit_select_every_card_type(options: Vec<ironsmith::CardType>) -> Vec<String> {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::ChooseCardTypeEffect;
    use ironsmith::{CardId, CardType, Zone};
    let mut discrepancies = Vec::new();
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
        let definition = CardDefinitionBuilder::new(CardId::new(), "Card type choice source")
            .card_types(vec![CardType::Artifact])
            .build();
        let source = game.create_object_from_definition(&definition, actor, Zone::Battlefield);
        let expected = if options.is_empty() {
            cr_audit_complete_card_type_inventory().to_vec()
        } else {
            options.clone()
        };
        let effect = ChooseCardTypeEffect::new(PlayerFilter::You, options.clone());
        let mut dm = CrAuditCardTypeChoice {
            chooser: actor,
            position: 0,
            menu: vec![],
            calls: 0,
        };
        effect
            .execute(&mut game, &mut EffectContext::new(source, actor, &mut dm))
            .unwrap();
        let offered: std::collections::BTreeSet<_> = dm
            .menu
            .iter()
            .filter(|(_, legal)| *legal)
            .map(|(name, _)| name.clone())
            .collect();
        let required: std::collections::BTreeSet<_> =
            expected.iter().map(|kind| kind.to_string()).collect();
        assert_eq!(
            offered.len(),
            dm.menu.len(),
            "no repeated/disabled card-type options"
        );
        let missing: Vec<_> = required.difference(&offered).collect();
        let extra: Vec<_> = offered.difference(&required).collect();
        if !missing.is_empty() || !extra.is_empty() {
            discrepancies.push(format!(
                "actor={actor:?}: missing {missing:?}; invalid {extra:?}"
            ));
        }
        let menu = dm.menu.clone();
        for (position, (name, _)) in menu.iter().enumerate() {
            if position != 0 {
                dm.position = position;
                effect
                    .execute(&mut game, &mut EffectContext::new(source, actor, &mut dm))
                    .unwrap();
            }
            assert_eq!(
                game.chosen_card_type(source).unwrap().to_string(),
                *name,
                "selected type is committed exactly"
            );
        }
        assert_eq!(dm.calls, menu.len());
    }
    discrepancies
}

#[test]
fn cr_205_2a_unrestricted_card_type_choices_include_nontraditional_types() {
    let discrepancies = cr_audit_select_every_card_type(vec![]);
    assert!(
        discrepancies.is_empty(),
        "CR 205.2a: unrestricted card-type choices may name any of the fifteen card types: {discrepancies:#?}"
    );
}

#[test]
fn cr_205_2a_explicit_card_type_domains_store_every_type_and_respect_restrictions() {
    use ironsmith::CardType;
    let domains = [
        cr_audit_complete_card_type_inventory().to_vec(),
        cr_audit_complete_card_type_inventory()
            .iter()
            .copied()
            .filter(|t| !matches!(t, CardType::Creature | CardType::Land))
            .collect(),
        vec![
            CardType::Artifact,
            CardType::Battle,
            CardType::Creature,
            CardType::Enchantment,
            CardType::Land,
            CardType::Planeswalker,
        ],
    ];
    let mut selections = 0;
    for domain in domains {
        selections += domain.len() * 2;
        assert!(cr_audit_select_every_card_type(domain).is_empty());
    }
    assert_eq!(selections, 68);
}

#[test]
fn cr_205_2b_multitype_objects_match_effects_for_each_of_their_card_types() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::{CardId, CardType, Effect, ObjectFilter, StackEntry, Value, Zone};
    let mut cases = 0;
    let mut checks = 0;
    let mut discrepancies = Vec::new();
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for types in [
            vec![CardType::Artifact, CardType::Creature],
            vec![CardType::Enchantment, CardType::Creature],
            vec![CardType::Artifact, CardType::Enchantment],
            vec![CardType::Land, CardType::Creature],
            vec![CardType::Artifact, CardType::Land],
            vec![CardType::Artifact, CardType::Land, CardType::Creature],
            vec![CardType::Kindred, CardType::Artifact],
            vec![CardType::Kindred, CardType::Enchantment],
            vec![CardType::Kindred, CardType::Instant],
            vec![CardType::Kindred, CardType::Sorcery],
        ] {
            for zone in [
                Zone::Battlefield,
                Zone::Hand,
                Zone::Library,
                Zone::Graveyard,
                Zone::Exile,
                Zone::Command,
                Zone::Stack,
            ] {
                if zone == Zone::Battlefield
                    && types
                        .iter()
                        .any(|t| matches!(t, CardType::Instant | CardType::Sorcery))
                {
                    continue;
                }
                let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                let definition =
                    CardDefinitionBuilder::new(CardId::new(), "Multiple card type subject")
                        .card_types(types.clone())
                        .power_toughness(ironsmith::PowerToughness::fixed(3, 4))
                        .build();
                let subject = game.create_object_from_definition(&definition, actor, zone);
                if zone == Zone::Stack {
                    game.stack.push(StackEntry::new(subject, actor));
                }
                let observer =
                    CardDefinitionBuilder::new(CardId::new(), "Card type query observer")
                        .card_types(vec![CardType::Artifact])
                        .build();
                let observer =
                    game.create_object_from_definition(&observer, actor, Zone::Battlefield);
                for queried in cr_audit_complete_card_type_inventory() {
                    let before = game.player(actor).unwrap().life;
                    game.stack.push(StackEntry::ability(
                        observer,
                        actor,
                        vec![Effect::gain_life(Value::Count(
                            ObjectFilter::specific(subject)
                                .in_zone(zone)
                                .with_type(*queried),
                        ))],
                    ));
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    let actual = game.player(actor).unwrap().life - before;
                    let expected = i32::from(types.contains(queried));
                    if actual != expected {
                        discrepancies.push(format!("actor={actor:?}, types={types:?}, zone={zone:?}, query={queried:?}: count={actual}, required={expected}"));
                    }
                    checks += 1;
                }
                cases += 1;
            }
        }
    }
    assert_eq!((cases, checks), (136, 2040));
    assert!(
        discrepancies.is_empty(),
        "CR 205.2b: every type on an object independently satisfies effect criteria: {discrepancies:#?}"
    );
}

#[test]
fn cr_205_2c_tokens_and_spell_copies_keep_types_and_match_typed_effects() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effect::OutcomeValue;
    use ironsmith::effects::{CopySpellEffect, CreateTokenCopyEffect, CreateTokenEffect};
    use ironsmith::object::ObjectKind;
    use ironsmith::{CardId, CardType, ChooseSpec, Effect, ObjectFilter, StackEntry, Value, Zone};
    let mut fixtures = 0;
    let mut checks = 0;
    let mut discrepancies = Vec::new();
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for types in [
            vec![CardType::Artifact, CardType::Creature],
            vec![CardType::Enchantment, CardType::Creature],
            vec![CardType::Artifact, CardType::Enchantment],
            vec![CardType::Land, CardType::Creature],
            vec![CardType::Artifact, CardType::Land],
            vec![CardType::Artifact, CardType::Land, CardType::Creature],
            vec![CardType::Kindred, CardType::Artifact],
            vec![CardType::Kindred, CardType::Enchantment],
            vec![CardType::Kindred, CardType::Instant],
            vec![CardType::Kindred, CardType::Sorcery],
        ] {
            for mode in 0..3 {
                let spell = types
                    .iter()
                    .any(|t| matches!(t, CardType::Instant | CardType::Sorcery));
                if spell && mode != 2 {
                    continue;
                }
                let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                let observer =
                    CardDefinitionBuilder::new(CardId::new(), "Noncard type query observer")
                        .card_types(vec![CardType::Artifact])
                        .build();
                let observer =
                    game.create_object_from_definition(&observer, actor, Zone::Battlefield);
                let mut builder = CardDefinitionBuilder::new(CardId::new(), "Noncard type subject")
                    .card_types(types.clone())
                    .power_toughness(ironsmith::PowerToughness::fixed(3, 4));
                if mode != 2 {
                    builder = builder.token();
                }
                let definition = builder.build();
                let mut ctx = EffectContext::new_default(observer, actor);
                let subject = if mode == 2 {
                    let original =
                        game.create_object_from_definition(&definition, actor, Zone::Stack);
                    assert_eq!(game.object(original).unwrap().kind, ObjectKind::Card);
                    game.stack.push(StackEntry::new(original, actor));
                    CopySpellEffect::single(ChooseSpec::SpecificObject(original))
                        .execute(&mut game, &mut ctx)
                        .unwrap();
                    assert_eq!(game.stack.len(), 2);
                    let copy = game.stack.last().unwrap().object_id;
                    assert_eq!(game.object(copy).unwrap().kind, ObjectKind::SpellCopy);
                    copy
                } else {
                    let OutcomeValue::Objects(created) = CreateTokenEffect::one(definition)
                        .execute(&mut game, &mut ctx)
                        .unwrap()
                        .value
                    else {
                        panic!("created token receipt")
                    };
                    assert_eq!(created.len(), 1);
                    let original = created[0];
                    assert_eq!(game.object(original).unwrap().kind, ObjectKind::Token);
                    if mode == 0 {
                        original
                    } else {
                        let OutcomeValue::Objects(created) =
                            CreateTokenCopyEffect::one(ChooseSpec::SpecificObject(original))
                                .execute(&mut game, &mut ctx)
                                .unwrap()
                                .value
                        else {
                            panic!("copied token receipt")
                        };
                        assert_eq!(created.len(), 1);
                        created[0]
                    }
                };
                assert_ne!(game.object(subject).unwrap().kind, ObjectKind::Card);
                let zone = if mode == 2 {
                    Zone::Stack
                } else {
                    Zone::Battlefield
                };
                assert_eq!(game.object(subject).unwrap().zone, zone);
                let actual_types: std::collections::BTreeSet<_> = game
                    .current_card_types(subject)
                    .unwrap()
                    .iter()
                    .map(|t| t.to_string())
                    .collect();
                assert_eq!(actual_types, types.iter().map(|t| t.to_string()).collect());
                for queried in cr_audit_complete_card_type_inventory() {
                    let before = game.player(actor).unwrap().life;
                    game.stack.push(StackEntry::ability(
                        observer,
                        actor,
                        vec![Effect::gain_life(Value::Count(
                            ObjectFilter::specific(subject)
                                .in_zone(zone)
                                .with_type(*queried),
                        ))],
                    ));
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    let actual = game.player(actor).unwrap().life - before;
                    let expected = i32::from(types.contains(queried));
                    if actual != expected {
                        discrepancies.push(format!("actor={actor:?}, types={types:?}, mode={mode}, query={queried:?}: count={actual}, required={expected}"));
                    }
                    checks += 1;
                }
                fixtures += 1;
            }
        }
    }
    assert_eq!((fixtures, checks), (52, 780));
    assert!(
        discrepancies.is_empty(),
        "CR 205.2c: noncard token objects and spell copies retain their card types and satisfy typed effects: {discrepancies:#?}"
    );
}

#[test]
fn cr_205_4a_b_all_supertype_combinations_are_independent_of_type_and_subtype_changes() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::continuous::{EffectTarget, Modification};
    use ironsmith::effects::ApplyContinuousEffect;
    use ironsmith::{
        CardId, CardType, Effect, ObjectFilter, StackEntry, Subtype, Supertype, Until, Value, Zone,
    };
    use std::collections::BTreeSet;
    let supertypes = [
        Supertype::Basic,
        Supertype::Legendary,
        Supertype::Ongoing,
        Supertype::Snow,
        Supertype::World,
    ];
    let mut cases = 0;
    let mut type_queries = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for mask in 0..32 {
            for mode in 0..16 {
                let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                let initial: Vec<_> = supertypes
                    .iter()
                    .enumerate()
                    .filter(|(index, _)| mask & (1 << index) != 0)
                    .map(|(_, s)| *s)
                    .collect();
                let definition =
                    CardDefinitionBuilder::new(CardId::new(), "Independent supertype subject")
                        .card_types(vec![CardType::Land, CardType::Creature])
                        .subtypes(vec![Subtype::Forest, Subtype::Dryad])
                        .supertypes(initial.clone())
                        .power_toughness(ironsmith::PowerToughness::fixed(3, 4))
                        .build();
                let subject =
                    game.create_object_from_definition(&definition, actor, Zone::Battlefield);
                let mut expected_super = initial.clone();
                let mut expected_types = vec![CardType::Land, CardType::Creature];
                let mut expected_sub = vec![Subtype::Forest, Subtype::Dryad];
                let modification = match mode {
                    0..5 => {
                        let add = supertypes[mode];
                        if !expected_super.contains(&add) {
                            expected_super.push(add);
                        }
                        Modification::AddSupertypes(vec![add])
                    }
                    5..10 => {
                        let remove = supertypes[mode - 5];
                        expected_super.retain(|s| *s != remove);
                        Modification::RemoveSupertypes(vec![remove])
                    }
                    10 => {
                        expected_types = vec![CardType::Artifact];
                        expected_sub.clear();
                        Modification::SetCardTypes(vec![CardType::Artifact])
                    }
                    11 => {
                        expected_types.push(CardType::Artifact);
                        Modification::AddCardTypes(vec![CardType::Artifact])
                    }
                    12 => {
                        expected_types = vec![CardType::Land];
                        expected_sub = vec![Subtype::Forest];
                        Modification::RemoveCardTypes(vec![CardType::Creature])
                    }
                    13 => {
                        expected_sub = vec![Subtype::Forest, Subtype::Goblin];
                        Modification::SetSubtypes(vec![Subtype::Goblin])
                    }
                    14 => {
                        expected_sub.push(Subtype::Goblin);
                        Modification::AddSubtypes(vec![Subtype::Goblin])
                    }
                    _ => {
                        expected_sub = vec![Subtype::Forest];
                        Modification::RemoveSubtypes(vec![Subtype::Dryad])
                    }
                };
                ApplyContinuousEffect::new(
                    EffectTarget::Specific(subject),
                    modification,
                    Until::EndOfTurn,
                )
                .execute(&mut game, &mut EffectContext::new_default(subject, actor))
                .unwrap();
                let names = |values: Vec<Supertype>| {
                    values
                        .iter()
                        .map(|s| s.to_string())
                        .collect::<BTreeSet<_>>()
                };
                assert_eq!(
                    names(game.current_supertypes(subject).unwrap()),
                    names(expected_super.clone()),
                    "CR 205.4a/b: actor={actor:?}, mask={mask}, mode={mode}"
                );
                assert_eq!(
                    game.current_card_types(subject)
                        .unwrap()
                        .iter()
                        .map(|s| s.to_string())
                        .collect::<BTreeSet<_>>(),
                    expected_types.iter().map(|s| s.to_string()).collect()
                );
                assert_eq!(
                    game.current_subtypes(subject)
                        .unwrap()
                        .iter()
                        .map(|s| s.to_string())
                        .collect::<BTreeSet<_>>(),
                    expected_sub.iter().map(|s| s.to_string()).collect()
                );
                for queried in supertypes {
                    let before = game.player(actor).unwrap().life;
                    game.stack.push(StackEntry::ability(
                        subject,
                        actor,
                        vec![Effect::gain_life(Value::Count(
                            ObjectFilter::specific(subject)
                                .in_zone(Zone::Battlefield)
                                .with_supertype(queried),
                        ))],
                    ));
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    assert_eq!(
                        game.player(actor).unwrap().life - before,
                        i32::from(expected_super.contains(&queried)),
                        "actual supertype-filtered effect: actor={actor:?}, mask={mask}, mode={mode}, query={queried:?}"
                    );
                    type_queries += 1;
                }
                cases += 1;
            }
        }
    }
    assert_eq!((cases, type_queries), (1024, 5120));
}

fn cr_audit_cast_with_plain_pool(
    cost: ironsmith::ManaCost,
    pool: [u32; 6],
    actor: PlayerId,
    expected_payment: Option<u32>,
    alternative: usize,
) -> Vec<String> {
    cr_audit_cast_with_pool_and_life(cost, pool, actor, expected_payment, alternative, 20, 0)
}

fn cr_audit_cast_with_pool_and_life(
    cost: ironsmith::ManaCost,
    pool: [u32; 6],
    actor: PlayerId,
    expected_payment: Option<u32>,
    alternative: usize,
    starting_life: i32,
    expected_life_payment: u32,
) -> Vec<String> {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::{CardId, CardType, Effect, LegalAction, ManaSymbol, Phase, Zone};
    struct ChooseHalf(usize);
    impl DecisionMaker for ChooseHalf {
        fn decide_options(&mut self, _game: &GameState, ctx: &SelectOptionsContext) -> Vec<usize> {
            if ctx.description.starts_with("Choose how to pay pip ") {
                return vec![ctx.options[self.0].index];
            }
            ctx.options
                .iter()
                .filter(|o| o.legal)
                .take(ctx.min)
                .map(|o| o.index)
                .collect()
        }
    }
    let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], starting_life);
    game.turn.active_player = actor;
    game.turn.priority_player = Some(actor);
    game.turn.phase = Phase::FirstMain;
    let definition = CardDefinitionBuilder::new(CardId::new(), "Mana symbol payment subject")
        .card_types(vec![CardType::Sorcery])
        .mana_cost(cost.clone())
        .with_spell_effect(vec![Effect::gain_life(2)])
        .build();
    let card = game.create_object_from_definition(&definition, actor, Zone::Hand);
    let symbols = [
        ManaSymbol::White,
        ManaSymbol::Blue,
        ManaSymbol::Black,
        ManaSymbol::Red,
        ManaSymbol::Green,
        ManaSymbol::Colorless,
    ];
    for (symbol, amount) in symbols.into_iter().zip(pool) {
        game.player_mut(actor)
            .unwrap()
            .mana_pool
            .add(symbol, amount);
    }
    let action = ironsmith::compute_legal_actions(&game, actor)
        .unwrap()
        .into_iter()
        .find(|a| matches!(a, LegalAction::CastSpell { spell_id, .. } if *spell_id == card));
    let mut discrepancies = Vec::new();
    if action.is_none() && expected_payment.is_some() {
        discrepancies.push(format!(
            "actor={actor:?}, cost={cost:?}, pool={pool:?}: a payable cast is unavailable"
        ));
    }
    let Some(required) = expected_payment else {
        if let Some(action) = action {
            use ironsmith::{PriorityLoopState, PriorityResponse};
            let mut state = PriorityLoopState::new(game.players_in_game());
            let mut queue = ironsmith::triggers::TriggerQueue::new();
            let mut dm = ChooseHalf(
                if cost
                    .pips()
                    .iter()
                    .any(|p| p.len() > 1 && p.contains(&ManaSymbol::Generic(2)))
                {
                    1
                } else {
                    alternative
                },
            );
            let before = game.player(actor).unwrap().mana_pool.clone();
            let stable = game.object(card).unwrap().stable_id;
            let mut result = ironsmith::game_loop::apply_priority_response_with_dm(
                &mut game,
                &mut queue,
                &mut state,
                &PriorityResponse::PriorityAction(action),
                &mut dm,
            );
            for _ in 0..32 {
                if result.is_err()
                    || (state.pending_cast.is_none()
                        && state.pending_activation.is_none()
                        && state.pending_method_selection.is_none())
                {
                    break;
                }
                let context = match &result {
                    Ok(ironsmith::GameProgress::NeedsDecisionCtx(context)) => context.clone(),
                    other => panic!("unaffordable payment has no native continuation: {other:?}"),
                };
                result = ironsmith::game_loop::apply_decision_context_with_dm(
                    &mut game, &mut queue, &mut state, &context, &mut dm,
                );
            }
            assert!(
                state.pending_cast.is_none(),
                "unaffordable attempt must terminate after payment cancellation"
            );
            if !game.stack.is_empty()
                || game.player(actor).unwrap().mana_pool != before
                || game.player(actor).unwrap().life != starting_life
                || game
                    .find_object_by_stable_id(stable)
                    .and_then(|id| game.object(id))
                    .is_none_or(|o| o.zone != Zone::Hand)
            {
                discrepancies.push(format!("actor={actor:?}, cost={cost:?}, pool={pool:?}: unaffordable native attempt completed or failed to restore its resources; result={result:?}, stack={:?}", game.stack));
            }
        } else {
            assert!(game.stack.is_empty());
            assert_eq!(game.object(card).unwrap().zone, Zone::Hand);
            assert_eq!(
                game.player(actor).unwrap().mana_pool.total(),
                pool.iter().sum::<u32>()
            );
        }
        return discrepancies;
    };
    let Some(action) = action else {
        return discrepancies;
    };
    let stack = audit_finish_cost_rule_cast_with(&mut game, action, &mut ChooseHalf(alternative));
    assert_eq!(game.stack.len(), 1);
    let object = game.object(stack).unwrap();
    assert_eq!(
        object.mana_cost.as_ref().map(|v| v.pips()),
        Some(cost.pips())
    );
    let stable = object.stable_id;
    let remaining = &game.player(actor).unwrap().mana_pool;
    let unspent = [
        remaining.white,
        remaining.blue,
        remaining.black,
        remaining.red,
        remaining.green,
        remaining.colorless,
    ];
    for (index, symbol) in symbols.iter().enumerate() {
        let mandatory = cost
            .pips()
            .iter()
            .filter(|pip| pip.as_slice() == [*symbol])
            .count() as u32;
        assert!(
            pool[index] - unspent[index] >= mandatory,
            "each mandatory colored/colorless requirement must consume the matching mana"
        );
    }
    let paid = pool.iter().sum::<u32>() - game.player(actor).unwrap().mana_pool.total();
    assert_eq!(
        paid, required,
        "native mana consumption: actor={actor:?}, cost={cost:?}, pool={pool:?}"
    );
    assert_eq!(
        game.player(actor).unwrap().life,
        starting_life - expected_life_payment as i32
    );
    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
    assert_eq!(
        game.player(actor).unwrap().life,
        starting_life - expected_life_payment as i32 + 2
    );
    assert!(game.stack.is_empty());
    let resolved = game.find_object_by_stable_id(stable).unwrap();
    assert_eq!(game.object(resolved).unwrap().zone, Zone::Graveyard);
    discrepancies
}

#[test]
fn cr_107_4a_c_202_1a_single_colored_and_colorless_costs_require_the_matching_mana_type() {
    use ironsmith::{ManaCost, ManaSymbol};
    let symbols = [
        ManaSymbol::White,
        ManaSymbol::Blue,
        ManaSymbol::Black,
        ManaSymbol::Red,
        ManaSymbol::Green,
        ManaSymbol::Colorless,
    ];
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for (required_index, required) in symbols.into_iter().enumerate() {
            for offered_index in 0..6 {
                for amount in 0..3 {
                    let mut pool = [0; 6];
                    pool[offered_index] = amount;
                    let payment = (required_index == offered_index && amount >= 1).then_some(1);
                    discrepancies.extend(cr_audit_cast_with_plain_pool(
                        ManaCost::from_symbols(vec![required]),
                        pool,
                        actor,
                        payment,
                        0,
                    ));
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 216);
    assert!(
        discrepancies.is_empty(),
        "CR 107.4a/c and 202.1a: colored/colorless requirements are type-specific: {discrepancies:#?}"
    );
}

#[test]
fn cr_107_4b_d_generic_and_zero_casting_costs_accept_every_mana_type() {
    use ironsmith::{ManaCost, ManaSymbol};
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for required in 0..4 {
            for offered_index in 0..6 {
                for amount in 0..4 {
                    let mut pool = [0; 6];
                    pool[offered_index] = amount;
                    let payment = (amount >= required).then_some(required);
                    discrepancies.extend(cr_audit_cast_with_plain_pool(
                        ManaCost::from_symbols(vec![ManaSymbol::Generic(required as u8)]),
                        pool,
                        actor,
                        payment,
                        0,
                    ));
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 192);
    assert!(
        discrepancies.is_empty(),
        "CR 107.4b/d: generic mana is payable with any mana type and zero needs no resources: {discrepancies:#?}"
    );
}

#[test]
fn cr_202_1a_colored_colorless_and_generic_parts_of_one_cost_are_all_paid() {
    use ironsmith::{ManaCost, ManaSymbol};
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    let colored = [
        ManaSymbol::White,
        ManaSymbol::Blue,
        ManaSymbol::Black,
        ManaSymbol::Red,
        ManaSymbol::Green,
    ];
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for (index, symbol) in colored.into_iter().enumerate() {
            for matching in 0..3 {
                for colorless in 0..3 {
                    for other in 0..3 {
                        let mut pool = [0; 6];
                        pool[index] = matching;
                        pool[5] = colorless;
                        pool[(index + 1) % 5] = other;
                        let payable =
                            matching >= 1 && colorless >= 1 && matching + colorless + other >= 3;
                        discrepancies.extend(cr_audit_cast_with_plain_pool(
                            ManaCost::from_symbols(vec![
                                symbol,
                                ManaSymbol::Colorless,
                                ManaSymbol::Generic(1),
                            ]),
                            pool,
                            actor,
                            payable.then_some(3),
                            0,
                        ));
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 270);
    assert!(
        discrepancies.is_empty(),
        "CR 202.1a: generic mana cannot replace an unsatisfied colored or colorless component of the same cost: {discrepancies:#?}"
    );
}

#[test]
fn cr_107_4e_every_colored_twobrid_and_colorless_hybrid_can_use_either_half() {
    use ironsmith::{ManaCost, ManaSymbol};
    let symbols = [
        ManaSymbol::White,
        ManaSymbol::Blue,
        ManaSymbol::Black,
        ManaSymbol::Red,
        ManaSymbol::Green,
    ];
    let mut costs = Vec::new();
    for first in 0..5 {
        for second in (first + 1)..5 {
            costs.push((symbols[first], symbols[second]));
        }
        costs.push((symbols[first], ManaSymbol::Generic(2)));
        costs.push((symbols[first], ManaSymbol::Colorless));
    }
    assert_eq!(costs.len(), 20);
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for (first, second) in &costs {
            for offered_index in 0..6 {
                for amount in 0..4 {
                    let offered = if offered_index < 5 {
                        symbols[offered_index]
                    } else {
                        ManaSymbol::Colorless
                    };
                    let mut pool = [0; 6];
                    pool[offered_index] = amount;
                    let payment = if offered == *first && amount >= 1 {
                        Some((1, 0))
                    } else if offered == *second && amount >= 1 {
                        Some((1, 1))
                    } else if *second == ManaSymbol::Generic(2) && amount >= 2 {
                        Some((2, 1))
                    } else {
                        None
                    };
                    discrepancies.extend(cr_audit_cast_with_plain_pool(
                        ManaCost::from_pips(vec![vec![*first, *second]]),
                        pool,
                        actor,
                        payment.map(|p| p.0),
                        payment.map_or(0, |p| p.1),
                    ));
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 960);
    assert!(
        discrepancies.is_empty(),
        "CR 107.4e: all ten colored hybrids, five twobrid and five colorless/colored hybrids admit either printed alternative: {discrepancies:#?}"
    );
}

#[test]
fn cr_107_4f_all_fifteen_phyrexian_symbols_allow_their_colors_or_two_life() {
    use ironsmith::{ManaCost, ManaSymbol};
    let colors = [
        ManaSymbol::White,
        ManaSymbol::Blue,
        ManaSymbol::Black,
        ManaSymbol::Red,
        ManaSymbol::Green,
    ];
    let mut forms = Vec::new();
    for first in 0..5 {
        forms.push(vec![colors[first], ManaSymbol::Life(2)]);
        for second in (first + 1)..5 {
            forms.push(vec![colors[first], colors[second], ManaSymbol::Life(2)]);
        }
    }
    assert_eq!(forms.len(), 15);
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for form in &forms {
            for mana_index in 0..6 {
                for amount in 0..2 {
                    for life in [1, 3] {
                        let offered = if mana_index < 5 {
                            colors[mana_index]
                        } else {
                            ManaSymbol::Colorless
                        };
                        let mut pool = [0; 6];
                        pool[mana_index] = amount;
                        let colored_half = form
                            .iter()
                            .position(|s| *s == offered)
                            .filter(|_| amount >= 1);
                        let choice = colored_half.unwrap_or(form.len() - 1);
                        let mana_payment = if colored_half.is_some() {
                            Some(1)
                        } else {
                            (life >= 2).then_some(0)
                        };
                        let life_payment = if colored_half.is_some() { 0 } else { 2 };
                        discrepancies.extend(cr_audit_cast_with_pool_and_life(
                            ManaCost::from_pips(vec![form.clone()]),
                            pool,
                            actor,
                            mana_payment,
                            choice,
                            life,
                            life_payment,
                        ));
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 720);
    assert!(
        discrepancies.is_empty(),
        "CR 107.4f: every colored/hybrid Phyrexian symbol is payable with any printed component color or two life, never insufficient life or colorless mana alone: {discrepancies:#?}"
    );
}

#[test]
fn cr_107_4e_f_hybrid_and_phyrexian_symbols_keep_all_component_colors_in_every_zone() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::{CardId, CardType, Color, ColorSet, ManaCost, ManaSymbol, StackEntry, Zone};
    let components = [
        (ManaSymbol::White, Color::White),
        (ManaSymbol::Blue, Color::Blue),
        (ManaSymbol::Black, Color::Black),
        (ManaSymbol::Red, Color::Red),
        (ManaSymbol::Green, Color::Green),
    ];
    let mut forms = Vec::new();
    for first in 0..5 {
        let single = ColorSet::new().with(components[first].1);
        for second in (first + 1)..5 {
            let both = single.with(components[second].1);
            forms.push((vec![components[first].0, components[second].0], both));
            forms.push((
                vec![
                    components[first].0,
                    components[second].0,
                    ManaSymbol::Life(2),
                ],
                both,
            ));
        }
        for alternative in [
            ManaSymbol::Generic(2),
            ManaSymbol::Colorless,
            ManaSymbol::Life(2),
        ] {
            forms.push((vec![components[first].0, alternative], single));
        }
    }
    assert_eq!(forms.len(), 35);
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for (form, expected) in &forms {
            for zone in [
                Zone::Battlefield,
                Zone::Hand,
                Zone::Library,
                Zone::Graveyard,
                Zone::Exile,
                Zone::Command,
                Zone::Stack,
                Zone::Ante,
                Zone::OutsideGame,
            ] {
                let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                let definition =
                    CardDefinitionBuilder::new(CardId::new(), "Composite mana symbol colors")
                        .card_types(vec![CardType::Creature])
                        .mana_cost(ManaCost::from_pips(vec![form.clone()]))
                        .power_toughness(ironsmith::PowerToughness::fixed(3, 4))
                        .build();
                let subject = game.create_object_from_definition(&definition, actor, zone);
                if zone == Zone::Stack {
                    game.stack.push(StackEntry::new(subject, actor));
                }
                assert_eq!(
                    game.current_colors(subject),
                    Some(*expected),
                    "CR 107.4e/f: actor={actor:?}, form={form:?}, zone={zone:?}"
                );
                cases += 1;
            }
        }
    }
    assert_eq!(cases, 630);
}

#[test]
fn cr_107_4h_118_7g_a_snow_reduction_cannot_complete_a_cast_without_required_snow_mana() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::static_abilities::{CostReduction, CostReductionManaCost};
    use ironsmith::{
        Ability, CardId, CardType, Effect, LegalAction, ManaCost, ManaSymbol, ObjectFilter, Phase,
        StaticAbility, Supertype, TotalCost, Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for generic in [0, 2] {
            for snow_source in [false, true] {
                for reducer in 0..3 {
                    let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                    game.turn.active_player = actor;
                    game.turn.priority_player = Some(actor);
                    game.turn.phase = Phase::FirstMain;
                    let mut producer = CardDefinitionBuilder::new(
                        CardId::new(),
                        "Provenance-bearing colorless mana source",
                    )
                    .card_types(vec![CardType::Artifact])
                    .with_ability(Ability::mana(
                        TotalCost::free(),
                        vec![ManaSymbol::Colorless],
                    ));
                    if snow_source {
                        producer = producer.supertypes(vec![Supertype::Snow]);
                    }
                    let producer = game.create_object_from_definition(
                        &producer.build(),
                        actor,
                        Zone::Battlefield,
                    );
                    ironsmith::special_actions::perform_activate_mana_ability(
                        &mut game,
                        actor,
                        producer,
                        0,
                        &mut ironsmith::decision::SelectFirstDecisionMaker,
                    )
                    .unwrap();
                    game.player_mut(actor).unwrap().mana_pool.colorless += 2;
                    game.player_mut(actor).unwrap().mana_pool.green = 1;
                    if reducer != 0 {
                        let mut filter = ObjectFilter::default();
                        filter.cast_by = Some(PlayerFilter::You);
                        let reduction = if reducer == 1 {
                            StaticAbility::new(CostReduction::new(
                                filter,
                                ironsmith::Value::Fixed(1),
                            ))
                        } else {
                            StaticAbility::new(CostReductionManaCost::new(
                                filter,
                                ManaCost::from_symbols(vec![ManaSymbol::Snow]),
                            ))
                        };
                        let definition = CardDefinitionBuilder::new(
                            CardId::new(),
                            "One-mana generic price reduction",
                        )
                        .card_types(vec![CardType::Enchantment])
                        .with_ability(Ability::static_ability(reduction))
                        .build();
                        game.create_object_from_definition(&definition, actor, Zone::Battlefield);
                    }
                    let mut symbols = vec![ManaSymbol::Snow, ManaSymbol::Green];
                    if generic != 0 {
                        symbols.push(ManaSymbol::Generic(generic));
                    }
                    let cost = ManaCost::from_symbols(symbols);
                    let definition = CardDefinitionBuilder::new(
                        CardId::new(),
                        "Spell requiring actual snow-produced mana",
                    )
                    .card_types(vec![CardType::Sorcery])
                    .mana_cost(cost.clone())
                    .with_spell_effect(vec![Effect::gain_life(2)])
                    .build();
                    let card = game.create_object_from_definition(&definition, actor, Zone::Hand);
                    let action = ironsmith::compute_legal_actions(&game, actor).unwrap().into_iter()
                        .find(|a| matches!(a, LegalAction::CastSpell { spell_id, .. } if *spell_id == card));
                    let mut expected_symbols = vec![ManaSymbol::Snow, ManaSymbol::Green];
                    let expected_generic = if reducer == 0 {
                        generic
                    } else {
                        generic.saturating_sub(1)
                    };
                    if expected_generic != 0 {
                        expected_symbols.push(ManaSymbol::Generic(expected_generic));
                    }
                    let quote = ironsmith::decision::calculate_effective_mana_cost(
                        &game,
                        actor,
                        game.object(card).unwrap(),
                        &cost,
                    );
                    let canonical = |c: &ManaCost| {
                        let mut p = c.pips().to_vec();
                        p.sort_by_key(|v| format!("{v:?}"));
                        p
                    };
                    if canonical(&quote) != canonical(&ManaCost::from_symbols(expected_symbols)) {
                        discrepancies.push(format!("wrong quote actor={actor:?}, generic={generic}, snow={snow_source}, reducer={reducer}: {quote:?}"));
                    }
                    if let Some(action) = action {
                        let stack = audit_finish_cost_rule_cast(&mut game, action);
                        assert_eq!(game.stack.len(), 1);
                        assert_eq!(
                            game.object(stack)
                                .unwrap()
                                .mana_cost
                                .as_ref()
                                .unwrap()
                                .pips(),
                            cost.pips()
                        );
                        let spent = 4 - game.player(actor).unwrap().mana_pool.total();
                        if !snow_source || spent != expected_generic as u32 + 2 {
                            discrepancies.push(format!("completed cast actor={actor:?}, generic={generic}, snow={snow_source}, reducer={reducer}: spent {spent}; required {} including one snow-produced unit", expected_generic as u32 + 2));
                        }
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        assert_eq!(game.player(actor).unwrap().life, 22);
                    } else {
                        if snow_source {
                            discrepancies.push(format!("missing payable cast actor={actor:?}, generic={generic}, reducer={reducer}"));
                        }
                        assert_eq!(game.player(actor).unwrap().mana_pool.total(), 4);
                        assert!(game.stack.is_empty());
                    }
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 24);
    assert!(
        discrepancies.is_empty(),
        "CR 107.4h / 118.7g: a snow-symbol reduction reduces only generic mana; required snow-produced mana still must actually be paid: {discrepancies:#?}"
    );
}

#[test]
fn cr_208_2a_unchosen_player_scalars_are_zero_operands_in_a_cda() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::{
        Ability, CardId, CardType, ObjectFilter, PowerToughness, PtValue, StackEntry,
        StaticAbility, Value, Zone,
    };
    let mut cases = 0;
    let mut observations = 0;
    let mut discrepancies = Vec::new();
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        let opponent = PlayerId::from_index(1 - actor.0);
        for zone in [
            Zone::Library,
            Zone::Hand,
            Zone::Battlefield,
            Zone::Graveyard,
            Zone::Stack,
            Zone::Exile,
            Zone::Command,
            Zone::Ante,
            Zone::OutsideGame,
        ] {
            for operand in 0..5 {
                let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                game.player_mut(opponent).unwrap().life = 11;
                for index in 0..3 {
                    let card = CardDefinitionBuilder::new(
                        CardId::new(),
                        format!("Chosen player hand control {index}"),
                    )
                    .card_types(vec![CardType::Artifact])
                    .build();
                    game.create_object_from_definition(&card, opponent, Zone::Hand);
                }
                for index in 0..2 {
                    let card = CardDefinitionBuilder::new(
                        CardId::new(),
                        format!("Chosen player creature control {index}"),
                    )
                    .card_types(vec![CardType::Creature])
                    .power_toughness(PowerToughness::fixed(3, 4))
                    .build();
                    game.create_object_from_definition(&card, opponent, Zone::Battlefield);
                }
                let (value, known) = match operand {
                    0 => (Value::LifeTotal(PlayerFilter::ChosenPlayer), 11),
                    1 => (Value::CardsInHand(PlayerFilter::ChosenPlayer), 3),
                    2 => (Value::StartingLifeTotal(PlayerFilter::ChosenPlayer), 20),
                    3 => (Value::HalfLifeTotalRoundedUp(PlayerFilter::ChosenPlayer), 6),
                    _ => (
                        Value::Count(
                            ObjectFilter::creature().controlled_by(PlayerFilter::ChosenPlayer),
                        ),
                        2,
                    ),
                };
                let power = Value::Add(Box::new(Value::Fixed(1)), Box::new(value.clone()));
                let toughness = Value::Add(
                    Box::new(Value::Fixed(2)),
                    Box::new(Value::Scaled(Box::new(value), 2)),
                );
                let definition = CardDefinitionBuilder::new(
                    CardId::new(),
                    "CDA using an as-yet-unchosen player's number",
                )
                .card_types(vec![CardType::Creature])
                .power_toughness(PowerToughness::new(
                    PtValue::StarPlus(1),
                    PtValue::StarPlus(2),
                ))
                .with_ability(Ability::static_ability(
                    StaticAbility::characteristic_defining_pt(power, toughness),
                ))
                .build();
                let source = game.create_object_from_definition(&definition, actor, zone);
                if zone == Zone::Stack {
                    game.stack.push(StackEntry::new(source, actor));
                }
                assert_eq!(game.chosen_player(source), None);
                for chosen in [false, true] {
                    if chosen {
                        game.set_chosen_player(source, opponent);
                    }
                    let n = if chosen { known } else { 0 };
                    let expected = (Some(1 + n), Some(2 + 2 * n));
                    let actual = (game.current_power(source), game.current_toughness(source));
                    if actual != expected {
                        discrepancies.push(format!("actor={actor:?}, zone={zone:?}, operand={operand}, chosen={chosen}: {actual:?}, required {expected:?}"));
                    }
                    observations += 1;
                }
                cases += 1;
            }
        }
    }
    assert_eq!((cases, observations), (90, 180));
    assert!(
        discrepancies.is_empty(),
        "CR 208.2a: a CDA substitutes zero for each undeterminable numeric operand, preserving the rest of its arithmetic, and updates after the player is chosen: {discrepancies:#?}"
    );
}

#[test]
fn cr_208_2a_unchosen_player_cdas_still_supply_values_to_resolving_numeric_readers() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, Effect, ObjectFilter, PowerToughness, PtValue,
        StackEntry, StaticAbility, Value, Zone,
    };
    let mut fixtures = 0;
    let mut reads = 0;
    let mut discrepancies = Vec::new();
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        let opponent = PlayerId::from_index(1 - actor.0);
        for zone in [
            Zone::Library,
            Zone::Hand,
            Zone::Battlefield,
            Zone::Graveyard,
            Zone::Stack,
            Zone::Exile,
            Zone::Command,
            Zone::Ante,
            Zone::OutsideGame,
        ] {
            for scalar in [false, true] {
                for chosen in [false, true] {
                    for reader_index in 0..5 {
                        // Each reader gets a fresh game: an evaluation error can
                        // legitimately retain its own pending stack entry. The
                        // regression is the failure to resolve a defined value,
                        // not an assumption about error cleanup.
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        game.player_mut(opponent).unwrap().life = 11;
                        for index in 0..2 {
                            let creature = CardDefinitionBuilder::new(
                                CardId::new(),
                                format!("Numeric reader count control {index}"),
                            )
                            .card_types(vec![CardType::Creature])
                            .power_toughness(PowerToughness::fixed(3, 4))
                            .build();
                            game.create_object_from_definition(
                                &creature,
                                opponent,
                                Zone::Battlefield,
                            );
                        }
                        let value = if scalar {
                            Value::LifeTotal(PlayerFilter::ChosenPlayer)
                        } else {
                            Value::Count(
                                ObjectFilter::creature().controlled_by(PlayerFilter::ChosenPlayer),
                            )
                        };
                        let definition =
                            CardDefinitionBuilder::new(CardId::new(), "CDA numeric reader subject")
                                .card_types(vec![CardType::Creature])
                                .power_toughness(PowerToughness::new(
                                    PtValue::StarPlus(1),
                                    PtValue::StarPlus(2),
                                ))
                                .with_ability(Ability::static_ability(
                                    StaticAbility::characteristic_defining_pt(
                                        Value::Add(
                                            Box::new(Value::Fixed(1)),
                                            Box::new(value.clone()),
                                        ),
                                        Value::Add(
                                            Box::new(Value::Fixed(2)),
                                            Box::new(Value::Scaled(Box::new(value), 2)),
                                        ),
                                    ),
                                ))
                                .build();
                        let source = game.create_object_from_definition(&definition, actor, zone);
                        if zone == Zone::Stack {
                            game.stack.push(StackEntry::new(source, actor));
                        }
                        if chosen {
                            game.set_chosen_player(source, opponent);
                        }
                        let n = if !chosen {
                            0
                        } else if scalar {
                            11
                        } else {
                            2
                        };
                        let (reader, expected) = match reader_index {
                            0 => (Value::SourcePower, 1 + n),
                            1 => (Value::SourceToughness, 2 + 2 * n),
                            2 => (
                                Value::PowerOf(Box::new(ChooseSpec::SpecificObject(source))),
                                1 + n,
                            ),
                            3 => (
                                Value::ToughnessOf(Box::new(ChooseSpec::SpecificObject(source))),
                                2 + 2 * n,
                            ),
                            _ => (
                                Value::BasePowerOf(Box::new(ChooseSpec::SpecificObject(source))),
                                1 + n,
                            ),
                        };
                        game.stack.push(StackEntry::ability(
                            source,
                            actor,
                            vec![Effect::gain_life(reader.clone())],
                        ));
                        let result = ironsmith::game_loop::resolve_stack_entry(&mut game);
                        let actual = game.player(actor).unwrap().life - 20;
                        if result.is_err() || actual != expected {
                            discrepancies.push(format!("actor={actor:?}, zone={zone:?}, scalar={scalar}, chosen={chosen}, reader={reader:?}: result={result:?}, gained={actual}, required {expected}"));
                        }
                        if result.is_ok() {
                            assert_eq!(
                                game.stack.len(),
                                usize::from(zone == Zone::Stack),
                                "successful reader consumes only its own ability entry"
                            );
                        }
                        reads += 1;
                    }
                }
                fixtures += 1;
            }
        }
    }
    assert_eq!((fixtures, reads), (36, 360));
    assert!(
        discrepancies.is_empty(),
        "CR 208.2a / 107.2: an unavailable chosen-player scalar contributes zero inside the CDA; later readers must receive the defined arithmetic result: {discrepancies:#?}"
    );
}

#[test]
fn cr_208_2a_613_4a_pt_cdas_stop_after_ability_loss_and_return_at_cleanup() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::continuous::{EffectTarget, Modification};
    use ironsmith::effects::ApplyContinuousEffect;
    use ironsmith::{
        Ability, CardId, CardType, PowerToughness, PtValue, StackEntry, StaticAbility, Until,
        Value, Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for zone in [
            Zone::Library,
            Zone::Hand,
            Zone::Battlefield,
            Zone::Graveyard,
            Zone::Stack,
            Zone::Exile,
            Zone::Command,
            Zone::Ante,
        ] {
            let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
            let definition = CardDefinitionBuilder::new(CardId::new(), "Removable P/T CDA")
                .card_types(vec![CardType::Creature])
                .power_toughness(PowerToughness::new(PtValue::Star, PtValue::Star))
                .with_ability(Ability::static_ability(
                    StaticAbility::characteristic_defining_pt(Value::Fixed(5), Value::Fixed(7)),
                ))
                .build();
            let source = game.create_object_from_definition(&definition, actor, zone);
            if zone == Zone::Stack {
                game.stack.push(StackEntry::new(source, actor));
            }
            assert_eq!(
                (game.current_power(source), game.current_toughness(source)),
                (Some(5), Some(7))
            );
            ApplyContinuousEffect::new(
                EffectTarget::Specific(source),
                Modification::RemoveAllAbilities,
                Until::EndOfTurn,
            )
            .execute(&mut game, &mut EffectContext::new_default(source, actor))
            .unwrap();
            let current = game.current_characteristics(source).unwrap();
            assert!(
                current.abilities.is_empty(),
                "the layer-6 removal actually applies in {zone:?}"
            );
            let actual = (game.current_power(source), game.current_toughness(source));
            if actual != (Some(0), Some(0)) {
                discrepancies.push(format!("actor={actor:?}, zone={zone:?}: after losing its only defining ability, got {actual:?}, required 0/0"));
            }
            ironsmith::turn::execute_cleanup_step(&mut game);
            assert_eq!(
                (game.current_power(source), game.current_toughness(source)),
                (Some(5), Some(7)),
                "cleanup restores the defining ability in {zone:?}"
            );
            cases += 1;
        }
    }
    assert_eq!(cases, 16);
    assert!(
        discrepancies.is_empty(),
        "CR 208.2a / 613.4a: an ability removed in layer 6 cannot define P/T in layer 7a: {discrepancies:#?}"
    );
}

#[test]
fn cr_613_4a_cda_pt_precedes_base_setting_modifiers_counters_and_switches() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::continuous::{EffectTarget, Modification, PtSublayer};
    use ironsmith::effects::ApplyContinuousEffect;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, CounterType, Effect, PowerToughness, PtValue,
        StackEntry, StaticAbility, Until, Value, Zone,
    };
    let mut cases = 0;
    let mut reads = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for setting in [false, true] {
            for modifying in [false, true] {
                for counters in [0, 2] {
                    for switches in 0..3 {
                        for reverse in [false, true] {
                            let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                            let definition = CardDefinitionBuilder::new(
                                CardId::new(),
                                "CDA layer-order subject",
                            )
                            .card_types(vec![CardType::Creature])
                            .power_toughness(PowerToughness::new(PtValue::Star, PtValue::Star))
                            .with_ability(Ability::static_ability(
                                StaticAbility::characteristic_defining_pt(
                                    Value::Fixed(5),
                                    Value::Fixed(7),
                                ),
                            ))
                            .build();
                            let source = game.create_object_from_definition(
                                &definition,
                                actor,
                                Zone::Battlefield,
                            );
                            let mut modifications = vec![];
                            if setting {
                                modifications.push(Modification::SetPowerToughness {
                                    power: Value::Fixed(2),
                                    toughness: Value::Fixed(4),
                                    sublayer: PtSublayer::Setting,
                                });
                            }
                            if modifying {
                                modifications.push(Modification::ModifyPowerToughness {
                                    power: 3,
                                    toughness: -1,
                                });
                            }
                            for _ in 0..switches {
                                modifications.push(Modification::SwitchPowerToughness);
                            }
                            if reverse {
                                modifications.reverse();
                            }
                            for modification in modifications {
                                ApplyContinuousEffect::new(
                                    EffectTarget::Specific(source),
                                    modification,
                                    Until::EndOfTurn,
                                )
                                .execute(&mut game, &mut EffectContext::new_default(source, actor))
                                .unwrap();
                            }
                            if counters != 0 {
                                game.add_counters(source, CounterType::PlusOnePlusOne, counters)
                                    .unwrap();
                            }
                            let base = if setting { (2, 4) } else { (5, 7) };
                            let mut current = (
                                base.0 + if modifying { 3 } else { 0 } + counters as i32,
                                base.1 + if modifying { -1 } else { 0 } + counters as i32,
                            );
                            if switches % 2 == 1 {
                                current = (current.1, current.0);
                            }
                            let chars = game.current_characteristics(source).unwrap();
                            assert_eq!(
                                (chars.base_power, chars.base_toughness),
                                (Some(base.0), Some(base.1)),
                                "CR 613.4a/208.4b: CDA establishes 7a values before 7b setting"
                            );
                            assert_eq!(
                                (chars.power, chars.toughness),
                                (Some(current.0), Some(current.1)),
                                "actor={actor:?}, setting={setting}, modifying={modifying}, counters={counters}, switches={switches}, reverse={reverse}"
                            );
                            for (value, expected) in [
                                (Value::SourcePower, current.0),
                                (Value::SourceToughness, current.1),
                                (
                                    Value::BasePowerOf(Box::new(ChooseSpec::SpecificObject(
                                        source,
                                    ))),
                                    base.0,
                                ),
                            ] {
                                game.player_mut(actor).unwrap().life = 20;
                                game.stack.push(StackEntry::ability(
                                    source,
                                    actor,
                                    vec![Effect::gain_life(value)],
                                ));
                                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                assert_eq!(game.player(actor).unwrap().life - 20, expected);
                                reads += 1;
                            }
                            cases += 1;
                        }
                    }
                }
            }
        }
    }
    assert_eq!((cases, reads), (96, 288));
}

#[test]
fn cr_400_11c_global_effects_cannot_change_cards_outside_the_game() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::static_abilities::{
        AddColorsForFilter, RemoveAllAbilitiesForFilter, SetCreatureSubtypesForFilter,
    };
    use ironsmith::{
        Ability, CardId, CardType, ColorSet, ObjectFilter, PowerToughness, PtValue, StackEntry,
        StaticAbility, Subtype, Value, Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for zone in [
            Zone::Library,
            Zone::Hand,
            Zone::Battlefield,
            Zone::Graveyard,
            Zone::Stack,
            Zone::Exile,
            Zone::Command,
            Zone::Ante,
            Zone::OutsideGame,
        ] {
            for mode in 0..3 {
                let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                let definition = CardDefinitionBuilder::new(
                    CardId::new(),
                    "Printed CDA on an otherwise unaffected creature card",
                )
                .card_types(vec![CardType::Creature])
                .subtypes(vec![Subtype::Elf])
                .power_toughness(PowerToughness::new(PtValue::Star, PtValue::Star))
                .with_ability(Ability::static_ability(
                    StaticAbility::characteristic_defining_pt(Value::Fixed(5), Value::Fixed(7)),
                ))
                .build();
                let subject = game.create_object_from_definition(&definition, actor, zone);
                if zone == Zone::Stack {
                    game.stack.push(StackEntry::new(subject, actor));
                }
                assert_eq!(
                    (game.current_power(subject), game.current_toughness(subject)),
                    (Some(5), Some(7)),
                    "printed CDAs work even outside the game"
                );
                // No explicit outside-game selector or forged target is used:
                // this is a broad static effect on creature cards you own.
                // A card outside the game is immune even if that description
                // would otherwise match it (CR 400.11c).
                let mut filter = ObjectFilter::default()
                    .with_type(CardType::Creature)
                    .owned_by(PlayerFilter::You);
                filter.physical_card = true;
                let ability = match mode {
                    0 => StaticAbility::new(SetCreatureSubtypesForFilter::new(
                        filter,
                        vec![Subtype::Goblin],
                    )),
                    1 => StaticAbility::new(AddColorsForFilter::new(filter, ColorSet::BLUE)),
                    _ => StaticAbility::new(RemoveAllAbilitiesForFilter::new(filter)),
                };
                let source =
                    CardDefinitionBuilder::new(CardId::new(), "External all-card effect source")
                        .card_types(vec![CardType::Enchantment])
                        .with_ability(Ability::static_ability(ability))
                        .build();
                game.create_object_from_definition(&source, actor, Zone::Battlefield);
                let chars = game.current_characteristics(subject).unwrap();
                let outside = zone == Zone::OutsideGame;
                let correct = match mode {
                    0 => {
                        chars.subtypes.contains(&if outside {
                            Subtype::Elf
                        } else {
                            Subtype::Goblin
                        }) && !chars.subtypes.contains(&if outside {
                            Subtype::Goblin
                        } else {
                            Subtype::Elf
                        })
                    }
                    1 => {
                        chars.colors
                            == if outside {
                                ColorSet::COLORLESS
                            } else {
                                ColorSet::BLUE
                            }
                    }
                    _ => {
                        if outside {
                            !chars.abilities.is_empty()
                                && (chars.power, chars.toughness) == (Some(5), Some(7))
                        } else {
                            chars.abilities.is_empty()
                                && (chars.power, chars.toughness) == (Some(0), Some(0))
                        }
                    }
                };
                if !correct {
                    discrepancies.push(format!("actor={actor:?}, zone={zone:?}, mode={mode}: subtypes={:?}, colors={:?}, abilities={}, PT={:?}/{:?}", chars.subtypes, chars.colors, chars.abilities.len(), chars.power, chars.toughness));
                }
                cases += 1;
            }
        }
    }
    assert_eq!(cases, 54);
    assert!(
        discrepancies.is_empty(),
        "CR 400.11c: external global effects cannot modify cards outside the game, while printed CDAs keep functioning there: {discrepancies:#?}"
    );
}

#[test]
fn cr_400_11b_c_effects_can_bring_cards_into_the_game_then_affect_them_normally() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::MoveToZoneEffect;
    use ironsmith::static_abilities::AddColorsForFilter;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, ColorSet, ObjectFilter, PowerToughness, PtValue,
        StaticAbility, Value, Zone,
    };
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for same_owner in [false, true] {
            for destination in [Zone::Hand, Zone::Battlefield] {
                let owner = if same_owner {
                    actor
                } else {
                    PlayerId::from_index(1 - actor.0)
                };
                let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                let definition =
                    CardDefinitionBuilder::new(CardId::new(), "Outside card with a printed CDA")
                        .card_types(vec![CardType::Creature])
                        .power_toughness(PowerToughness::new(PtValue::Star, PtValue::Star))
                        .with_ability(Ability::static_ability(
                            StaticAbility::characteristic_defining_pt(
                                Value::Fixed(5),
                                Value::Fixed(7),
                            ),
                        ))
                        .build();
                let card =
                    game.create_object_from_definition(&definition, owner, Zone::OutsideGame);
                let stable = game.object(card).unwrap().stable_id;
                assert_eq!(
                    (game.current_power(card), game.current_toughness(card)),
                    (Some(5), Some(7))
                );
                let mut filter = ObjectFilter::default().with_type(CardType::Creature);
                filter.physical_card = true;
                let source =
                    CardDefinitionBuilder::new(CardId::new(), "In-game global color effect")
                        .card_types(vec![CardType::Enchantment])
                        .with_ability(Ability::static_ability(StaticAbility::new(
                            AddColorsForFilter::new(filter, ColorSet::BLUE),
                        )))
                        .build();
                let source = game.create_object_from_definition(&source, actor, Zone::Battlefield);
                let effect =
                    MoveToZoneEffect::new(ChooseSpec::SpecificObject(card), destination, false);
                let effect = if destination == Zone::Battlefield {
                    effect.under_you_control()
                } else {
                    effect
                };
                effect
                    .execute(&mut game, &mut EffectContext::new_default(source, actor))
                    .unwrap();
                let entered = game.find_object_by_stable_id(stable).unwrap();
                assert_eq!(game.object(entered).unwrap().zone, destination);
                assert_eq!(game.object(entered).unwrap().owner, owner);
                if destination == Zone::Battlefield {
                    assert_eq!(game.current_controller(entered), Some(actor));
                } else {
                    assert!(game.player(owner).unwrap().hand.contains(&entered));
                }
                for zone in [destination, Zone::Exile, Zone::Graveyard] {
                    let current = game.find_object_by_stable_id(stable).unwrap();
                    if zone != destination {
                        MoveToZoneEffect::new(ChooseSpec::SpecificObject(current), zone, false)
                            .execute(&mut game, &mut EffectContext::new_default(source, actor))
                            .unwrap();
                    }
                    let current = game.find_object_by_stable_id(stable).unwrap();
                    assert_eq!(game.object(current).unwrap().zone, zone);
                    assert_eq!(game.object(current).unwrap().owner, owner);
                    assert_eq!(
                        game.current_colors(current),
                        Some(ColorSet::BLUE),
                        "once in the game, ordinary global effects apply in {zone:?}"
                    );
                    assert_eq!(
                        (game.current_power(current), game.current_toughness(current)),
                        (Some(5), Some(7))
                    );
                }
                cases += 1;
            }
        }
    }
    assert_eq!(cases, 8);
}

#[test]
fn cr_110_5d_cards_outside_the_battlefield_are_neither_tapped_nor_untapped() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::{
        CardId, CardType, Effect, ObjectFilter, PowerToughness, StackEntry, Value, Zone,
    };
    let mut fixtures = 0;
    let mut queries = 0;
    let mut discrepancies = Vec::new();
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for zone in [
            Zone::Library,
            Zone::Hand,
            Zone::Battlefield,
            Zone::Graveyard,
            Zone::Stack,
            Zone::Exile,
            Zone::Command,
            Zone::Ante,
        ] {
            for tapped in [false, true] {
                if zone != Zone::Battlefield && tapped {
                    continue;
                }
                let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                let definition =
                    CardDefinitionBuilder::new(CardId::new(), "Permanent-status domain subject")
                        .card_types(vec![CardType::Creature])
                        .power_toughness(PowerToughness::fixed(3, 4))
                        .build();
                let subject = game.create_object_from_definition(&definition, actor, zone);
                if zone == Zone::Stack {
                    game.stack.push(StackEntry::new(subject, actor));
                }
                if tapped {
                    game.tap(subject);
                }
                let observer =
                    CardDefinitionBuilder::new(CardId::new(), "Status count effect observer")
                        .card_types(vec![CardType::Artifact])
                        .build();
                let observer =
                    game.create_object_from_definition(&observer, actor, Zone::Battlefield);
                for status in 0..3 {
                    let filter = ObjectFilter::specific(subject).in_zone(zone);
                    let filter = match status {
                        1 => filter.tapped(),
                        2 => filter.untapped(),
                        _ => filter,
                    };
                    let expected = if status == 0 {
                        1
                    } else {
                        i32::from(
                            zone == Zone::Battlefield
                                && ((status == 1 && tapped) || (status == 2 && !tapped)),
                        )
                    };
                    let before = game.player(actor).unwrap().life;
                    game.stack.push(StackEntry::ability(
                        observer,
                        actor,
                        vec![Effect::gain_life(Value::Count(filter))],
                    ));
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    let actual = game.player(actor).unwrap().life - before;
                    if actual != expected {
                        discrepancies.push(format!("actor={actor:?}, zone={zone:?}, tapped={tapped}, status={status}: counted {actual}, required {expected}"));
                    }
                    queries += 1;
                }
                fixtures += 1;
            }
        }
    }
    assert_eq!((fixtures, queries), (18, 54));
    assert!(
        discrepancies.is_empty(),
        "CR 110.5d: only battlefield permanents can satisfy a tapped or untapped status predicate: {discrepancies:#?}"
    );
}

#[test]
fn cr_110_5a_b_token_copies_get_fresh_status_even_when_the_source_is_tapped_or_face_down() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effect::OutcomeValue;
    use ironsmith::effects::CreateTokenCopyEffect;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, ColorSet, ManaCost, ManaSymbol, PowerToughness,
        StaticAbility, Subtype, Zone,
    };
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for same_owner in [false, true] {
            for source_tapped in [false, true] {
                for face_down in [false, true] {
                    for enters_tapped in [false, true] {
                        let owner = if same_owner {
                            actor
                        } else {
                            PlayerId::from_index(1 - actor.0)
                        };
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        let definition = CardDefinitionBuilder::new(
                            CardId::new(),
                            "Status-copy source creature",
                        )
                        .card_types(vec![CardType::Creature])
                        .subtypes(vec![Subtype::Elf])
                        .mana_cost(ManaCost::from_symbols(vec![ManaSymbol::Red]))
                        .power_toughness(PowerToughness::fixed(3, 4))
                        .with_ability(Ability::static_ability(StaticAbility::flying()))
                        .build();
                        let source = game.create_object_from_definition(
                            &definition,
                            owner,
                            Zone::Battlefield,
                        );
                        if source_tapped {
                            game.tap(source);
                        }
                        if face_down {
                            assert!(game.set_face_down(source));
                        }
                        let effect = CreateTokenCopyEffect::one(ChooseSpec::SpecificObject(source));
                        let effect = if enters_tapped {
                            CreateTokenCopyEffect::tapped(ChooseSpec::SpecificObject(source))
                        } else {
                            effect
                        };
                        let OutcomeValue::Objects(created) = effect
                            .execute(&mut game, &mut EffectContext::new_default(source, actor))
                            .unwrap()
                            .value
                        else {
                            panic!("created copy receipt")
                        };
                        assert_eq!(created.len(), 1);
                        let copy = created[0];
                        assert_eq!(game.object(copy).unwrap().zone, Zone::Battlefield);
                        assert_eq!(
                            game.is_tapped(copy),
                            enters_tapped,
                            "new status follows the creating effect, not source status"
                        );
                        assert!(!game.is_face_down(copy), "face-down status is not copied");
                        assert!(!game.is_flipped(copy));
                        assert!(!game.is_phased_out(copy));
                        assert_eq!(game.current_controller(copy), Some(actor));
                        let expected_pt = if face_down {
                            (Some(2), Some(2))
                        } else {
                            (Some(3), Some(4))
                        };
                        assert_eq!(
                            (game.current_power(copy), game.current_toughness(copy)),
                            expected_pt,
                            "face-down characteristics are copiable even though face-down status is not"
                        );
                        assert_eq!(
                            game.current_colors(copy),
                            Some(if face_down {
                                ColorSet::COLORLESS
                            } else {
                                ColorSet::RED
                            })
                        );
                        assert_eq!(
                            game.object_has_ability(copy, &StaticAbility::flying()),
                            !face_down
                        );
                        assert_eq!(game.is_tapped(source), source_tapped);
                        assert_eq!(game.is_face_down(source), face_down);
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 32);
}

#[test]
fn cr_110_5b_reentry_starts_fresh_after_tapped_flipped_and_face_down_departures() {
    use ironsmith::card::LinkedFaceLayout;
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::MoveToZoneEffect;
    use ironsmith::{CardId, CardType, ChooseSpec, PowerToughness, Zone};
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for destination in [Zone::Hand, Zone::Graveyard, Zone::Exile, Zone::Library] {
            for mask in 0..8 {
                for enters_tapped in [false, true] {
                    let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                    let front_id = CardId::new();
                    let back_id = CardId::new();
                    let front = CardDefinitionBuilder::new(front_id, "Reentry flip front")
                        .card_types(vec![CardType::Creature])
                        .power_toughness(PowerToughness::fixed(3, 4))
                        .other_face(back_id)
                        .other_face_name("Reentry flip back")
                        .linked_face_layout(LinkedFaceLayout::Flip)
                        .build();
                    let back = CardDefinitionBuilder::new(back_id, "Reentry flip back")
                        .card_types(vec![CardType::Creature])
                        .power_toughness(PowerToughness::fixed(5, 6))
                        .other_face(front_id)
                        .other_face_name("Reentry flip front")
                        .linked_face_layout(LinkedFaceLayout::Flip)
                        .build();
                    game.register_linked_face_definition(&front);
                    game.register_linked_face_definition(&back);
                    let source =
                        game.create_object_from_definition(&front, actor, Zone::Battlefield);
                    let stable = game.object(source).unwrap().stable_id;
                    if mask & 1 != 0 {
                        game.tap(source);
                    }
                    if mask & 2 != 0 {
                        assert!(game.flip_permanent(source));
                    }
                    if mask & 4 != 0 {
                        assert!(game.set_face_down(source));
                    }
                    assert_eq!(game.is_tapped(source), mask & 1 != 0);
                    assert_eq!(game.is_flipped(source), mask & 2 != 0);
                    assert_eq!(game.is_face_down(source), mask & 4 != 0);
                    MoveToZoneEffect::new(ChooseSpec::SpecificObject(source), destination, false)
                        .execute(&mut game, &mut EffectContext::new_default(source, actor))
                        .unwrap();
                    let away = game.find_object_by_stable_id(stable).unwrap();
                    assert_eq!(game.object(away).unwrap().zone, destination);
                    let effect = MoveToZoneEffect::new(
                        ChooseSpec::SpecificObject(away),
                        Zone::Battlefield,
                        false,
                    );
                    let effect = if enters_tapped {
                        effect.tapped()
                    } else {
                        effect
                    };
                    effect
                        .execute(&mut game, &mut EffectContext::new_default(away, actor))
                        .unwrap();
                    let returned = game.find_object_by_stable_id(stable).unwrap();
                    assert_eq!(game.object(returned).unwrap().zone, Zone::Battlefield);
                    assert_eq!(
                        game.is_tapped(returned),
                        enters_tapped,
                        "actor={actor:?}, via={destination:?}, departure={mask}"
                    );
                    assert!(!game.is_flipped(returned), "reentry is unflipped");
                    assert!(!game.is_face_down(returned), "reentry is face up");
                    assert!(!game.is_phased_out(returned), "reentry is phased in");
                    assert_eq!(
                        game.current_name(returned).as_deref(),
                        Some("Reentry flip front")
                    );
                    assert_eq!(
                        (
                            game.current_power(returned),
                            game.current_toughness(returned)
                        ),
                        (Some(3), Some(4))
                    );
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 128);
}

#[test]
fn cr_110_1_4c_losing_every_permanent_type_leaves_a_permanent_on_the_battlefield() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::continuous::{EffectTarget, Modification};
    use ironsmith::effects::{ApplyContinuousEffect, DestroyEffect, TapEffect};
    use ironsmith::{
        CardId, CardType, ChooseSpec, Effect, ObjectFilter, PowerToughness, StackEntry, Until,
        Value, Zone,
    };
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for permanent_type in [
            CardType::Artifact,
            CardType::Battle,
            CardType::Creature,
            CardType::Enchantment,
            CardType::Land,
            CardType::Planeswalker,
        ] {
            for kindred in [false, true] {
                for setting in [false, true] {
                    let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                    let mut types = vec![permanent_type];
                    if kindred {
                        types.push(CardType::Kindred);
                    }
                    let mut builder = CardDefinitionBuilder::new(
                        CardId::new(),
                        "Permanent after losing its permanent types",
                    )
                    .card_types(types);
                    if permanent_type == CardType::Creature {
                        builder = builder.power_toughness(PowerToughness::fixed(3, 4));
                    }
                    if permanent_type == CardType::Planeswalker {
                        builder = builder.loyalty(3);
                    }
                    if permanent_type == CardType::Battle {
                        builder = builder.defense(3);
                    }
                    let subject = game.create_object_from_definition(
                        &builder.build(),
                        actor,
                        Zone::Battlefield,
                    );
                    let stable = game.object(subject).unwrap().stable_id;
                    let observer = CardDefinitionBuilder::new(
                        CardId::new(),
                        "Permanent domain count observer",
                    )
                    .card_types(vec![CardType::Artifact])
                    .build();
                    let observer =
                        game.create_object_from_definition(&observer, actor, Zone::Battlefield);
                    let expected = if kindred {
                        vec![CardType::Kindred]
                    } else {
                        vec![]
                    };
                    let modification = if setting {
                        Modification::SetCardTypes(expected.clone())
                    } else {
                        Modification::RemoveCardTypes(vec![permanent_type])
                    };
                    ApplyContinuousEffect::new(
                        EffectTarget::Specific(subject),
                        modification,
                        Until::EndOfTurn,
                    )
                    .execute(&mut game, &mut EffectContext::new_default(observer, actor))
                    .unwrap();
                    assert_eq!(game.current_card_types(subject), Some(expected));
                    ironsmith::rules::state_based::apply_state_based_actions(&mut game).unwrap();
                    assert_eq!(game.object(subject).unwrap().zone, Zone::Battlefield);
                    TapEffect::with_spec(ChooseSpec::SpecificObject(subject))
                        .execute(&mut game, &mut EffectContext::new_default(observer, actor))
                        .unwrap();
                    assert!(
                        game.is_tapped(subject),
                        "a typeless permanent still has status"
                    );
                    let mut filter = ObjectFilter::permanent();
                    filter.specific = Some(subject);
                    game.stack.push(StackEntry::ability(
                        observer,
                        actor,
                        vec![Effect::gain_life(Value::Count(filter))],
                    ));
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    assert_eq!(
                        game.player(actor).unwrap().life,
                        21,
                        "all six permanent types remain permanent after losing their types"
                    );
                    DestroyEffect::with_spec(ChooseSpec::SpecificObject(subject))
                        .execute(&mut game, &mut EffectContext::new_default(observer, actor))
                        .unwrap();
                    let departed = game.find_object_by_stable_id(stable).unwrap();
                    assert_eq!(game.object(departed).unwrap().zone, Zone::Graveyard);
                    let mut filter = ObjectFilter::permanent();
                    filter.specific = Some(departed);
                    game.stack.push(StackEntry::ability(
                        observer,
                        actor,
                        vec![Effect::gain_life(Value::Count(filter))],
                    ));
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    assert_eq!(
                        game.player(actor).unwrap().life,
                        21,
                        "the departed card is no longer a permanent"
                    );
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 48);
}

#[test]
fn cr_400_9_901_7a_face_down_planes_are_new_objects_without_old_counters() {
    cr_audit_planar_new_object_counters(false);
}

#[test]
fn cr_400_9_901_7a_face_down_phenomena_are_new_objects_without_old_counters() {
    cr_audit_planar_new_object_counters(true);
}

fn cr_audit_planar_new_object_counters(phenomenon: bool) {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::{CardId, CardType, CounterType, PlanarCardKind, Zone};
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for communal in [false, true] {
            for counters in [0, 1, 3] {
                let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                game.turn.active_player = actor;
                let make_deck = |prefix: &str, count: usize| {
                    (0..count)
                        .map(|index| {
                            let is_phenomenon = phenomenon && index == 0;
                            let definition = CardDefinitionBuilder::new(
                                CardId::new(),
                                format!("{prefix} Planar card {index}"),
                            )
                            .card_types(vec![if is_phenomenon {
                                CardType::Phenomenon
                            } else {
                                CardType::Plane
                            }])
                            .build();
                            (
                                definition,
                                if is_phenomenon {
                                    PlanarCardKind::Phenomenon
                                } else {
                                    PlanarCardKind::Plane
                                },
                            )
                        })
                        .collect::<Vec<_>>()
                };
                if communal {
                    game.enable_planechase_communal(make_deck("Shared", 20))
                        .unwrap();
                } else {
                    game.enable_planechase(vec![
                        (PlayerId::from_index(0), make_deck("Alice", 10)),
                        (PlayerId::from_index(1), make_deck("Bob", 10)),
                    ])
                    .unwrap();
                }
                let mut original = game.reveal_starting_plane().unwrap();
                if phenomenon {
                    let mut searched = 0;
                    while game.planar_card_kind(original) != Some(PlanarCardKind::Phenomenon) {
                        original = game.planeswalk(actor, original).unwrap();
                        searched += 1;
                        assert!(
                            searched <= if communal { 20 } else { 10 },
                            "native deck must contain its phenomenon"
                        );
                    }
                }
                let stable = game.object(original).unwrap().stable_id;
                let owner = game.object(original).unwrap().owner;
                let scroll = CounterType::Named("scroll".into());
                if counters != 0 {
                    game.add_counters(original, scroll, counters).unwrap();
                }
                game.planeswalk(actor, original).unwrap();
                let down = game.find_object_by_stable_id(stable).unwrap();
                assert_ne!(down, original);
                assert!(game.object(original).is_none());
                assert_eq!(game.object(down).unwrap().zone, Zone::Command);
                assert_eq!(game.object(down).unwrap().owner, owner);
                assert!(!game.is_face_up_planar_object(down));
                let remaining = game
                    .object(down)
                    .unwrap()
                    .counters
                    .get(&scroll)
                    .copied()
                    .unwrap_or(0);
                if remaining != 0 {
                    discrepancies.push(format!("actor={actor:?}, communal={communal}, old counters={counters}: new face-down object retained {remaining}"));
                }
                let size = if communal { 20 } else { 10 };
                for _ in 1..size {
                    let current = game.face_up_planar_objects()[0];
                    game.planeswalk(actor, current).unwrap();
                }
                let returned = game.find_object_by_stable_id(stable).unwrap();
                assert!(game.is_face_up_planar_object(returned));
                let remaining = game
                    .object(returned)
                    .unwrap()
                    .counters
                    .get(&scroll)
                    .copied()
                    .unwrap_or(0);
                if remaining != 0 {
                    discrepancies.push(format!("actor={actor:?}, communal={communal}, old counters={counters}: next visit retained {remaining}"));
                }
                cases += 1;
            }
        }
    }
    assert_eq!(cases, 12);
    assert!(
        discrepancies.is_empty(),
        "CR 400.9 / 901.7a: the new face-down object has no relation to the old plane object, including its old counters: {discrepancies:#?}"
    );
}

#[test]
fn cr_400_9_schemes_become_new_objects_without_old_counters_when_turned_down() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::{
        ArchenemyVariant, CardId, CardType, CounterType, Supertype, TriggerQueue, Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for ongoing in [false, true] {
            for counters in [0, 1, 3] {
                let mut game =
                    GameState::new(vec!["Alice".into(), "Bob".into(), "Charlie".into()], 20);
                let deck = (0..20)
                    .map(|index| {
                        CardDefinitionBuilder::new(
                            CardId::new(),
                            format!("Identity scheme {index}"),
                        )
                        .card_types(vec![CardType::Scheme])
                        .supertypes(if ongoing {
                            vec![Supertype::Ongoing]
                        } else {
                            vec![]
                        })
                        .build()
                    })
                    .collect();
                game.enable_archenemy(ArchenemyVariant::Default, vec![(actor, deck)])
                    .unwrap();
                let original = game.set_scheme_in_motion(actor).unwrap();
                let stable = game.object(original).unwrap().stable_id;
                let scroll = CounterType::Named("scroll".into());
                if counters != 0 {
                    game.add_counters(original, scroll, counters).unwrap();
                }
                let mut triggers = TriggerQueue::new();
                // Dispatch actual set-in-motion observations; these schemes have no abilities.
                ironsmith::put_triggers_on_stack(&mut game, &mut triggers).unwrap();
                assert!(game.stack.is_empty());
                if ongoing {
                    game.abandon_scheme(original).unwrap();
                } else {
                    ironsmith::apply_state_based_actions(&mut game).unwrap();
                }
                let down = game.find_object_by_stable_id(stable).unwrap();
                assert_ne!(down, original);
                assert!(game.object(original).is_none());
                assert_eq!(game.object(down).unwrap().zone, Zone::Command);
                assert_eq!(game.object(down).unwrap().owner, actor);
                assert!(!game.is_face_up_scheme(down));
                assert_eq!(game.scheme_deck(actor).unwrap()[0], down);
                let remaining = game
                    .object(down)
                    .unwrap()
                    .counters
                    .get(&scroll)
                    .copied()
                    .unwrap_or(0);
                if remaining != 0 {
                    discrepancies.push(format!("actor={actor:?} ongoing={ongoing} old={counters}: down object retained {remaining}"));
                }
                for visit in 0..20 {
                    let current = game.set_scheme_in_motion(actor).unwrap();
                    ironsmith::put_triggers_on_stack(&mut game, &mut triggers).unwrap();
                    assert!(game.stack.is_empty());
                    if visit == 19 {
                        assert_eq!(game.object(current).unwrap().stable_id, stable);
                        let remaining = game
                            .object(current)
                            .unwrap()
                            .counters
                            .get(&scroll)
                            .copied()
                            .unwrap_or(0);
                        if remaining != 0 {
                            discrepancies.push(format!("actor={actor:?} ongoing={ongoing} old={counters}: next visit retained {remaining}"));
                        }
                    } else if ongoing {
                        game.abandon_scheme(current).unwrap();
                    } else {
                        ironsmith::apply_state_based_actions(&mut game).unwrap();
                    }
                }
                cases += 1;
            }
        }
    }
    assert_eq!(cases, 12);
    assert!(
        discrepancies.is_empty(),
        "CR 400.9: a scheme turned face down becomes a new object without the previous object's counters: {discrepancies:#?}"
    );
}

#[test]
fn cr_110_2b_400_7a_resolved_spell_control_keeps_caster_as_default_controller() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::GainControlEffect;
    use ironsmith::{
        CardId, CardType, ChooseSpec, Effect, PowerToughness, StackEntry, Until, Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for caster in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        let taker = PlayerId::from_index(1 - caster.index() as u8);
        let owner = PlayerId::from_index(2);
        for temporary in [false, true] {
            for caster_leaves in [false, true] {
                let mut game =
                    GameState::new(vec!["Alice".into(), "Bob".into(), "Charlie".into()], 20);
                let card =
                    CardDefinitionBuilder::new(CardId::new(), "Foreign-owned permanent spell")
                        .card_types(vec![CardType::Creature])
                        .power_toughness(PowerToughness::fixed(3, 4))
                        .build();
                let spell = game.create_object_from_definition(&card, owner, Zone::Stack);
                let stable = game.object(spell).unwrap().stable_id;
                game.stage_initial_controller_for_assembly(spell, caster);
                game.stack.push(StackEntry::new(spell, caster));
                let source = game.create_object_from_definition(
                    &CardDefinitionBuilder::new(CardId::new(), "Resolved control source")
                        .card_types(vec![CardType::Artifact])
                        .build(),
                    taker,
                    Zone::Battlefield,
                );
                game.stack.push(StackEntry::ability(
                    source,
                    taker,
                    vec![Effect::new(GainControlEffect::new(
                        ChooseSpec::SpecificObject(spell),
                        if temporary {
                            Until::EndOfTurn
                        } else {
                            Until::Forever
                        },
                    ))],
                ));
                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                assert_eq!(game.current_controller(spell), Some(taker));
                assert_eq!(game.stack[0].controller, caster);
                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                let permanent = game.find_object_by_stable_id(stable).unwrap();
                assert_ne!(permanent, spell);
                assert_eq!(game.object(permanent).unwrap().owner, owner);
                assert_eq!(game.object(permanent).unwrap().zone, Zone::Battlefield);
                if game.current_controller(permanent) != Some(taker) {
                    discrepancies.push(format!("caster={caster:?} temp={temporary} leaves={caster_leaves}: live controller {:?}, required {taker:?}", game.current_controller(permanent)));
                }
                if game.object(permanent).unwrap().initial_controller != caster {
                    discrepancies.push(format!("caster={caster:?} temp={temporary} leaves={caster_leaves}: default controller {:?}",game.object(permanent).unwrap().initial_controller));
                }
                if caster_leaves {
                    game.concede_game(caster).unwrap();
                }
                ironsmith::turn::execute_cleanup_step(&mut game);
                game.refresh_continuous_state().unwrap();
                let current = game.find_object_by_stable_id(stable).unwrap();
                let required_zone = if temporary && caster_leaves {
                    Zone::Exile
                } else {
                    Zone::Battlefield
                };
                if game.object(current).unwrap().zone != required_zone {
                    discrepancies.push(format!("caster={caster:?} temp={temporary} leaves={caster_leaves}: after cleanup {:?}, required {required_zone:?}",game.object(current).unwrap().zone));
                }
                if required_zone == Zone::Battlefield {
                    let required_controller = if temporary { caster } else { taker };
                    if game.current_controller(current) != Some(required_controller) {
                        discrepancies.push(format!("caster={caster:?} temp={temporary} leaves={caster_leaves}: cleanup controller {:?}, required {required_controller:?}",game.current_controller(current)));
                    }
                }
                cases += 1;
            }
        }
    }
    assert_eq!(cases, 8);
    assert!(
        discrepancies.is_empty(),
        "CR 110.2b / 400.7a / 800.4c: resolving control effects follow the spell, with its original caster retained as default: {discrepancies:#?}"
    );
}

#[test]
fn cr_110_2_4_304_4_307_4_entry_keeps_ownership_and_rejects_instant_sorcery_cards() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::MoveToZoneEffect;
    use ironsmith::{
        CardId, CardType, ChooseSpec, CounterType, Effect, PowerToughness, StackEntry, Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    let types = [
        CardType::Artifact,
        CardType::Battle,
        CardType::Creature,
        CardType::Enchantment,
        CardType::Land,
        CardType::Planeswalker,
        CardType::Instant,
        CardType::Sorcery,
    ];
    for kind in types {
        for kindred in [false, true] {
            for origin in [
                Zone::Hand,
                Zone::Library,
                Zone::Graveyard,
                Zone::Exile,
                Zone::Stack,
                Zone::Command,
            ] {
                for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                        for under_owner in [false, true] {
                            let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                            let mut card_types = vec![kind];
                            if kindred {
                                card_types.push(CardType::Kindred);
                            }
                            let card =
                                CardDefinitionBuilder::new(CardId::new(), "Entry domain card")
                                    .card_types(card_types)
                                    .power_toughness(PowerToughness::fixed(3, 4))
                                    .loyalty(3)
                                    .defense(3)
                                    .build();
                            let old = game.create_object_from_definition(&card, owner, origin);
                            let stable = game.object(old).unwrap().stable_id;
                            if origin == Zone::Stack {
                                game.stack.push(StackEntry::new(old, owner));
                            }
                            let scroll = CounterType::Named("scroll".into());
                            game.add_counters(old, scroll, 1).unwrap();
                            let source = game.create_object_from_definition(
                                &CardDefinitionBuilder::new(
                                    CardId::new(),
                                    "Entry instruction source",
                                )
                                .card_types(vec![CardType::Artifact])
                                .build(),
                                actor,
                                Zone::Battlefield,
                            );
                            let entry = MoveToZoneEffect::new(
                                ChooseSpec::SpecificObject(old),
                                Zone::Battlefield,
                                false,
                            );
                            let entry = if under_owner {
                                entry.under_owner_control()
                            } else {
                                entry.under_you_control()
                            };
                            game.stack.push(StackEntry::ability(
                                source,
                                actor,
                                vec![Effect::new(entry)],
                            ));
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                            let current = game.find_object_by_stable_id(stable).unwrap();
                            let object = game.object(current).unwrap();
                            let prohibited = matches!(kind, CardType::Instant | CardType::Sorcery);
                            let expected_zone = if prohibited {
                                origin
                            } else {
                                Zone::Battlefield
                            };
                            let label = format!(
                                "kind={kind:?} kindred={kindred} origin={origin:?} owner={owner:?} actor={actor:?} under_owner={under_owner}"
                            );
                            if object.zone != expected_zone || object.owner != owner {
                                discrepancies.push(format!("{label}: zone/owner {:?}/{:?}, required {expected_zone:?}/{owner:?}",object.zone,object.owner));
                            }
                            if prohibited {
                                if current != old
                                    || object.counters.get(&scroll).copied() != Some(1)
                                {
                                    discrepancies.push(format!(
                                        "{label}: rejected entry changed identity or counters"
                                    ));
                                }
                            } else {
                                let expected_controller = if under_owner { owner } else { actor };
                                if current == old
                                    || game.object(old).is_some()
                                    || object.counters.get(&scroll).copied().unwrap_or(0) != 0
                                {
                                    discrepancies.push(format!("{label}: entry did not create a fresh object without old counters"));
                                }
                                if game.current_controller(current) != Some(expected_controller)
                                    || object.initial_controller != expected_controller
                                {
                                    discrepancies.push(format!("{label}: live/default controller {:?}/{:?}, required {expected_controller:?}",game.current_controller(current),object.initial_controller));
                                }
                            }
                            game.validate_zone_consistency().unwrap();
                            cases += 1;
                        }
                    }
                }
            }
        }
    }
    assert_eq!(cases, 768);
    assert!(
        discrepancies.is_empty(),
        "CR 110.2/110.4/304.4/307.4/400.4a: actual entry instructions retain ownership, set the stated controller, and leave instant/sorcery cards in their previous zone: {discrepancies:#?}"
    );
}

#[test]
fn cr_110_2b_109_5_614_12a_stolen_permanent_spells_use_current_controller_for_entry_choices() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::ColorsContext;
    use ironsmith::effects::GainControlEffect;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, Color, Effect, PowerToughness, StackEntry,
        StaticAbility, Zone,
    };
    struct EntryChoice {
        players: Vec<PlayerId>,
    }
    impl DecisionMaker for EntryChoice {
        fn decide_colors(&mut self, _: &GameState, ctx: &ColorsContext) -> Vec<Color> {
            self.players.push(ctx.player);
            vec![if ctx.player == PlayerId::from_index(0) {
                Color::Red
            } else {
                Color::Blue
            }]
        }
    }
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for kind in [CardType::Artifact, CardType::Creature] {
        for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
            for caster in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                for taker in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                    let mut card =
                        CardDefinitionBuilder::new(CardId::new(), "Entry choice permanent")
                            .card_types(vec![kind])
                            .with_ability(Ability::static_ability(
                                StaticAbility::choose_color_as_enters(
                                    None,
                                    "As this enters, choose a color.".into(),
                                ),
                            ));
                    if kind == CardType::Creature {
                        card = card.power_toughness(PowerToughness::fixed(3, 4));
                    }
                    let spell =
                        game.create_object_from_definition(&card.build(), owner, Zone::Stack);
                    let stable = game.object(spell).unwrap().stable_id;
                    game.stage_initial_controller_for_assembly(spell, caster);
                    game.stack.push(StackEntry::new(spell, caster));
                    let source = game.create_object_from_definition(
                        &CardDefinitionBuilder::new(CardId::new(), "Control source")
                            .card_types(vec![CardType::Artifact])
                            .build(),
                        taker,
                        Zone::Battlefield,
                    );
                    game.stack.push(StackEntry::ability(
                        source,
                        taker,
                        vec![Effect::new(GainControlEffect::permanent(
                            ChooseSpec::SpecificObject(spell),
                        ))],
                    ));
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    assert_eq!(game.current_controller(spell), Some(taker));
                    let mut dm = EntryChoice {
                        players: Vec::new(),
                    };
                    ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm).unwrap();
                    let permanent = game.find_object_by_stable_id(stable).unwrap();
                    assert_eq!(game.object(permanent).unwrap().zone, Zone::Battlefield);
                    assert_eq!(game.object(permanent).unwrap().owner, owner);
                    assert_eq!(game.object(permanent).unwrap().initial_controller, caster);
                    assert_eq!(game.current_controller(permanent), Some(taker));
                    let expected = if taker == PlayerId::from_index(0) {
                        Color::Red
                    } else {
                        Color::Blue
                    };
                    if dm.players != vec![taker] || game.chosen_color(permanent) != Some(expected) {
                        discrepancies.push(format!("kind={kind:?} owner={owner:?} caster={caster:?} taker={taker:?}: chooser {:?}, stored {:?}; required {taker:?}/{expected:?}",dm.players,game.chosen_color(permanent)));
                    }
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 16);
    assert!(
        discrepancies.is_empty(),
        "CR 109.5/110.2b/400.7a/614.12a: the current controller makes the permanent's own entry choices while the caster remains only the default controller: {discrepancies:#?}"
    );
}

#[test]
fn cr_303_4a_608_3b_c_player_aura_resolution_uses_live_controller_and_legal_enchant_filter() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::GainControlEffect;
    use ironsmith::object::AttachmentTarget;
    use ironsmith::{CardId, CardType, ChooseSpec, Effect, StackEntry, Subtype, Target, Zone};
    let players = [PlayerId::from_index(0), PlayerId::from_index(1)];
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for mode in 0..3 {
        for owner in players {
            for caster in players {
                for taker in players {
                    for enchanted in players {
                        if (mode == 1 && enchanted != caster) || (mode == 2 && enchanted == caster)
                        {
                            continue;
                        }
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        let filter = match mode {
                            0 => PlayerFilter::Any,
                            1 => PlayerFilter::You,
                            _ => PlayerFilter::Opponent,
                        };
                        let card = CardDefinitionBuilder::new(CardId::new(), "Player Aura spell")
                            .card_types(vec![CardType::Enchantment])
                            .subtypes(vec![Subtype::Aura])
                            .enchants(filter)
                            .build();
                        let spell = game.create_object_from_definition(&card, owner, Zone::Stack);
                        let stable = game.object(spell).unwrap().stable_id;
                        game.stage_initial_controller_for_assembly(spell, caster);
                        let mut entry = StackEntry::new(spell, caster);
                        entry.targets.push(Target::Player(enchanted));
                        game.stack.push(entry);
                        let source = game.create_object_from_definition(
                            &CardDefinitionBuilder::new(CardId::new(), "Aura control source")
                                .card_types(vec![CardType::Artifact])
                                .build(),
                            taker,
                            Zone::Battlefield,
                        );
                        game.stack.push(StackEntry::ability(
                            source,
                            taker,
                            vec![Effect::new(GainControlEffect::until_end_of_turn(
                                ChooseSpec::SpecificObject(spell),
                            ))],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        assert_eq!(game.current_controller(spell), Some(taker));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let current = game.find_object_by_stable_id(stable).unwrap();
                        let legal = mode == 0
                            || (mode == 1 && enchanted == taker)
                            || (mode == 2 && enchanted != taker);
                        let expected_zone = if legal {
                            Zone::Battlefield
                        } else {
                            Zone::Graveyard
                        };
                        let object = game.object(current).unwrap();
                        let attachment = legal.then_some(AttachmentTarget::Player(enchanted));
                        let label = format!(
                            "mode={mode} owner={owner:?} caster={caster:?} taker={taker:?} target={enchanted:?}"
                        );
                        if object.zone != expected_zone
                            || object.owner != owner
                            || object.attached_to != attachment
                            || game
                                .player(enchanted)
                                .unwrap()
                                .attachments
                                .contains(&current)
                                != legal
                        {
                            discrepancies.push(format!("{label}: zone/owner/attachment {:?}/{:?}/{:?}, required {expected_zone:?}/{owner:?}/{attachment:?}",object.zone,object.owner,object.attached_to));
                        }
                        if legal {
                            if game.current_controller(current) != Some(taker)
                                || object.initial_controller != caster
                            {
                                discrepancies.push(format!("{label}: live/default {:?}/{:?}, required {taker:?}/{caster:?}",game.current_controller(current),object.initial_controller));
                            }
                            ironsmith::turn::execute_cleanup_step(&mut game);
                            game.refresh_continuous_state().unwrap();
                            if game.current_controller(current) != Some(caster)
                                || game.object(current).unwrap().attached_to != attachment
                            {
                                discrepancies.push(format!("{label}: cleanup changed attachment or did not restore caster control"));
                            }
                        }
                        game.validate_zone_consistency().unwrap();
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 32);
    assert!(
        discrepancies.is_empty(),
        "CR 303.4a/303.4e/608.3b-c: player Aura resolution rechecks its enchant filter against its current controller, preserves ownership, and attaches only on legal resolution: {discrepancies:#?}"
    );
}

#[test]
fn cr_708_3_face_down_entry_uses_creature_characteristics_and_suppresses_printed_entry_abilities() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::MoveToZoneEffect;
    use ironsmith::triggers::Trigger;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, ColorSet, CounterType, Effect, PowerToughness,
        StackEntry, StaticAbility, TriggerQueue, Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for kind in [
        CardType::Artifact,
        CardType::Battle,
        CardType::Creature,
        CardType::Enchantment,
        CardType::Land,
        CardType::Planeswalker,
        CardType::Instant,
        CardType::Sorcery,
    ] {
        for origin in [
            Zone::Hand,
            Zone::Library,
            Zone::Graveyard,
            Zone::Exile,
            Zone::Stack,
            Zone::Command,
        ] {
            for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    for face_down in [false, true] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        let mut builder =
                            CardDefinitionBuilder::new(CardId::new(), "Printed entry ability card")
                                .card_types(vec![kind])
                                .with_ability(Ability::static_ability(
                                    StaticAbility::enters_with_counters(CounterType::Charge, 2),
                                ))
                                .with_trigger(
                                    Trigger::this_enters_battlefield(),
                                    vec![Effect::gain_life(7)],
                                );
                        if kind == CardType::Creature {
                            builder = builder.power_toughness(PowerToughness::fixed(3, 4));
                        }
                        if kind == CardType::Planeswalker {
                            builder = builder.loyalty(3);
                        }
                        if kind == CardType::Battle {
                            builder = builder.defense(3);
                        }
                        let old =
                            game.create_object_from_definition(&builder.build(), owner, origin);
                        let stable = game.object(old).unwrap().stable_id;
                        if origin == Zone::Stack {
                            game.stack.push(StackEntry::new(old, owner));
                        }
                        let source = game.create_object_from_definition(
                            &CardDefinitionBuilder::new(CardId::new(), "Hidden entry instruction")
                                .card_types(vec![CardType::Artifact])
                                .build(),
                            actor,
                            Zone::Battlefield,
                        );
                        let mut entry = MoveToZoneEffect::new(
                            ChooseSpec::SpecificObject(old),
                            Zone::Battlefield,
                            false,
                        )
                        .under_you_control();
                        if face_down {
                            entry = entry.face_down();
                        }
                        game.stack.push(StackEntry::ability(
                            source,
                            actor,
                            vec![Effect::new(entry)],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let current = game.find_object_by_stable_id(stable).unwrap();
                        let enters =
                            face_down || !matches!(kind, CardType::Instant | CardType::Sorcery);
                        let label = format!(
                            "kind={kind:?} origin={origin:?} owner={owner:?} actor={actor:?} face_down={face_down}"
                        );
                        let expected_zone = if enters { Zone::Battlefield } else { origin };
                        if game.object(current).unwrap().zone != expected_zone {
                            discrepancies.push(format!(
                                "{label}: zone {:?}, required {expected_zone:?}",
                                game.object(current).unwrap().zone
                            ));
                        }
                        assert_eq!(game.object(current).unwrap().owner, owner);
                        if enters {
                            if game.current_controller(current) != Some(actor)
                                || game.is_face_down(current) != face_down
                            {
                                discrepancies
                                    .push(format!("{label}: wrong controller/orientation"));
                            }
                            let charges = game.counter_count(current, CounterType::Charge);
                            let expected_charges = if face_down { 0 } else { 2 };
                            if charges != expected_charges {
                                discrepancies.push(format!("{label}: printed entry counters {charges}, required {expected_charges}"));
                            }
                            if face_down {
                                let chars = game.current_characteristics(current).unwrap();
                                if chars.card_types != vec![CardType::Creature]
                                    || (chars.power, chars.toughness) != (Some(2), Some(2))
                                    || chars.colors != ColorSet::COLORLESS
                                    || chars.mana_cost.is_some()
                                    || !chars.abilities.is_empty()
                                {
                                    discrepancies.push(format!(
                                        "{label}: face-down characteristic overlay incorrect"
                                    ));
                                }
                            }
                        }
                        let baseline = game.stack.len();
                        let mut triggers = TriggerQueue::new();
                        ironsmith::put_triggers_on_stack(&mut game, &mut triggers).unwrap();
                        let added = game.stack.len() - baseline;
                        let expected_triggers = usize::from(enters && !face_down);
                        if added != expected_triggers {
                            discrepancies.push(format!("{label}: printed entry triggers {added}, required {expected_triggers}"));
                        }
                        for _ in 0..added {
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        }
                        let expected_life = 20 + if enters && !face_down { 7 } else { 0 };
                        if game.player(actor).unwrap().life != expected_life {
                            discrepancies.push(format!(
                                "{label}: entry trigger life {}, required {expected_life}",
                                game.player(actor).unwrap().life
                            ));
                        }
                        game.validate_zone_consistency().unwrap();
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 384);
    assert!(
        discrepancies.is_empty(),
        "CR 708.3: face-down presentation applies before entry and suppresses printed static/triggered entry abilities, including instant/sorcery cards entering as creatures: {discrepancies:#?}"
    );
}

#[test]
fn cr_614_12a_entry_choices_finish_before_the_card_enters_the_battlefield() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::ColorsContext;
    use ironsmith::effects::MoveToZoneEffect;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, Color, Effect, ObjectId, PowerToughness, StackEntry,
        StaticAbility, Zone,
    };
    struct ObserveChoice {
        old: ObjectId,
        observations: Vec<(PlayerId, Option<Zone>, bool, bool)>,
    }
    impl DecisionMaker for ObserveChoice {
        fn decide_colors(&mut self, game: &GameState, ctx: &ColorsContext) -> Vec<Color> {
            self.observations.push((
                ctx.player,
                game.object(self.old).map(|o| o.zone),
                game.battlefield.contains(&self.old),
                ctx.source == Some(self.old),
            ));
            vec![Color::Red]
        }
    }
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for origin in [
        Zone::Hand,
        Zone::Library,
        Zone::Graveyard,
        Zone::Exile,
        Zone::Stack,
        Zone::Command,
    ] {
        for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
            for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                let card = CardDefinitionBuilder::new(CardId::new(), "Timing of entry choice")
                    .card_types(vec![CardType::Creature])
                    .power_toughness(PowerToughness::fixed(3, 4))
                    .with_ability(Ability::static_ability(
                        StaticAbility::choose_color_as_enters(
                            None,
                            "As this enters, choose a color.".into(),
                        ),
                    ))
                    .build();
                let old = game.create_object_from_definition(&card, owner, origin);
                let stable = game.object(old).unwrap().stable_id;
                if origin == Zone::Stack {
                    game.stack.push(StackEntry::new(old, owner));
                }
                let source = game.create_object_from_definition(
                    &CardDefinitionBuilder::new(CardId::new(), "Entry timing instruction")
                        .card_types(vec![CardType::Artifact])
                        .build(),
                    actor,
                    Zone::Battlefield,
                );
                game.stack.push(StackEntry::ability(
                    source,
                    actor,
                    vec![Effect::new(
                        MoveToZoneEffect::new(
                            ChooseSpec::SpecificObject(old),
                            Zone::Battlefield,
                            false,
                        )
                        .under_you_control(),
                    )],
                ));
                let mut dm = ObserveChoice {
                    old,
                    observations: Vec::new(),
                };
                ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm).unwrap();
                let current = game.find_object_by_stable_id(stable).unwrap();
                assert_ne!(current, old);
                assert!(game.object(old).is_none());
                assert_eq!(game.object(current).unwrap().zone, Zone::Battlefield);
                assert_eq!(game.object(current).unwrap().owner, owner);
                assert_eq!(game.current_controller(current), Some(actor));
                assert_eq!(game.chosen_color(current), Some(Color::Red));
                if dm.observations != vec![(actor, Some(origin), false, true)] {
                    discrepancies.push(format!("origin={origin:?} owner={owner:?} actor={actor:?}: choice observations {:?}; expected the original card still in its old zone before entry",dm.observations));
                }
                cases += 1;
            }
        }
    }
    assert_eq!(cases, 24);
    assert!(
        discrepancies.is_empty(),
        "CR 614.12a: entry choices are made before the card becomes a battlefield object: {discrepancies:#?}"
    );
}

#[test]
fn cr_712_14a_b_transformed_entry_checks_the_entering_face_and_preserves_rejected_cards() {
    use ironsmith::card::LinkedFaceLayout;
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::MoveToZoneEffect;
    use ironsmith::{
        CardId, CardType, ChooseSpec, CounterType, Effect, PowerToughness, StackEntry, Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for (front_type, back_type) in [
        (CardType::Creature, CardType::Artifact),
        (CardType::Instant, CardType::Creature),
        (CardType::Sorcery, CardType::Land),
        (CardType::Creature, CardType::Instant),
        (CardType::Artifact, CardType::Sorcery),
    ] {
        for transforming in [false, true] {
            for transformed in [false, true] {
                for origin in [
                    Zone::Hand,
                    Zone::Library,
                    Zone::Graveyard,
                    Zone::Exile,
                    Zone::Command,
                ] {
                    for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                        for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                            let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                            let front_id = CardId::new();
                            let back_id = CardId::new();
                            let mut front =
                                CardDefinitionBuilder::new(front_id, "Entry front face")
                                    .card_types(vec![front_type])
                                    .other_face(back_id)
                                    .other_face_name("Entry back face")
                                    .linked_face_layout(LinkedFaceLayout::TransformLike);
                            let mut back = CardDefinitionBuilder::new(back_id, "Entry back face")
                                .card_types(vec![back_type])
                                .other_face(front_id)
                                .other_face_name("Entry front face")
                                .linked_face_layout(LinkedFaceLayout::TransformLike);
                            if front_type == CardType::Creature {
                                front = front.power_toughness(PowerToughness::fixed(3, 4));
                            }
                            if back_type == CardType::Creature {
                                back = back.power_toughness(PowerToughness::fixed(5, 6));
                            }
                            let mut front = front.build();
                            let mut back = back.build();
                            front.card.transforming_dfc = transforming;
                            back.card.transforming_dfc = transforming;
                            game.register_linked_face_definition(&front);
                            game.register_linked_face_definition(&back);
                            let old = game.create_object_from_definition(&front, owner, origin);
                            let stable = game.object(old).unwrap().stable_id;
                            game.add_counters(old, CounterType::Charge, 1).unwrap();
                            let source = game.create_object_from_definition(
                                &CardDefinitionBuilder::new(CardId::new(), "DFC entry instruction")
                                    .card_types(vec![CardType::Artifact])
                                    .build(),
                                actor,
                                Zone::Battlefield,
                            );
                            let mut entry = MoveToZoneEffect::new(
                                ChooseSpec::SpecificObject(old),
                                Zone::Battlefield,
                                false,
                            )
                            .under_you_control();
                            if transformed {
                                entry = entry.transformed();
                            }
                            game.stack.push(StackEntry::ability(
                                source,
                                actor,
                                vec![Effect::new(entry)],
                            ));
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                            let current = game.find_object_by_stable_id(stable).unwrap();
                            let object = game.object(current).unwrap();
                            let entering_type = if transformed { back_type } else { front_type };
                            let enters =
                                !matches!(entering_type, CardType::Instant | CardType::Sorcery);
                            let label = format!(
                                "front={front_type:?} back={back_type:?} transforming={transforming} transformed={transformed} origin={origin:?} owner={owner:?} actor={actor:?}"
                            );
                            if enters {
                                let name = if transformed {
                                    "Entry back face"
                                } else {
                                    "Entry front face"
                                };
                                if object.zone != Zone::Battlefield
                                    || game.current_name(current).as_deref() != Some(name)
                                    || game.current_card_types(current) != Some(vec![entering_type])
                                    || current == old
                                    || game.counter_count(current, CounterType::Charge) != 0
                                    || game.current_controller(current) != Some(actor)
                                {
                                    discrepancies.push(format!("{label}: zone/name/types {:?}/{:?}/{:?}; required battlefield {name}/{entering_type:?} with fresh identity and actor control",object.zone,game.current_name(current),game.current_card_types(current)));
                                }
                            } else if current != old
                                || object.zone != origin
                                || game.current_name(current).as_deref() != Some("Entry front face")
                                || game.counter_count(current, CounterType::Charge) != 1
                            {
                                discrepancies.push(format!("{label}: rejected entry changed identity, zone, face or counters"));
                            }
                            assert_eq!(object.owner, owner);
                            game.validate_zone_consistency().unwrap();
                            cases += 1;
                        }
                    }
                }
            }
        }
    }
    assert_eq!(cases, 400);
    assert!(
        discrepancies.is_empty(),
        "CR 712.14a-b/400.4a: transformed entry uses the back face; ordinary entry uses the front, and illegal instant/sorcery presentations leave the card unchanged: {discrepancies:#?}"
    );
}

#[test]
fn cr_616_1c_614_12_copied_entries_use_copied_static_counters_and_triggered_abilities() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::MoveToZoneEffect;
    use ironsmith::events::zones::matchers::WouldEnterBattlefieldMatcher;
    use ironsmith::replacement::{ReplacementAction, ReplacementEffect};
    use ironsmith::triggers::Trigger;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, ColorSet, CounterType, Effect, PowerToughness,
        StackEntry, StaticAbility, Subtype, TriggerQueue, Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for donor_type in [
        CardType::Artifact,
        CardType::Battle,
        CardType::Creature,
        CardType::Enchantment,
        CardType::Land,
        CardType::Planeswalker,
    ] {
        for old_type in [CardType::Artifact, CardType::Creature] {
            for origin in [Zone::Hand, Zone::Graveyard, Zone::Exile] {
                for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        let donor_owner = PlayerId::from_index(1 - actor.index() as u8);
                        let mut template =
                            CardDefinitionBuilder::new(CardId::new(), "Copied entry donor")
                                .card_types(vec![donor_type])
                                .with_ability(Ability::static_ability(
                                    StaticAbility::enters_with_counters(CounterType::Charge, 2),
                                ))
                                .with_trigger(
                                    Trigger::this_enters_battlefield(),
                                    vec![Effect::gain_life(3)],
                                );
                        if donor_type == CardType::Creature {
                            template = template.power_toughness(PowerToughness::fixed(5, 6));
                        }
                        if donor_type == CardType::Planeswalker {
                            template = template.loyalty(3);
                        }
                        if donor_type == CardType::Battle {
                            template = template.defense(3).subtypes(vec![Subtype::Siege]);
                        }
                        let donor = game.create_object_from_definition(
                            &template.build(),
                            donor_owner,
                            Zone::Battlefield,
                        );
                        game.add_counters(donor, CounterType::Charge, 7).unwrap();
                        let donor_charge = game.counter_count(donor, CounterType::Charge);
                        if donor_type == CardType::Planeswalker {
                            game.add_counters(donor, CounterType::Loyalty, 2).unwrap();
                        }
                        if donor_type == CardType::Battle {
                            game.add_counters(donor, CounterType::Defense, 2).unwrap();
                        }
                        let mut original = CardDefinitionBuilder::new(
                            CardId::new(),
                            "Original entry presentation",
                        )
                        .card_types(vec![old_type])
                        .with_ability(Ability::static_ability(
                            StaticAbility::enters_with_counters(CounterType::Charge, 11),
                        ))
                        .with_trigger(
                            Trigger::this_enters_battlefield(),
                            vec![Effect::gain_life(11)],
                        );
                        if old_type == CardType::Creature {
                            original = original.power_toughness(PowerToughness::fixed(3, 4));
                        }
                        let old =
                            game.create_object_from_definition(&original.build(), owner, origin);
                        let stable = game.object(old).unwrap().stable_id;
                        game.effect_store.replacement_effects.add_one_shot_effect(
                            ReplacementEffect::with_matcher(
                                donor,
                                donor_owner,
                                WouldEnterBattlefieldMatcher::any().with_stable_id(stable),
                                ReplacementAction::EnterAsCopy {
                                    source: donor,
                                    enters_tapped: false,
                                    copy_duration: None,
                                    linked_exile_objects: vec![],
                                    additional_counters: vec![],
                                    name_override: None,
                                    added_colors: ColorSet::default(),
                                    added_card_types: vec![],
                                    removes_other_card_types: false,
                                    added_supertypes: vec![],
                                    removed_supertypes: vec![],
                                    added_subtypes: vec![],
                                    added_abilities: vec![],
                                    set_base_power_toughness: None,
                                    copy_followups: vec![],
                                },
                            ),
                        );
                        let instruction_source = game.create_object_from_definition(
                            &CardDefinitionBuilder::new(CardId::new(), "Copy entry instruction")
                                .card_types(vec![CardType::Artifact])
                                .build(),
                            actor,
                            Zone::Battlefield,
                        );
                        game.stack.push(StackEntry::ability(
                            instruction_source,
                            actor,
                            vec![Effect::new(
                                MoveToZoneEffect::new(
                                    ChooseSpec::SpecificObject(old),
                                    Zone::Battlefield,
                                    false,
                                )
                                .under_you_control(),
                            )],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let copy = game.find_object_by_stable_id(stable).unwrap();
                        let label = format!(
                            "donor={donor_type:?} old={old_type:?} origin={origin:?} owner={owner:?} actor={actor:?}"
                        );
                        assert_ne!(copy, old);
                        assert_eq!(game.object(copy).unwrap().zone, Zone::Battlefield);
                        assert_eq!(game.object(copy).unwrap().owner, owner);
                        if game.current_controller(copy) != Some(actor)
                            || game.current_name(copy).as_deref() != Some("Copied entry donor")
                            || game.current_card_types(copy) != Some(vec![donor_type])
                            || game.counter_count(copy, CounterType::Charge) != 2
                        {
                            discrepancies.push(format!(
                                "{label}: copied control/name/types/charge {:?}/{:?}/{:?}/{}",
                                game.current_controller(copy),
                                game.current_name(copy),
                                game.current_card_types(copy),
                                game.counter_count(copy, CounterType::Charge)
                            ));
                        }
                        if donor_type == CardType::Creature
                            && (game.current_power(copy), game.current_toughness(copy))
                                != (Some(5), Some(6))
                        {
                            discrepancies.push(format!("{label}: copied creature P/T"));
                        }
                        for (kind, expected) in [
                            (
                                CounterType::Loyalty,
                                if donor_type == CardType::Planeswalker {
                                    3
                                } else {
                                    0
                                },
                            ),
                            (
                                CounterType::Defense,
                                if donor_type == CardType::Battle { 3 } else { 0 },
                            ),
                        ] {
                            if game.counter_count(copy, kind) != expected {
                                discrepancies.push(format!(
                                    "{label}: {kind:?} {}, required {expected}",
                                    game.counter_count(copy, kind)
                                ));
                            }
                        }
                        assert_eq!(game.counter_count(donor, CounterType::Charge), donor_charge);
                        let mut queue = TriggerQueue::new();
                        ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                        let triggers = game.stack.len();
                        if triggers != 1 {
                            discrepancies
                                .push(format!("{label}: ETB triggers {triggers}, required1"));
                        }
                        for _ in 0..triggers {
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        }
                        if game.player(actor).unwrap().life != 23
                            || game.player(donor_owner).unwrap().life != 20
                        {
                            discrepancies.push(format!(
                                "{label}: copied ETB life actor {}, donor owner {}; required23/20",
                                game.player(actor).unwrap().life,
                                game.player(donor_owner).unwrap().life
                            ));
                        }
                        game.validate_zone_consistency().unwrap();
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 144);
    assert!(
        discrepancies.is_empty(),
        "CR 616.1c/614.12/707.5: copy replacement precedes other entry replacements, and the incoming permanent uses copied entry abilities without copying existing counters: {discrepancies:#?}"
    );
}

#[test]
fn cr_712_14a_single_faced_transformed_entry_attempts_leave_cards_and_choices_unchanged() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::ColorsContext;
    use ironsmith::effects::MoveToZoneEffect;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, Color, CounterType, Effect, PowerToughness,
        StackEntry, StaticAbility, Zone,
    };
    struct Choice {
        players: Vec<PlayerId>,
    }
    impl DecisionMaker for Choice {
        fn decide_colors(&mut self, _: &GameState, ctx: &ColorsContext) -> Vec<Color> {
            self.players.push(ctx.player);
            vec![Color::Red]
        }
    }
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for kind in [
        CardType::Artifact,
        CardType::Battle,
        CardType::Creature,
        CardType::Enchantment,
        CardType::Land,
        CardType::Planeswalker,
        CardType::Instant,
        CardType::Sorcery,
    ] {
        for transformed in [false, true] {
            for origin in [
                Zone::Hand,
                Zone::Library,
                Zone::Graveyard,
                Zone::Exile,
                Zone::Stack,
                Zone::Command,
            ] {
                for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        let mut card = CardDefinitionBuilder::new(
                            CardId::new(),
                            "Single-faced entry candidate",
                        )
                        .card_types(vec![kind])
                        .with_ability(Ability::static_ability(
                            StaticAbility::choose_color_as_enters(
                                None,
                                "As this enters, choose a color.".into(),
                            ),
                        ));
                        if kind == CardType::Creature {
                            card = card.power_toughness(PowerToughness::fixed(3, 4));
                        }
                        if kind == CardType::Planeswalker {
                            card = card.loyalty(3);
                        }
                        if kind == CardType::Battle {
                            card = card.defense(3);
                        }
                        let old = game.create_object_from_definition(&card.build(), owner, origin);
                        let stable = game.object(old).unwrap().stable_id;
                        game.add_counters(old, CounterType::Charge, 1).unwrap();
                        if origin == Zone::Stack {
                            game.stack.push(StackEntry::new(old, owner));
                        }
                        let source = game.create_object_from_definition(
                            &CardDefinitionBuilder::new(
                                CardId::new(),
                                "Single-face entry instruction",
                            )
                            .card_types(vec![CardType::Artifact])
                            .build(),
                            actor,
                            Zone::Battlefield,
                        );
                        let mut entry = MoveToZoneEffect::new(
                            ChooseSpec::SpecificObject(old),
                            Zone::Battlefield,
                            false,
                        )
                        .under_you_control();
                        if transformed {
                            entry = entry.transformed();
                        }
                        game.stack.push(StackEntry::ability(
                            source,
                            actor,
                            vec![Effect::new(entry)],
                        ));
                        let mut dm = Choice { players: vec![] };
                        ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm).unwrap();
                        let current = game.find_object_by_stable_id(stable).unwrap();
                        let object = game.object(current).unwrap();
                        let enters =
                            !transformed && !matches!(kind, CardType::Instant | CardType::Sorcery);
                        let label = format!(
                            "type={kind:?} transformed={transformed} origin={origin:?} owner={owner:?} actor={actor:?}"
                        );
                        if enters {
                            if object.zone != Zone::Battlefield
                                || current == old
                                || game.current_controller(current) != Some(actor)
                                || game.counter_count(current, CounterType::Charge) != 0
                                || dm.players != vec![actor]
                                || game.chosen_color(current) != Some(Color::Red)
                            {
                                discrepancies.push(format!(
                                    "{label}: ordinary permanent entry failed its controls"
                                ));
                            }
                        } else if current != old
                            || object.zone != origin
                            || game.counter_count(current, CounterType::Charge) != 1
                            || !dm.players.is_empty()
                            || game.chosen_color(current).is_some()
                        {
                            discrepancies.push(format!("{label}: prohibited entry changed identity/zone/counters or made an entry choice"));
                        }
                        assert_eq!(object.owner, owner);
                        game.validate_zone_consistency().unwrap();
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 384);
    assert!(
        discrepancies.is_empty(),
        "CR 712.14a/614.7: a single-faced card instructed to enter transformed stays in its source zone without making entry choices: {discrepancies:#?}"
    );
}

#[test]
fn cr_616_1c_f_competing_copy_replacements_precede_other_entry_replacements() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::{MoveToZoneEffect, RegisterNextBatchEnterAsCopyEffect};
    use ironsmith::events::zones::matchers::WouldEnterBattlefieldMatcher;
    use ironsmith::replacement::{ReplacementAction, ReplacementEffect};
    use ironsmith::triggers::Trigger;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, CounterType, Effect, ObjectId, PowerToughness,
        StackEntry, StaticAbility, TriggerQueue, Zone,
    };
    struct Prefer {
        copies: [ObjectId; 2],
        tap: ObjectId,
        first: usize,
        menus: Vec<(PlayerId, Vec<ObjectId>)>,
    }
    impl DecisionMaker for Prefer {
        fn decide_options(&mut self, _: &GameState, ctx: &SelectOptionsContext) -> Vec<usize> {
            let legal: Vec<_> = ctx.options.iter().filter(|o| o.legal).collect();
            self.menus.push((
                ctx.player,
                legal.iter().filter_map(|o| o.object_id).collect(),
            ));
            // If an illegal lower-priority option is exposed, actually choose it.
            // Otherwise choose the requested first copy while both copies apply.
            let preferred = if legal.iter().any(|o| o.object_id == Some(self.tap)) {
                self.tap
            } else {
                self.copies[self.first]
            };
            legal
                .iter()
                .find(|o| o.object_id == Some(preferred))
                .or_else(|| legal.first())
                .map(|o| vec![o.index])
                .unwrap_or_default()
        }
    }
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for order in [
        [0, 1, 2],
        [0, 2, 1],
        [1, 0, 2],
        [1, 2, 0],
        [2, 0, 1],
        [2, 1, 0],
    ] {
        for first in [0, 1] {
            for origin in [Zone::Hand, Zone::Graveyard, Zone::Exile] {
                for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        let other = PlayerId::from_index(1 - actor.index() as u8);
                        let mut donors = Vec::new();
                        for (index, amount) in [2, 5].into_iter().enumerate() {
                            let mut def = CardDefinitionBuilder::new(
                                CardId::new(),
                                format!("Copy choice donor {index}"),
                            )
                            .card_types(vec![if index == 0 {
                                CardType::Artifact
                            } else {
                                CardType::Creature
                            }])
                            .with_ability(Ability::static_ability(
                                StaticAbility::enters_with_counters(CounterType::Charge, amount),
                            ))
                            .with_trigger(
                                Trigger::this_enters_battlefield(),
                                vec![Effect::gain_life(amount)],
                            );
                            if index == 1 {
                                def = def.power_toughness(PowerToughness::fixed(5, 6));
                            }
                            donors.push(game.create_object_from_definition(
                                &def.build(),
                                other,
                                Zone::Battlefield,
                            ));
                        }
                        let source = game.create_object_from_definition(
                            &CardDefinitionBuilder::new(CardId::new(), "Copy priority instruction")
                                .card_types(vec![CardType::Artifact])
                                .build(),
                            actor,
                            Zone::Battlefield,
                        );
                        let original =
                            CardDefinitionBuilder::new(CardId::new(), "Original priority subject")
                                .card_types(vec![CardType::Artifact])
                                .with_ability(Ability::static_ability(
                                    StaticAbility::enters_with_counters(CounterType::Charge, 11),
                                ))
                                .with_trigger(
                                    Trigger::this_enters_battlefield(),
                                    vec![Effect::gain_life(11)],
                                )
                                .build();
                        let old = game.create_object_from_definition(&original, owner, origin);
                        let stable = game.object(old).unwrap().stable_id;
                        let mut registrations = Vec::new();
                        for index in order {
                            if index == 2 {
                                registrations.push(
                                    game.effect_store.replacement_effects.add_one_shot_effect(
                                        ReplacementEffect::with_matcher(
                                            source,
                                            actor,
                                            WouldEnterBattlefieldMatcher::any()
                                                .with_stable_id(stable),
                                            ReplacementAction::EnterTapped,
                                        ),
                                    ),
                                );
                            } else {
                                // Execute the production registration effect. Its priority
                                // metadata must come from the runtime, not this fixture.
                                game.stack.push(StackEntry::ability(
                                    donors[index],
                                    other,
                                    vec![Effect::new(RegisterNextBatchEnterAsCopyEffect::new(
                                        ironsmith::ObjectFilter::specific(old),
                                        ChooseSpec::SpecificObject(donors[index]),
                                    ))],
                                ));
                                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                let id = game.effect_store.replacement_effects.effects().iter()
                                    .find(|effect| effect.source == donors[index] && matches!(
                                        &effect.replacement, ReplacementAction::EnterAsCopy { source, .. } if *source == donors[index]
                                    )).expect("production copy registration must exist").id;
                                registrations.push(id);
                            }
                        }
                        game.stack.push(StackEntry::ability(
                            source,
                            actor,
                            vec![Effect::new(
                                MoveToZoneEffect::new(
                                    ChooseSpec::SpecificObject(old),
                                    Zone::Battlefield,
                                    false,
                                )
                                .under_you_control(),
                            )],
                        ));
                        let mut dm = Prefer {
                            copies: [donors[0], donors[1]],
                            tap: source,
                            first,
                            menus: vec![],
                        };
                        ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm).unwrap();
                        let current = game.find_object_by_stable_id(stable).unwrap();
                        let last = 1 - first;
                        let amount = if last == 0 { 2 } else { 5 };
                        let label = format!(
                            "order={order:?} first={first} origin={origin:?} owner={owner:?} actor={actor:?}"
                        );
                        if dm.menus.len() != 1
                            || dm.menus[0].0 != actor
                            || dm.menus[0].1.len() != 2
                            || !dm.menus[0].1.contains(&donors[0])
                            || !dm.menus[0].1.contains(&donors[1])
                        {
                            discrepancies.push(format!("{label}: copy-priority menu {:?}, required only both copy replacements for the entering controller",dm.menus));
                        }
                        if game.object(current).unwrap().zone != Zone::Battlefield
                            || game.current_name(current)
                                != Some(format!("Copy choice donor {last}"))
                            || game.counter_count(current, CounterType::Charge) != amount
                            || !game.is_tapped(current)
                            || game.current_controller(current) != Some(actor)
                        {
                            discrepancies.push(format!("{label}: final name/charge/tapped/controller {:?}/{}/{}/{:?}, required last copy and subsequent tap",game.current_name(current),game.counter_count(current,CounterType::Charge),game.is_tapped(current),game.current_controller(current)));
                        }
                        for id in registrations {
                            if game
                                .effect_store
                                .replacement_effects
                                .get_effect(id)
                                .is_some()
                            {
                                discrepancies.push(format!(
                                    "{label}: a mandatory one-shot replacement was not consumed"
                                ));
                            }
                        }
                        assert_eq!(game.object(current).unwrap().owner, owner);
                        let mut queue = TriggerQueue::new();
                        ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                        let n = game.stack.len();
                        if n != 1 {
                            discrepancies.push(format!("{label}: final copy triggered{n} times"));
                        }
                        for _ in 0..n {
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        }
                        if game.player(actor).unwrap().life != 20 + amount as i32
                            || game.player(other).unwrap().life != 20
                        {
                            discrepancies
                                .push(format!("{label}: final copied trigger life mismatch"));
                        }
                        game.validate_zone_consistency().unwrap();
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 144);
    assert!(
        discrepancies.is_empty(),
        "CR 616.1c/f: choose a copy replacement before lower-priority entry effects, repeat for the remaining copy, and use only the final copied entry abilities: {discrepancies:#?}"
    );
}

#[test]
fn cr_712_13a_702_145b_resolving_daybound_spells_with_nonpermanent_backs_go_to_graveyard_at_night()
{
    use ironsmith::card::LinkedFaceLayout;
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::{DayNightDesignation, SetDayNightEffect};
    use ironsmith::triggers::Trigger;
    use ironsmith::{
        Ability, CardId, CardType, Effect, PowerToughness, StackEntry, StaticAbility, TriggerQueue,
        Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for back_type in [
        CardType::Creature,
        CardType::Artifact,
        CardType::Instant,
        CardType::Sorcery,
    ] {
        for transforming in [false, true] {
            for night in [false, true] {
                for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    for caster in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        let source = game.create_object_from_definition(
                            &CardDefinitionBuilder::new(
                                CardId::new(),
                                "Night entry resolution observer",
                            )
                            .card_types(vec![CardType::Artifact])
                            .build(),
                            caster,
                            Zone::Battlefield,
                        );
                        game.stack.push(StackEntry::ability(
                            source,
                            caster,
                            vec![Effect::new(SetDayNightEffect::new(if night {
                                DayNightDesignation::Night
                            } else {
                                DayNightDesignation::Day
                            }))],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        assert!(game.has_day_night);
                        assert_eq!(game.is_night, night);
                        let front_id = CardId::new();
                        let back_id = CardId::new();
                        let mut front =
                            CardDefinitionBuilder::new(front_id, "Daybound resolving front")
                                .card_types(vec![CardType::Creature])
                                .power_toughness(PowerToughness::fixed(3, 4))
                                .other_face(back_id)
                                .other_face_name("Nightbound resolving back")
                                .linked_face_layout(LinkedFaceLayout::TransformLike)
                                .with_ability(Ability::static_ability(StaticAbility::daybound()))
                                .with_trigger(
                                    Trigger::this_enters_battlefield(),
                                    vec![Effect::gain_life(3)],
                                )
                                .build();
                        let mut back_builder =
                            CardDefinitionBuilder::new(back_id, "Nightbound resolving back")
                                .card_types(vec![back_type])
                                .other_face(front_id)
                                .other_face_name("Daybound resolving front")
                                .linked_face_layout(LinkedFaceLayout::TransformLike)
                                .with_ability(Ability::static_ability(StaticAbility::nightbound()))
                                .with_trigger(
                                    Trigger::this_enters_battlefield(),
                                    vec![Effect::gain_life(5)],
                                );
                        if back_type == CardType::Creature {
                            back_builder =
                                back_builder.power_toughness(PowerToughness::fixed(5, 6));
                        }
                        let mut back = back_builder.build();
                        front.card.transforming_dfc = transforming;
                        back.card.transforming_dfc = transforming;
                        game.register_linked_face_definition(&front);
                        game.register_linked_face_definition(&back);
                        let spell = game.create_object_from_definition(&front, owner, Zone::Stack);
                        let stable = game.object(spell).unwrap().stable_id;
                        game.stage_initial_controller_for_assembly(spell, caster);
                        game.stack.push(StackEntry::new(spell, caster));
                        let label = format!(
                            "back={back_type:?} transforming={transforming} night={night} owner={owner:?} caster={caster:?}"
                        );
                        if let Err(error) = ironsmith::game_loop::resolve_stack_entry(&mut game) {
                            discrepancies.push(format!(
                                "{label}: resolution unexpectedly failed: {error:?}"
                            ));
                        }
                        let Some(current) = game.find_object_by_stable_id(stable) else {
                            discrepancies.push(format!("{label}: lost physical card"));
                            cases += 1;
                            continue;
                        };
                        let enters =
                            !night || !matches!(back_type, CardType::Instant | CardType::Sorcery);
                        let expected_zone = if enters {
                            Zone::Battlefield
                        } else {
                            Zone::Graveyard
                        };
                        if game.object(current).unwrap().zone != expected_zone
                            || current == spell
                            || game.object(current).unwrap().owner != owner
                        {
                            discrepancies.push(format!("{label}: resulting zone/id/owner {:?}/{current:?}/{:?}, required new object in {expected_zone:?} owned by{owner:?}",game.object(current).unwrap().zone,game.object(current).unwrap().owner));
                        }
                        let expected_name = if enters && night {
                            "Nightbound resolving back"
                        } else {
                            "Daybound resolving front"
                        };
                        if game.current_name(current).as_deref() != Some(expected_name) {
                            discrepancies.push(format!(
                                "{label}: resulting face {:?}, required {expected_name}",
                                game.current_name(current)
                            ));
                        }
                        if enters && game.current_controller(current) != Some(caster) {
                            discrepancies.push(format!("{label}: incorrect entering controller"));
                        }
                        let baseline = game.stack.len();
                        let mut queue = TriggerQueue::new();
                        ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                        let n = game.stack.len() - baseline;
                        if n != usize::from(enters) {
                            discrepancies.push(format!(
                                "{label}: ETB triggers{n}, required{}",
                                usize::from(enters)
                            ));
                        }
                        for _ in 0..n {
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        }
                        let expected_life = 20
                            + if !enters {
                                0
                            } else if night {
                                5
                            } else {
                                3
                            };
                        if game.player(caster).unwrap().life != expected_life {
                            discrepancies.push(format!(
                                "{label}: ETB life{}, required{expected_life}",
                                game.player(caster).unwrap().life
                            ));
                        }
                        if let Err(error) = game.validate_zone_consistency() {
                            discrepancies.push(format!("{label}: inconsistent zones: {error:?}"));
                        }
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 64);
    assert!(
        discrepancies.is_empty(),
        "CR 712.13a/702.145b: a resolving daybound spell that must enter transformed cannot enter with an instant/sorcery back and goes to its owner's graveyard, without ETB: {discrepancies:#?}"
    );
}

#[test]
fn cr_614_12_702_145b_night_entries_use_the_back_faces_static_entry_programs() {
    use ironsmith::card::LinkedFaceLayout;
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::{DayNightDesignation, SetDayNightEffect};
    use ironsmith::triggers::Trigger;
    use ironsmith::{
        Ability, CardId, CardType, CounterType, Effect, PowerToughness, StackEntry, StaticAbility,
        TriggerQueue, Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for back_type in [CardType::Creature, CardType::Artifact] {
        for transforming in [false, true] {
            for night in [false, true] {
                for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    for caster in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        let source = game.create_object_from_definition(
                            &CardDefinitionBuilder::new(
                                CardId::new(),
                                "Static entry face observer",
                            )
                            .card_types(vec![CardType::Artifact])
                            .build(),
                            caster,
                            Zone::Battlefield,
                        );
                        game.stack.push(StackEntry::ability(
                            source,
                            caster,
                            vec![Effect::new(SetDayNightEffect::new(if night {
                                DayNightDesignation::Night
                            } else {
                                DayNightDesignation::Day
                            }))],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let front_id = CardId::new();
                        let back_id = CardId::new();
                        let mut front = CardDefinitionBuilder::new(front_id, "Static entry front")
                            .card_types(vec![CardType::Creature])
                            .power_toughness(PowerToughness::fixed(3, 4))
                            .other_face(back_id)
                            .other_face_name("Static entry back")
                            .linked_face_layout(LinkedFaceLayout::TransformLike)
                            .with_ability(Ability::static_ability(StaticAbility::daybound()))
                            .with_ability(Ability::static_ability(
                                StaticAbility::enters_with_counters(CounterType::Charge, 2),
                            ))
                            .with_trigger(
                                Trigger::this_enters_battlefield(),
                                vec![Effect::gain_life(3)],
                            )
                            .build();
                        let mut back = CardDefinitionBuilder::new(back_id, "Static entry back")
                            .card_types(vec![back_type])
                            .other_face(front_id)
                            .other_face_name("Static entry front")
                            .linked_face_layout(LinkedFaceLayout::TransformLike)
                            .with_ability(Ability::static_ability(StaticAbility::nightbound()))
                            .with_ability(Ability::static_ability(
                                StaticAbility::enters_with_counters(CounterType::Charge, 5),
                            ))
                            .with_trigger(
                                Trigger::this_enters_battlefield(),
                                vec![Effect::gain_life(7)],
                            );
                        if back_type == CardType::Creature {
                            back = back.power_toughness(PowerToughness::fixed(5, 6));
                        }
                        let mut back = back.build();
                        front.card.transforming_dfc = transforming;
                        back.card.transforming_dfc = transforming;
                        game.register_linked_face_definition(&front);
                        game.register_linked_face_definition(&back);
                        let spell = game.create_object_from_definition(&front, owner, Zone::Stack);
                        let stable = game.object(spell).unwrap().stable_id;
                        game.stage_initial_controller_for_assembly(spell, caster);
                        game.stack.push(StackEntry::new(spell, caster));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let current = game.find_object_by_stable_id(stable).unwrap();
                        let label = format!(
                            "back={back_type:?} transforming={transforming} night={night} owner={owner:?} caster={caster:?}"
                        );
                        assert_ne!(current, spell);
                        assert_eq!(game.object(current).unwrap().zone, Zone::Battlefield);
                        assert_eq!(game.object(current).unwrap().owner, owner);
                        assert_eq!(game.current_controller(current), Some(caster));
                        assert_eq!(
                            game.current_name(current).as_deref(),
                            Some(if night {
                                "Static entry back"
                            } else {
                                "Static entry front"
                            })
                        );
                        assert_eq!(
                            game.current_card_types(current),
                            Some(vec![if night { back_type } else { CardType::Creature }])
                        );
                        let expected = if night { 5 } else { 2 };
                        let actual = game.counter_count(current, CounterType::Charge);
                        if actual != expected {
                            discrepancies.push(format!(
                                "{label}: static entry charge counters{actual}, required{expected}"
                            ));
                        }
                        let mut queue = TriggerQueue::new();
                        ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                        assert_eq!(game.stack.len(), 1);
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        assert_eq!(
                            game.player(caster).unwrap().life,
                            if night { 27 } else { 23 }
                        );
                        game.validate_zone_consistency().unwrap();
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 32);
    assert!(
        discrepancies.is_empty(),
        "CR 614.12/702.145b: a legal transformed night entry must use the back faces static entry abilities before entry, just as it uses that faces ETB trigger: {discrepancies:#?}"
    );
}

#[test]
fn cr_614_12b_simultaneous_entry_choices_cannot_overcommit_combined_life_costs() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::ReturnAllToBattlefieldEffect;
    use ironsmith::{
        Ability, CardId, CardType, Effect, ObjectFilter, ObjectId, StackEntry, StaticAbility, Zone,
    };
    struct Pay {
        accept: bool,
        old: Vec<ObjectId>,
        observations: Vec<(PlayerId, i32, bool, usize)>,
    }
    impl DecisionMaker for Pay {
        fn decide_boolean(&mut self, game: &GameState, ctx: &BooleanContext) -> bool {
            self.observations.push((
                ctx.player,
                game.player(ctx.player).unwrap().life,
                self.old
                    .iter()
                    .all(|id| game.object(*id).is_some_and(|o| o.zone == Zone::Graveyard)),
                game.battlefield.len(),
            ));
            self.accept
        }
    }
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for count in 2usize..=4 {
        for life in 1i32..=8 {
            for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    for accept in [false, true] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        game.player_mut(owner).unwrap().life = life;
                        let source = game.create_object_from_definition(
                            &CardDefinitionBuilder::new(
                                CardId::new(),
                                "Simultaneous return instruction",
                            )
                            .card_types(vec![CardType::Artifact])
                            .build(),
                            actor,
                            Zone::Battlefield,
                        );
                        let mut old = Vec::new();
                        let mut stable = Vec::new();
                        for index in 0..count {
                            let def = CardDefinitionBuilder::new(
                                CardId::new(),
                                format!("Simultaneous life-cost land {index}"),
                            )
                            .card_types(vec![CardType::Land])
                            .with_ability(Ability::static_ability(
                                StaticAbility::pay_life_or_enter_tapped(2),
                            ))
                            .build();
                            let id =
                                game.create_object_from_definition(&def, owner, Zone::Graveyard);
                            old.push(id);
                            stable.push(game.object(id).unwrap().stable_id);
                        }
                        let mut dm = Pay {
                            accept,
                            old: old.clone(),
                            observations: vec![],
                        };
                        game.stack.push(StackEntry::ability(
                            source,
                            actor,
                            vec![Effect::new(
                                ReturnAllToBattlefieldEffect::new(
                                    ObjectFilter::permanent_card().in_zone(Zone::Graveyard),
                                    false,
                                )
                                .under_owner_control(),
                            )],
                        ));
                        ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm).unwrap();
                        let paid = if accept {
                            count.min((life / 2) as usize)
                        } else {
                            0
                        };
                        let expected_offers = if life < 2 {
                            0
                        } else if accept {
                            paid
                        } else {
                            count
                        };
                        let label = format!(
                            "count={count} life={life} owner={owner:?} actor={actor:?} accept={accept}"
                        );
                        if dm.observations.len() != expected_offers {
                            discrepancies.push(format!(
                                "{label}: cost offers{}, required{expected_offers}",
                                dm.observations.len()
                            ));
                        }
                        for (index, (chooser, at_choice, all_original, field_size)) in
                            dm.observations.iter().enumerate()
                        {
                            let expected_life = life - if accept { 2 * index as i32 } else { 0 };
                            if *chooser != owner
                                || *at_choice != expected_life
                                || !*all_original
                                || *field_size != 1
                            {
                                discrepancies.push(format!("{label}: choice{index} saw{chooser:?}/life{at_choice}/originals{all_original}/battlefield{field_size}, required owner/life{expected_life}/all originals/no entrant"));
                            }
                        }
                        if game.player(owner).unwrap().life != life - 2 * paid as i32 {
                            discrepancies.push(format!("{label}: wrong combined life payment"));
                        }
                        let mut untapped = 0;
                        for (index, id) in stable.iter().enumerate() {
                            let current = game.find_object_by_stable_id(*id).unwrap();
                            assert_ne!(current, old[index]);
                            assert!(game.object(old[index]).is_none());
                            assert_eq!(game.object(current).unwrap().zone, Zone::Battlefield);
                            assert_eq!(game.object(current).unwrap().owner, owner);
                            assert_eq!(game.current_controller(current), Some(owner));
                            untapped += usize::from(!game.is_tapped(current));
                        }
                        if untapped != paid {
                            discrepancies.push(format!(
                                "{label}: untapped entries{untapped}, required{paid}"
                            ));
                        }
                        assert_eq!(game.battlefield.len(), count + 1);
                        assert!(game.stack.is_empty());
                        game.validate_zone_consistency().unwrap();
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 192);
    assert!(
        discrepancies.is_empty(),
        "CR 614.12b: choices for simultaneous entrants must reserve earlier payments and never select combined costs the player cannot pay: {discrepancies:#?}"
    );
}

#[test]
fn cr_608_2h_707_2_next_batch_copies_use_current_or_last_known_copiable_values() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::continuous::EffectTarget;
    use ironsmith::effects::{
        ApplyContinuousEffect, MoveToZoneEffect, RegisterNextBatchEnterAsCopyEffect,
        RuntimeModification,
    };
    use ironsmith::triggers::Trigger;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, CounterType, Effect, PowerToughness, StackEntry,
        StaticAbility, TriggerQueue, Until, Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for mode in 0..5 {
        for destination in [Zone::Graveyard, Zone::Exile] {
            for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                    let other = PlayerId::from_index(1 - actor.index() as u8);
                    let source = game.create_object_from_definition(
                        &CardDefinitionBuilder::new(CardId::new(), "Deferred copy source")
                            .card_types(vec![CardType::Artifact])
                            .build(),
                        actor,
                        Zone::Battlefield,
                    );
                    let donor_def =
                        CardDefinitionBuilder::new(CardId::new(), "Original deferred donor")
                            .card_types(vec![CardType::Creature])
                            .power_toughness(PowerToughness::fixed(3, 4))
                            .with_ability(Ability::static_ability(StaticAbility::flying()))
                            .with_ability(Ability::static_ability(
                                StaticAbility::enters_with_counters(CounterType::Charge, 2),
                            ))
                            .with_trigger(
                                Trigger::this_enters_battlefield(),
                                vec![Effect::gain_life(3)],
                            )
                            .build();
                    let donor =
                        game.create_object_from_definition(&donor_def, other, Zone::Battlefield);
                    let donor_stable = game.object(donor).unwrap().stable_id;
                    game.add_counters(donor, CounterType::Charge, 7).unwrap();
                    let template = game.create_object_from_definition(
                        &CardDefinitionBuilder::new(CardId::new(), "Updated deferred donor")
                            .card_types(vec![CardType::Creature])
                            .power_toughness(PowerToughness::fixed(5, 6))
                            .with_ability(Ability::static_ability(StaticAbility::reach()))
                            .with_ability(Ability::static_ability(
                                StaticAbility::enters_with_counters(CounterType::Charge, 5),
                            ))
                            .with_trigger(
                                Trigger::this_enters_battlefield(),
                                vec![Effect::gain_life(5)],
                            )
                            .build(),
                        other,
                        Zone::Battlefield,
                    );
                    let recipient = game.create_object_from_definition(
                        &CardDefinitionBuilder::new(CardId::new(), "Uncopied recipient")
                            .card_types(vec![CardType::Creature])
                            .power_toughness(PowerToughness::fixed(7, 8))
                            .build(),
                        owner,
                        Zone::Hand,
                    );
                    let stable = game.object(recipient).unwrap().stable_id;
                    // A narrow filter isolates this recipient from an optional donor reentry.
                    game.stack.push(StackEntry::ability(
                        source,
                        actor,
                        vec![Effect::new(RegisterNextBatchEnterAsCopyEffect::new(
                            ironsmith::ObjectFilter::specific(recipient),
                            ChooseSpec::SpecificObject(donor),
                        ))],
                    ));
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    let copy_effect = |target| {
                        Effect::new(ApplyContinuousEffect::new_runtime(
                            EffectTarget::Specific(target),
                            RuntimeModification::CopyOf {
                                source: ChooseSpec::SpecificObject(template),
                                preserve_source_abilities: false,
                                name_override: None,
                                name_override_surface: None,
                                add_supertypes: vec![],
                                copy_exception_surface: None,
                            },
                            Until::Forever,
                        ))
                    };
                    if mode == 2 || mode == 4 {
                        game.stack.push(StackEntry::ability(
                            source,
                            actor,
                            vec![copy_effect(donor)],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        assert_eq!(
                            game.current_name(donor).as_deref(),
                            Some("Updated deferred donor")
                        );
                    }
                    if (1..=3).contains(&mode) {
                        game.stack.push(StackEntry::ability(
                            source,
                            actor,
                            vec![Effect::new(MoveToZoneEffect::new(
                                ChooseSpec::SpecificObject(donor),
                                destination,
                                false,
                            ))],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        assert!(game.object(donor).is_none());
                    }
                    if mode == 3 {
                        let departed = game.find_object_by_stable_id(donor_stable).unwrap();
                        game.stack.push(StackEntry::ability(
                            source,
                            actor,
                            vec![Effect::new(
                                MoveToZoneEffect::new(
                                    ChooseSpec::SpecificObject(departed),
                                    Zone::Battlefield,
                                    false,
                                )
                                .under_owner_control(),
                            )],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let returned = game.find_object_by_stable_id(donor_stable).unwrap();
                        assert_ne!(returned, donor);
                        // Finish the donor's return trigger before resolving a
                        // separate ability that changes its new incarnation.
                        let mut returned_queue = TriggerQueue::new();
                        ironsmith::put_triggers_on_stack(&mut game, &mut returned_queue).unwrap();
                        while !game.stack.is_empty() {
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        }
                        game.stack.push(StackEntry::ability(
                            source,
                            actor,
                            vec![copy_effect(returned)],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        assert_eq!(
                            game.current_name(returned).as_deref(),
                            Some("Updated deferred donor")
                        );
                    }
                    let mut setup_queue = TriggerQueue::new();
                    ironsmith::put_triggers_on_stack(&mut game, &mut setup_queue).unwrap();
                    while !game.stack.is_empty() {
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    }
                    let life_before = game.player(actor).unwrap().life;
                    let other_before = game.player(other).unwrap().life;
                    game.stack.push(StackEntry::ability(
                        source,
                        actor,
                        vec![Effect::new(
                            MoveToZoneEffect::new(
                                ChooseSpec::SpecificObject(recipient),
                                Zone::Battlefield,
                                false,
                            )
                            .under_you_control(),
                        )],
                    ));
                    let label = format!(
                        "mode={mode} departure={destination:?} actor={actor:?} owner={owner:?}"
                    );
                    if let Err(error) = ironsmith::game_loop::resolve_stack_entry(&mut game) {
                        discrepancies
                            .push(format!("{label}: deferred copy entry failed: {error:?}"));
                    }
                    let Some(current) = game.find_object_by_stable_id(stable) else {
                        discrepancies.push(format!("{label}: recipient disappeared"));
                        cases += 1;
                        continue;
                    };
                    let updated = mode == 2 || mode == 4;
                    let name = if updated {
                        "Updated deferred donor"
                    } else {
                        "Original deferred donor"
                    };
                    let pt = if updated {
                        (Some(5), Some(6))
                    } else {
                        (Some(3), Some(4))
                    };
                    let amount = if updated { 5 } else { 2 };
                    let gain = if updated { 5 } else { 3 };
                    if game.object(current).unwrap().zone != Zone::Battlefield
                        || game.object(current).unwrap().owner != owner
                        || game.current_controller(current) != Some(actor)
                        || game.current_name(current).as_deref() != Some(name)
                        || (game.current_power(current), game.current_toughness(current)) != pt
                        || game.counter_count(current, CounterType::Charge) != amount
                        || game.object_has_ability(current, &StaticAbility::flying()) == updated
                        || game.object_has_ability(current, &StaticAbility::reach()) != updated
                    {
                        discrepancies.push(format!("{label}: zone/name/PT/charge {:?}/{:?}/{:?}/{}, required battlefield {name}/{pt:?}/{amount} with the selected donor abilities",game.object(current).unwrap().zone,game.current_name(current),(game.current_power(current),game.current_toughness(current)),game.counter_count(current,CounterType::Charge)));
                    }
                    let baseline = game.stack.len();
                    let mut queue = TriggerQueue::new();
                    ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                    let n = game.stack.len() - baseline;
                    if n != 1 {
                        discrepancies
                            .push(format!("{label}: copied ETB trigger count{n}, required1"));
                    }
                    for _ in 0..n {
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    }
                    if game.player(actor).unwrap().life != life_before + gain
                        || game.player(other).unwrap().life != other_before
                    {
                        discrepancies.push(format!("{label}: copied ETB life result incorrect"));
                    }
                    if let Err(error) = game.validate_zone_consistency() {
                        discrepancies.push(format!("{label}: inconsistent zones {error:?}"));
                    }
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 40);
    assert!(
        discrepancies.is_empty(),
        "CR 608.2h/707.2: deferred next-batch copies use the current donor if still in the expected zone or its last-known copiable values after departure, never the returned new object: {discrepancies:#?}"
    );
}


fn check_simultaneous_generic_entry_costs(resource: u8) {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::{ManaPaymentContext, SelectObjectsContext};
    use ironsmith::effect::{EffectId, EffectPredicate};
    use ironsmith::effects::{MayEffect, PayManaEffect, ReturnAllToBattlefieldEffect};
    use ironsmith::mana_payment::ManaPaymentResponse;
    use ironsmith::{Ability, CardId, CardType, ChooseSpec, Effect, ManaCost, ManaSymbol,
        ObjectFilter, ObjectId, PowerToughness, StackEntry, StaticAbility, Zone};
    struct Pay { accept: bool, owner: PlayerId, entrants: Vec<ObjectId>, observations: Vec<(PlayerId, bool)> }
    impl DecisionMaker for Pay {
        fn decide_boolean(&mut self, game: &GameState, ctx: &BooleanContext) -> bool {
            self.observations.push((ctx.player, self.entrants.iter().all(|id|
                game.object(*id).is_some_and(|o| o.zone == Zone::Graveyard))));
            self.accept
        }
        fn decide_objects(&mut self, _: &GameState, ctx: &SelectObjectsContext) -> Vec<ObjectId> {
            assert_eq!(ctx.player, self.owner);
            ctx.candidates.iter().filter(|c| c.legal).take(ctx.min).map(|c| c.id).collect()
        }
        fn decide_mana_payment(&mut self, _: &GameState, ctx: &ManaPaymentContext) -> ManaPaymentResponse {
            assert_eq!(ctx.player, self.owner);
            if ctx.plan.payable { ManaPaymentResponse::Confirm { plan_id: ctx.plan.id, request_hash: ctx.plan.request_hash } }
            else { ManaPaymentResponse::Cancel }
        }
    }
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for count in 2usize..=4 {
        for available in 0usize..=4 {
            for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    for accept in [false, true] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        let source = game.create_object_from_definition(&CardDefinitionBuilder::new(CardId::new(), "Generic return instruction")
                            .card_types(vec![CardType::Artifact]).build(), actor, Zone::Battlefield);
                        let mut resources = Vec::new();
                        if resource == 0 {
                            game.player_mut(owner).unwrap().mana_pool.add(ManaSymbol::Colorless, available as u32);
                        } else {
                            for index in 0..available {
                                let def = CardDefinitionBuilder::new(CardId::new(), format!("Payment resource {index}"))
                                    .card_types(vec![if resource == 1 { CardType::Creature } else { CardType::Artifact }])
                                    .power_toughness(PowerToughness::fixed(2, 3)).build();
                                resources.push(game.create_object_from_definition(&def, owner,
                                    if resource == 1 { Zone::Battlefield } else { Zone::Hand }));
                            }
                        }
                        let cost = match resource {
                            0 => Effect::new(PayManaEffect::new(ManaCost::from_symbols(vec![ManaSymbol::Generic(1)]), ChooseSpec::Player(PlayerFilter::You))),
                            1 => Effect::sacrifice(ObjectFilter::creature().you_control(), 1),
                            _ => Effect::discard(1),
                        };
                        let program = vec![
                            Effect::with_id(61412, Effect::new(MayEffect::new(vec![cost]).with_pay_as_cost(true))),
                            Effect::if_then_else(EffectId(61412), EffectPredicate::Happened, vec![Effect::gain_life(1)], vec![]),
                        ];
                        let mut old = Vec::new();
                        let mut stable = Vec::new();
                        for index in 0..count {
                            let def = CardDefinitionBuilder::new(CardId::new(), format!("Generic entry-cost land {index}"))
                                .card_types(vec![CardType::Land]).with_ability(Ability::static_ability(StaticAbility::from_model(
                                    ironsmith::static_abilities::CompiledStaticAbility::as_enters_effect_program(program.clone().into(), "this land", false, false, None)
                                ))).build();
                            let id = game.create_object_from_definition(&def, owner, Zone::Graveyard);
                            old.push(id); stable.push(game.object(id).unwrap().stable_id);
                        }
                        let mut dm = Pay { accept, owner, entrants: old.clone(), observations: vec![] };
                        game.stack.push(StackEntry::ability(source, actor, vec![Effect::new(ReturnAllToBattlefieldEffect::new(
                            ObjectFilter::land().in_zone(Zone::Graveyard), false).under_owner_control())]));
                        let result = ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm);
                        let paid = if accept { count.min(available) } else { 0 };
                        let label = format!("resource={resource} count={count} available={available} owner={owner:?} actor={actor:?} accept={accept}");
                        if let Err(error) = result { discrepancies.push(format!("{label}: resolution error {error:?}")); }
                        let remaining = if resource == 0 { game.player(owner).unwrap().mana_pool.total() as usize }
                            else { resources.iter().filter(|id| game.object(**id).is_some_and(|o| o.zone == if resource == 1 { Zone::Battlefield } else { Zone::Hand })).count() };
                        if remaining != available - paid || game.player(owner).unwrap().life != 20 + paid as i32 {
                            discrepancies.push(format!("{label}: remaining resources{remaining}, life{}; required resources{}, life{}", game.player(owner).unwrap().life, available-paid, 20+paid as i32));
                        }
                        if dm.observations.iter().any(|(chooser, before)| *chooser != owner || !*before) {
                            discrepancies.push(format!("{label}: entry choices had wrong controller or happened after an entrant moved: {:?}",dm.observations));
                        }
                        for (index, sid) in stable.iter().enumerate() {
                            let current = game.find_object_by_stable_id(*sid).unwrap();
                            if current == old[index] || game.object(current).unwrap().zone != Zone::Battlefield || game.current_controller(current) != Some(owner) {
                                discrepancies.push(format!("{label}: entrant{index} has wrong identity, zone or controller"));
                            }
                        }
                        assert_eq!(game.player(PlayerId::from_index(1-owner.index() as u8)).unwrap().life, 20);
                        game.validate_zone_consistency().unwrap();
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 120);
    assert!(discrepancies.is_empty(), "CR614.12b: generic simultaneous entry costs cannot reuse mana or cards already committed to another entrant, and only paid costs satisfy the payment condition: {discrepancies:#?}");
}

#[test]
fn cr_614_12b_generic_simultaneous_entry_mana_costs_share_one_pool() { check_simultaneous_generic_entry_costs(0); }
#[test]
fn cr_614_12b_generic_simultaneous_entry_sacrifices_share_one_battlefield() { check_simultaneous_generic_entry_costs(1); }
#[test]
fn cr_614_12b_generic_simultaneous_entry_discards_share_one_hand() { check_simultaneous_generic_entry_costs(2); }


fn check_entry_zone_choice_exclusions(discard: bool) {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::SelectObjectsContext;
    use ironsmith::effect::{EffectId, EffectPredicate};
    use ironsmith::effects::{ExileEffect, MayEffect, ReturnAllToBattlefieldEffect};
    use ironsmith::{
        Ability, CardId, CardType, ChoiceCount, ChooseSpec, Effect, ObjectFilter, ObjectId,
        PowerToughness, StackEntry, StaticAbility, Zone,
    };
    struct Pick {
        take: bool,
        owner: PlayerId,
        origin: Zone,
        old: Vec<ObjectId>,
        resources: Vec<ObjectId>,
        menus: Vec<Vec<ObjectId>>,
        errors: Vec<String>,
    }
    impl DecisionMaker for Pick {
        fn decide_boolean(&mut self, _: &GameState, ctx: &BooleanContext) -> bool {
            if ctx.player != self.owner {
                self.errors.push("wrong optional-cost chooser".into());
            }
            self.take
        }
        fn decide_objects(
            &mut self,
            game: &GameState,
            ctx: &SelectObjectsContext,
        ) -> Vec<ObjectId> {
            let legal: Vec<_> = ctx
                .candidates
                .iter()
                .filter(|c| c.legal)
                .map(|c| c.id)
                .collect();
            if ctx.player != self.owner || legal.iter().any(|id| !self.resources.contains(id)) {
                self.errors
                    .push(format!("illegal chooser/candidate menu {legal:?}"));
            }
            if !self
                .old
                .iter()
                .all(|id| game.object(*id).is_some_and(|o| o.zone == self.origin))
            {
                self.errors
                    .push("an entrant moved before all entry choices finished".into());
            }
            self.menus.push(legal.clone());
            if self.take {
                legal
                    .into_iter()
                    .take(ctx.max.unwrap_or(usize::MAX))
                    .collect()
            } else {
                vec![]
            }
        }
    }
    let origin = if discard { Zone::Hand } else { Zone::Graveyard };
    let destination = if discard {
        Zone::Graveyard
    } else {
        Zone::Exile
    };
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for count in 1usize..=3 {
        for available in 0usize..=3 {
            for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    for take in [false, true] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        let source = game.create_object_from_definition(
                            &CardDefinitionBuilder::new(
                                CardId::new(),
                                "Entry-zone-choice instruction",
                            )
                            .card_types(vec![CardType::Artifact])
                            .build(),
                            actor,
                            Zone::Battlefield,
                        );
                        let resource_def = CardDefinitionBuilder::new(
                            CardId::new(),
                            "Nonentering creature resource",
                        )
                        .card_types(vec![CardType::Creature])
                        .power_toughness(PowerToughness::fixed(2, 3))
                        .build();
                        let mut resources = Vec::new();
                        let mut resource_stable = Vec::new();
                        for _ in 0..available {
                            let id =
                                game.create_object_from_definition(&resource_def, owner, origin);
                            resources.push(id);
                            resource_stable.push(game.object(id).unwrap().stable_id);
                        }
                        let other = PlayerId::from_index(1 - owner.index() as u8);
                        let foreign =
                            game.create_object_from_definition(&resource_def, other, origin);
                        let program = if discard {
                            vec![
                                Effect::with_id(
                                    61413,
                                    Effect::new(
                                        MayEffect::new(vec![Effect::discard(1)])
                                            .with_pay_as_cost(true),
                                    ),
                                ),
                                Effect::if_then_else(
                                    EffectId(61413),
                                    EffectPredicate::Happened,
                                    vec![Effect::gain_life(1)],
                                    vec![],
                                ),
                            ]
                        } else {
                            vec![
                                Effect::choose_objects(
                                    ObjectFilter::creature()
                                        .in_zone(origin)
                                        .owned_by(PlayerFilter::You),
                                    ChoiceCount::any_number(),
                                    PlayerFilter::You,
                                    "entry_exiled",
                                ),
                                Effect::new(ExileEffect::with_spec(ChooseSpec::tagged(
                                    "entry_exiled",
                                ))),
                            ]
                        };
                        let mut old = Vec::new();
                        let mut stable = Vec::new();
                        for index in 0..count {
                            let mut def = CardDefinitionBuilder::new(
                                CardId::new(),
                                format!("Simultaneous land creature {index}"),
                            )
                            .card_types(vec![CardType::Land, CardType::Creature])
                            .power_toughness(PowerToughness::fixed(3, 4));
                            // Two distinct exile replacements also test that a chosen graveyard
                            // card is not offered again by another as-enters replacement.
                            for _ in 0..if discard { 1 } else { 2 } {
                                def = def.with_ability(Ability::static_ability(StaticAbility::from_model(
                                    ironsmith::static_abilities::CompiledStaticAbility::as_enters_effect_program(
                                        program.clone().into(),"this creature",false,false,None))));
                            }
                            let id =
                                game.create_object_from_definition(&def.build(), owner, origin);
                            old.push(id);
                            stable.push(game.object(id).unwrap().stable_id);
                        }
                        let mut dm = Pick {
                            take,
                            owner,
                            origin,
                            old: old.clone(),
                            resources: resources.clone(),
                            menus: vec![],
                            errors: vec![],
                        };
                        game.stack.push(StackEntry::ability(
                            source,
                            actor,
                            vec![Effect::new(
                                ReturnAllToBattlefieldEffect::new(
                                    ObjectFilter::land().in_zone(origin),
                                    false,
                                )
                                .under_owner_control(),
                            )],
                        ));
                        let label = format!(
                            "discard={discard} count={count} available={available} owner={owner:?} actor={actor:?} take={take}"
                        );
                        if let Err(error) =
                            ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm)
                        {
                            discrepancies.push(format!("{label}: resolution failed {error:?}"));
                        }
                        for error in dm.errors {
                            discrepancies.push(format!("{label}: {error}"));
                        }
                        let moved = if take {
                            if discard {
                                count.min(available)
                            } else {
                                available
                            }
                        } else {
                            0
                        };
                        let actual = resource_stable
                            .iter()
                            .filter(|sid| {
                                game.find_object_by_stable_id(**sid)
                                    .is_some_and(|id| game.object(id).unwrap().zone == destination)
                            })
                            .count();
                        if actual != moved
                            || game.player(owner).unwrap().life
                                != 20 + if discard { moved as i32 } else { 0 }
                        {
                            discrepancies.push(format!("{label}: moved{actual}/life{}, required moved{moved} with matching payment benefit",game.player(owner).unwrap().life));
                        }
                        for (index, sid) in stable.iter().enumerate() {
                            if !game.find_object_by_stable_id(*sid).is_some_and(|id| {
                                id != old[index]
                                    && game.object(id).unwrap().zone == Zone::Battlefield
                                    && game.current_controller(id) == Some(owner)
                            }) {
                                discrepancies.push(format!(
                                    "{label}: entrant{index} was consumed or failed to enter"
                                ));
                            }
                        }
                        assert_eq!(game.object(foreign).unwrap().zone, origin);
                        assert_eq!(game.player(other).unwrap().life, 20);
                        game.validate_zone_consistency().unwrap();
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 96);
    assert!(
        discrepancies.is_empty(),
        "CR614.13a/b: an entry replacement cannot choose its own entrant, a simultaneous entrant, or a card already chosen to change zones: {discrepancies:#?}"
    );
}

#[test]
fn cr_614_13a_b_graveyard_entry_exile_choices_exclude_all_entrants_and_spent_cards() {
    check_entry_zone_choice_exclusions(false);
}
#[test]
fn cr_614_13a_hand_entry_discard_costs_exclude_all_simultaneous_entrants() {
    check_entry_zone_choice_exclusions(true);
}

#[test]
fn cr_614_13a_b_multiple_devour_abilities_cannot_sacrifice_the_same_creature_twice() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::SelectObjectsContext;
    use ironsmith::effects::ReturnAllToBattlefieldEffect;
    use ironsmith::triggers::Trigger;
    use ironsmith::{
        Ability, CardId, CardType, CounterType, Effect, ObjectFilter, ObjectId, PowerToughness,
        StackEntry, StaticAbility, TriggerQueue, Zone,
    };
    struct Devour {
        take: bool,
        owner: PlayerId,
        old: Vec<ObjectId>,
        resources: Vec<ObjectId>,
        selected: Vec<ObjectId>,
        errors: Vec<String>,
    }
    impl DecisionMaker for Devour {
        fn decide_objects(
            &mut self,
            game: &GameState,
            ctx: &SelectObjectsContext,
        ) -> Vec<ObjectId> {
            let legal: Vec<_> = ctx
                .candidates
                .iter()
                .filter(|c| c.legal)
                .map(|c| c.id)
                .collect();
            if ctx.player != self.owner
                || legal
                    .iter()
                    .any(|id| !self.resources.contains(id) || self.selected.contains(id))
            {
                self.errors.push(format!("invalid devour menu {legal:?}"));
            }
            if !self
                .old
                .iter()
                .all(|id| game.object(*id).is_some_and(|o| o.zone == Zone::Graveyard))
            {
                self.errors
                    .push("devour choice occurred after an entrant moved".into());
            }
            if self.take {
                self.selected.extend(legal.iter().copied());
                legal
            } else {
                vec![]
            }
        }
    }
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for count in 1usize..=3 {
        for available in 0usize..=3 {
            for reverse in [false, true] {
                for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                        for take in [false, true] {
                            let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                            let source = game.create_object_from_definition(
                                &CardDefinitionBuilder::new(
                                    CardId::new(),
                                    "Devour return instruction",
                                )
                                .card_types(vec![CardType::Artifact])
                                .build(),
                                actor,
                                Zone::Battlefield,
                            );
                            let resource_def = CardDefinitionBuilder::new(
                                CardId::new(),
                                "Devour sacrifice resource",
                            )
                            .card_types(vec![CardType::Creature])
                            .power_toughness(PowerToughness::fixed(2, 3))
                            .with_trigger(Trigger::this_dies(), vec![Effect::gain_life(1)])
                            .build();
                            let mut resources = Vec::new();
                            let mut resource_stable = Vec::new();
                            for _ in 0..available {
                                let id = game.create_object_from_definition(
                                    &resource_def,
                                    owner,
                                    Zone::Battlefield,
                                );
                                resources.push(id);
                                resource_stable.push(game.object(id).unwrap().stable_id);
                            }
                            let other = PlayerId::from_index(1 - owner.index() as u8);
                            let foreign = game.create_object_from_definition(
                                &resource_def,
                                other,
                                Zone::Battlefield,
                            );
                            let mut old = Vec::new();
                            let mut stable = Vec::new();
                            for index in 0..count {
                                let mut def = CardDefinitionBuilder::new(
                                    CardId::new(),
                                    format!("Double-devour entrant {index}"),
                                )
                                .card_types(vec![CardType::Creature, CardType::Land])
                                .power_toughness(PowerToughness::fixed(3, 4))
                                .with_trigger(
                                    Trigger::this_enters_battlefield(),
                                    vec![Effect::gain_life(2)],
                                );
                                for multiplier in if reverse { [5, 3] } else { [3, 5] } {
                                    def=def.with_ability(Ability::static_ability(StaticAbility::from_model(ironsmith::static_abilities::CompiledStaticAbility::as_enters_effect_program(
                        vec![Effect::devour(multiplier)].into(),"this creature",false,false,None))));
                                }
                                let id = game.create_object_from_definition(
                                    &def.build(),
                                    owner,
                                    Zone::Graveyard,
                                );
                                old.push(id);
                                stable.push(game.object(id).unwrap().stable_id);
                            }
                            let mut dm = Devour {
                                take,
                                owner,
                                old: old.clone(),
                                resources: resources.clone(),
                                selected: vec![],
                                errors: vec![],
                            };
                            game.stack.push(StackEntry::ability(
                                source,
                                actor,
                                vec![Effect::new(
                                    ReturnAllToBattlefieldEffect::new(
                                        ObjectFilter::land().in_zone(Zone::Graveyard),
                                        false,
                                    )
                                    .under_owner_control(),
                                )],
                            ));
                            let label = format!(
                                "count={count} available={available} reverse={reverse} owner={owner:?} actor={actor:?} take={take}"
                            );
                            if let Err(error) =
                                ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm)
                            {
                                discrepancies.push(format!("{label}: resolution error {error:?}"));
                            }
                            for error in dm.errors {
                                discrepancies.push(format!("{label}: {error}"));
                            }
                            let mut counters = 0;
                            let mut recipients = 0;
                            for (index, sid) in stable.iter().enumerate() {
                                let id = game.find_object_by_stable_id(*sid).unwrap();
                                if id == old[index]
                                    || game.object(id).unwrap().zone != Zone::Battlefield
                                    || game.current_controller(id) != Some(owner)
                                {
                                    discrepancies.push(format!(
                                        "{label}: entrant{index} disposition incorrect"
                                    ));
                                }
                                let n = game.counter_count(id, CounterType::PlusOnePlusOne);
                                counters += n;
                                recipients += usize::from(n > 0);
                            }
                            let sacrificed = if take { available } else { 0 };
                            if (sacrificed == 0 && counters != 0)
                                || (sacrificed > 0
                                    && ![3 * sacrificed as u32, 5 * sacrificed as u32]
                                        .contains(&counters))
                                || recipients > 1
                                || dm.selected.len() != sacrificed
                            {
                                discrepancies.push(format!("{label}: counters{counters}/recipients{recipients}/selected{}, required one devour payment per creature",dm.selected.len()));
                            }
                            for sid in &resource_stable {
                                assert_eq!(
                                    game.object(game.find_object_by_stable_id(*sid).unwrap())
                                        .unwrap()
                                        .zone,
                                    if take {
                                        Zone::Graveyard
                                    } else {
                                        Zone::Battlefield
                                    }
                                );
                            }
                            assert_eq!(game.object(foreign).unwrap().zone, Zone::Battlefield);
                            let mut queue = TriggerQueue::new();
                            ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                            let n = game.stack.len();
                            if n != count + sacrificed {
                                discrepancies.push(format!(
                                    "{label}: ETB/death triggers{n}, required{}",
                                    count + sacrificed
                                ));
                            }
                            for _ in 0..n {
                                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                            }
                            if game.player(owner).unwrap().life
                                != 20 + 2 * count as i32 + sacrificed as i32
                                || game.player(other).unwrap().life != 20
                            {
                                discrepancies.push(format!(
                                    "{label}: ETB/death trigger life effects incorrect"
                                ));
                            }
                            game.validate_zone_consistency().unwrap();
                            cases += 1;
                        }
                    }
                }
            }
        }
    }
    assert_eq!(cases, 192);
    assert!(
        discrepancies.is_empty(),
        "CR614.13a/b: separate devour replacements cannot sacrifice an entrant or reuse one creature, and their actual sacrifices and entry triggers must be preserved: {discrepancies:#?}"
    );
}

#[test]
fn cr_702_82b_later_devour_instances_preserve_earlier_sacrifices_for_references() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::SelectObjectsContext;
    use ironsmith::effects::MoveToZoneEffect;
    use ironsmith::triggers::Trigger;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, CounterType, Effect, ObjectId, PowerToughness,
        StackEntry, StaticAbility, TriggerQueue, Value, Zone,
    };
    struct FirstMeal {
        resources: Vec<ObjectId>,
        choose: bool,
    }
    impl DecisionMaker for FirstMeal {
        fn decide_objects(&mut self, _: &GameState, ctx: &SelectObjectsContext) -> Vec<ObjectId> {
            if !self.choose {
                return vec![];
            }
            ctx.candidates
                .iter()
                .filter(|c| c.legal && self.resources.contains(&c.id))
                .map(|c| c.id)
                .collect()
        }
    }
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for instances in [1usize, 2, 3] {
        for amount in 0usize..=3 {
            for choose in [false, true] {
                for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        let resource_def =
                            CardDefinitionBuilder::new(CardId::new(), "Remembered devour creature")
                                .card_types(vec![CardType::Creature])
                                .power_toughness(PowerToughness::fixed(1, 2))
                                .build();
                        let mut resources = Vec::new();
                        for _ in 0..amount {
                            resources.push(game.create_object_from_definition(
                                &resource_def,
                                actor,
                                Zone::Battlefield,
                            ));
                        }
                        let source = game.create_object_from_definition(
                            &CardDefinitionBuilder::new(CardId::new(), "Devour memory instruction")
                                .card_types(vec![CardType::Artifact])
                                .build(),
                            actor,
                            Zone::Battlefield,
                        );
                        let mut entrant_def = CardDefinitionBuilder::new(
                            CardId::new(),
                            "Remembering multiple devour instances",
                        )
                        .card_types(vec![CardType::Creature])
                        .power_toughness(PowerToughness::fixed(3, 4))
                        .with_trigger(
                            Trigger::this_enters_battlefield(),
                            vec![Effect::gain_life(Value::SourceDevouredCreatureCount)],
                        );
                        for index in 0..instances {
                            entrant_def=entrant_def.with_ability(Ability::static_ability(StaticAbility::from_model(
                    ironsmith::static_abilities::CompiledStaticAbility::as_enters_effect_program(
                        vec![Effect::devour(3+2*index as u32)].into(),"this creature",false,false,None))));
                        }
                        let old = game.create_object_from_definition(
                            &entrant_def.build(),
                            owner,
                            Zone::Hand,
                        );
                        let stable = game.object(old).unwrap().stable_id;
                        game.stack.push(StackEntry::ability(
                            source,
                            actor,
                            vec![Effect::new(
                                MoveToZoneEffect::new(
                                    ChooseSpec::SpecificObject(old),
                                    Zone::Battlefield,
                                    false,
                                )
                                .under_you_control(),
                            )],
                        ));
                        let mut dm = FirstMeal {
                            resources: resources.clone(),
                            choose,
                        };
                        ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm).unwrap();
                        let current = game.find_object_by_stable_id(stable).unwrap();
                        assert_ne!(current, old);
                        assert_eq!(game.current_controller(current), Some(actor));
                        assert_eq!(game.object(current).unwrap().owner, owner);
                        let expected = if choose { amount as u32 } else { 0 };
                        let recorded = game.devoured_count(current);
                        let remembered = game.devoured_objects(current).len();
                        let counters = game.counter_count(current, CounterType::PlusOnePlusOne);
                        let label = format!(
                            "instances={instances} amount={amount} choose={choose} owner={owner:?} actor={actor:?}"
                        );
                        if recorded != expected || remembered != expected as usize {
                            discrepancies.push(format!("{label}: recorded{recorded}/remembered{remembered}, required{expected} across all devour instances"));
                        }
                        if expected > 0
                            && !(0..instances)
                                .any(|index| counters == expected * (3 + 2 * index as u32))
                            || expected == 0 && counters != 0
                        {
                            discrepancies.push(format!("{label}: counter payment {counters} did not match one devour ability"));
                        }
                        for resource in &resources {
                            assert_eq!(
                                game.object(*resource).map(|o| o.zone),
                                if choose {
                                    None
                                } else {
                                    Some(Zone::Battlefield)
                                }
                            );
                        }
                        let mut queue = TriggerQueue::new();
                        ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                        assert_eq!(game.stack.len(), 1);
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        if game.player(actor).unwrap().life != 20 + expected as i32 {
                            discrepancies.push(format!(
                                "{label}: devoured-count ETB life{}, required{}",
                                game.player(actor).unwrap().life,
                                20 + expected as i32
                            ));
                        }
                        assert_eq!(
                            game.player(PlayerId::from_index(1 - actor.index() as u8))
                                .unwrap()
                                .life,
                            20
                        );
                        game.validate_zone_consistency().unwrap();
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 96);
    assert!(
        discrepancies.is_empty(),
        "CR702.82b: later devour replacements cannot erase earlier sacrifices from the permanents devoured count or memory used by its other abilities: {discrepancies:#?}"
    );
}

fn check_library_entrant_exclusion_from_replaced_life_payments(mill: bool) {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effect::{EffectId, EffectPredicate};
    use ironsmith::effects::{MayEffect, ReturnAllToBattlefieldEffect};
    use ironsmith::{
        Ability, CardId, CardType, Effect, ObjectFilter, ObjectId, StackEntry, StaticAbility, Zone,
    };
    struct Pay {
        accept: bool,
        owner: PlayerId,
        old: Vec<ObjectId>,
        errors: Vec<String>,
    }
    impl DecisionMaker for Pay {
        fn decide_boolean(&mut self, game: &GameState, ctx: &BooleanContext) -> bool {
            if ctx.player != self.owner
                || !self
                    .old
                    .iter()
                    .all(|id| game.object(*id).is_some_and(|o| o.zone == Zone::Library))
            {
                self.errors
                    .push("wrong payer or an entrant moved before later entry choices".into());
            }
            self.accept
        }
    }
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for count in 1usize..=3 {
        for spare in [0usize, 1] {
            for interleaved in [false, true] {
                for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                        for accept in [false, true] {
                            let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                            let replacement = if mill {
                                Effect::mill(2)
                            } else {
                                Effect::exile_top_of_library_player(2, PlayerFilter::You)
                            };
                            let replacement_source=game.create_object_from_definition(&CardDefinitionBuilder::new(CardId::new(),"Entry life-payment replacement")
                .card_types(vec![CardType::Artifact]).with_ability(Ability::static_ability(StaticAbility::from_model(
                    ironsmith::static_abilities::CompiledStaticAbility::event_replacement_with_effects(
                        ironsmith_core::ReplacedEventSpec::LifePayment {player:PlayerFilter::You,require_library_capacity:true},
                        vec![replacement],"If you would pay 2 life, move the top two library cards instead")
                ))).build(),owner,Zone::Battlefield);
                            let source = game.create_object_from_definition(
                                &CardDefinitionBuilder::new(
                                    CardId::new(),
                                    "Library return instruction",
                                )
                                .card_types(vec![CardType::Artifact])
                                .build(),
                                actor,
                                Zone::Battlefield,
                            );
                            let mut old = Vec::new();
                            let mut stable = Vec::new();
                            for index in 0..count {
                                let program = vec![
                                    Effect::with_id(
                                        614131,
                                        Effect::new(
                                            MayEffect::new(vec![Effect::pay_life(2)])
                                                .with_pay_as_cost(true),
                                        ),
                                    ),
                                    Effect::if_then_else(
                                        EffectId(614131),
                                        EffectPredicate::Happened,
                                        vec![Effect::gain_life(1)],
                                        vec![],
                                    ),
                                ];
                                let def=CardDefinitionBuilder::new(CardId::new(),format!("Library entrant {index}"))
                    .card_types(vec![CardType::Land]).with_ability(Ability::static_ability(StaticAbility::from_model(
                        ironsmith::static_abilities::CompiledStaticAbility::as_enters_effect_program(program.into(),"this land",false,false,None)))).build();
                                let id =
                                    game.create_object_from_definition(&def, owner, Zone::Library);
                                old.push(id);
                                stable.push(game.object(id).unwrap().stable_id);
                            }
                            let mut resources = Vec::new();
                            let mut resource_stable = Vec::new();
                            for index in 0..2 * count + spare {
                                let def = CardDefinitionBuilder::new(
                                    CardId::new(),
                                    format!("Library resource {index}"),
                                )
                                .card_types(vec![CardType::Artifact])
                                .build();
                                let id =
                                    game.create_object_from_definition(&def, owner, Zone::Library);
                                resources.push(id);
                                resource_stable.push(game.object(id).unwrap().stable_id);
                            }
                            let mut order = Vec::new();
                            for (index, id) in resources.iter().enumerate() {
                                order.push(*id);
                                if interleaved && index < count {
                                    order.push(old[index]);
                                }
                            }
                            if !interleaved {
                                order.extend(old.iter().copied());
                            }
                            game.player_mut(owner).unwrap().library = order.clone().into();
                            let expected_moved: Vec<_> = if accept {
                                order
                                    .iter()
                                    .rev()
                                    .filter(|id| !old.contains(id))
                                    .take(2 * count)
                                    .copied()
                                    .collect()
                            } else {
                                vec![]
                            };
                            let mut dm = Pay {
                                accept,
                                owner,
                                old: old.clone(),
                                errors: vec![],
                            };
                            game.stack.push(StackEntry::ability(
                                source,
                                actor,
                                vec![Effect::new(
                                    ReturnAllToBattlefieldEffect::new(
                                        ObjectFilter::land().in_zone(Zone::Library),
                                        false,
                                    )
                                    .under_owner_control(),
                                )],
                            ));
                            let label = format!(
                                "mill={mill} count={count} spare={spare} interleaved={interleaved} owner={owner:?} actor={actor:?} accept={accept}"
                            );
                            if let Err(error) =
                                ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm)
                            {
                                discrepancies.push(format!("{label}: resolution error {error:?}"));
                            }
                            for error in dm.errors {
                                discrepancies.push(format!("{label}: {error}"));
                            }
                            for (index, sid) in stable.iter().enumerate() {
                                if !game.find_object_by_stable_id(*sid).is_some_and(|id| {
                                    id != old[index]
                                        && game.object(id).unwrap().zone == Zone::Battlefield
                                        && game.current_controller(id) == Some(owner)
                                }) {
                                    discrepancies.push(format!("{label}: incoming library card{index} was consumed instead of entering"));
                                }
                            }
                            for (index, sid) in resource_stable.iter().enumerate() {
                                let id = game.find_object_by_stable_id(*sid).unwrap();
                                let expected = if expected_moved.contains(&resources[index]) {
                                    if mill { Zone::Graveyard } else { Zone::Exile }
                                } else {
                                    Zone::Library
                                };
                                if game.object(id).unwrap().zone != expected {
                                    discrepancies.push(format!("{label}: resource{index} destination {:?}, required{expected:?}",game.object(id).unwrap().zone));
                                }
                            }
                            let remaining: Vec<_> = order
                                .into_iter()
                                .filter(|id| !old.contains(id) && !expected_moved.contains(id))
                                .collect();
                            if game.player(owner).unwrap().library != remaining
                                || game.player(owner).unwrap().life
                                    != 20 + if accept { count as i32 } else { 0 }
                            {
                                discrepancies.push(format!("{label}: remaining library or replaced-payment life benefit incorrect"));
                            }
                            assert_eq!(
                                game.object(replacement_source).unwrap().zone,
                                Zone::Battlefield
                            );
                            assert_eq!(
                                game.player(PlayerId::from_index(1 - owner.index() as u8))
                                    .unwrap()
                                    .life,
                                20
                            );
                            game.validate_zone_consistency().unwrap();
                            cases += 1;
                        }
                    }
                }
            }
        }
    }
    assert_eq!(cases, 96);
    assert!(
        discrepancies.is_empty(),
        "CR614.13c: mill/exile replacing an as-enters life payment must skip all incoming library cards and move the next eligible cards in order: {discrepancies:#?}"
    );
}
#[test]
fn cr_614_13c_library_entrants_are_excluded_from_life_payment_replacement_exile() {
    check_library_entrant_exclusion_from_replaced_life_payments(false);
}
#[test]
fn cr_614_13c_library_entrants_are_excluded_from_life_payment_replacement_mill() {
    check_library_entrant_exclusion_from_replaced_life_payments(true);
}

#[test]
fn cr_614_13b_replaced_entry_exiles_cannot_choose_the_same_graveyard_card_again() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::SelectObjectsContext;
    use ironsmith::effects::{ChooseObjectsEffect, ExileEffect, ReturnAllToBattlefieldEffect};
    use ironsmith::triggers::Trigger;
    use ironsmith::{
        Ability, CardId, CardType, ChoiceCount, ChooseSpec, Effect, ObjectFilter, ObjectId,
        PowerToughness, StackEntry, StaticAbility, TriggerQueue, Zone,
    };
    struct Pick {
        take: bool,
        owner: PlayerId,
        old: Vec<ObjectId>,
        resources: Vec<ObjectId>,
        chosen: Vec<ObjectId>,
        errors: Vec<String>,
    }
    impl DecisionMaker for Pick {
        fn decide_objects(
            &mut self,
            game: &GameState,
            ctx: &SelectObjectsContext,
        ) -> Vec<ObjectId> {
            let legal: Vec<_> = ctx
                .candidates
                .iter()
                .filter(|c| c.legal)
                .map(|c| c.id)
                .collect();
            if ctx.player != self.owner || legal.iter().any(|id| !self.resources.contains(id)) {
                self.errors
                    .push(format!("invalid entry-exile menu{legal:?}"));
            }
            if legal.iter().any(|id| self.chosen.contains(id)) {
                self.errors.push(format!(
                    "previously chosen zone-change object offered again{legal:?}"
                ));
            }
            if !self
                .old
                .iter()
                .all(|id| game.object(*id).is_some_and(|o| o.zone == Zone::Graveyard))
            {
                self.errors
                    .push("an entrant moved before later entry choices".into());
            }
            if self.take {
                self.chosen.extend(legal.iter().copied());
                legal
            } else {
                vec![]
            }
        }
    }
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for count in 1usize..=3 {
        for available in 0usize..=3 {
            for replace in [false, true] {
                for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                        for take in [false, true] {
                            let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                            let resource_def = CardDefinitionBuilder::new(
                                CardId::new(),
                                "Reusable entry-exile artifact",
                            )
                            .card_types(vec![CardType::Artifact])
                            .build();
                            let mut resources = Vec::new();
                            let mut resource_stable = Vec::new();
                            for _ in 0..available {
                                let id = game.create_object_from_definition(
                                    &resource_def,
                                    owner,
                                    Zone::Graveyard,
                                );
                                resources.push(id);
                                resource_stable.push(game.object(id).unwrap().stable_id);
                            }
                            let other = PlayerId::from_index(1 - owner.index() as u8);
                            let foreign = game.create_object_from_definition(
                                &resource_def,
                                other,
                                Zone::Graveyard,
                            );
                            let filter = ObjectFilter::artifact()
                                .in_zone(Zone::Graveyard)
                                .owned_by(PlayerFilter::You);
                            let mut replacement_def = CardDefinitionBuilder::new(
                                CardId::new(),
                                "Entry-exile replacement owner",
                            )
                            .card_types(vec![CardType::Enchantment]);
                            if replace {
                                replacement_def=replacement_def.with_ability(Ability::static_ability(StaticAbility::from_model(
                ironsmith::static_abilities::CompiledStaticAbility::event_replacement_with_effects(
                    ironsmith_core::ReplacedEventSpec::ZoneChange {object:filter.clone(),from:Some(Zone::Graveyard),to:Some(Zone::Exile)},
                    vec![Effect::gain_life(1)],"If your graveyard artifact would be exiled, gain1 life instead"))));
                            }
                            game.create_object_from_definition(
                                &replacement_def.build(),
                                owner,
                                Zone::Battlefield,
                            );
                            let source = game.create_object_from_definition(
                                &CardDefinitionBuilder::new(
                                    CardId::new(),
                                    "Repeated entry-exile instruction",
                                )
                                .card_types(vec![CardType::Enchantment])
                                .build(),
                                actor,
                                Zone::Battlefield,
                            );
                            let mut old = Vec::new();
                            let mut stable = Vec::new();
                            for index in 0..count {
                                let mut def = CardDefinitionBuilder::new(
                                    CardId::new(),
                                    format!("Repeated-exile entrant{index}"),
                                )
                                .card_types(vec![CardType::Land, CardType::Creature])
                                .power_toughness(PowerToughness::fixed(3, 4))
                                .with_trigger(
                                    Trigger::this_enters_battlefield(),
                                    vec![Effect::gain_life(2)],
                                );
                                for ability_index in 0..2 {
                                    let tag = format!("entry_resource_{index}_{ability_index}");
                                    let program = vec![
                                        Effect::new(
                                            ChooseObjectsEffect::new(
                                                filter.clone(),
                                                ChoiceCount::any_number(),
                                                PlayerFilter::You,
                                                tag.clone(),
                                            )
                                            .replace_tagged_objects(),
                                        ),
                                        Effect::new(ExileEffect::with_spec(ChooseSpec::tagged(
                                            tag,
                                        ))),
                                    ];
                                    def=def.with_ability(Ability::static_ability(StaticAbility::from_model(
                    ironsmith::static_abilities::CompiledStaticAbility::as_enters_effect_program(program.into(),"this creature",false,false,None))));
                                }
                                let id = game.create_object_from_definition(
                                    &def.build(),
                                    owner,
                                    Zone::Graveyard,
                                );
                                old.push(id);
                                stable.push(game.object(id).unwrap().stable_id);
                            }
                            let mut dm = Pick {
                                take,
                                owner,
                                old: old.clone(),
                                resources: resources.clone(),
                                chosen: vec![],
                                errors: vec![],
                            };
                            game.stack.push(StackEntry::ability(
                                source,
                                actor,
                                vec![Effect::new(
                                    ReturnAllToBattlefieldEffect::new(
                                        ObjectFilter::land().in_zone(Zone::Graveyard),
                                        false,
                                    )
                                    .under_owner_control(),
                                )],
                            ));
                            let label = format!(
                                "count={count} available={available} replace={replace} owner={owner:?} actor={actor:?} take={take}"
                            );
                            if let Err(error) =
                                ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm)
                            {
                                discrepancies.push(format!("{label}: resolution error{error:?}"));
                            }
                            for error in dm.errors {
                                discrepancies.push(format!("{label}: {error}"));
                            }
                            let expected_selected = if take { available } else { 0 };
                            let gain = if replace && take { available as i32 } else { 0 };
                            if dm.chosen.len() != expected_selected
                                || game.player(owner).unwrap().life != 20 + gain
                            {
                                discrepancies.push(format!(
                                    "{label}: selections{}/life{}, required{expected_selected}/{}",
                                    dm.chosen.len(),
                                    game.player(owner).unwrap().life,
                                    20 + gain
                                ));
                            }
                            for (index, sid) in resource_stable.iter().enumerate() {
                                let id = game.find_object_by_stable_id(*sid).unwrap();
                                assert_eq!(
                                    game.object(id).unwrap().zone,
                                    if take && !replace {
                                        Zone::Exile
                                    } else {
                                        Zone::Graveyard
                                    }
                                );
                                if replace {
                                    assert_eq!(id, resources[index]);
                                }
                            }
                            for (index, sid) in stable.iter().enumerate() {
                                let id = game.find_object_by_stable_id(*sid).unwrap();
                                assert_ne!(id, old[index]);
                                assert_eq!(game.object(id).unwrap().zone, Zone::Battlefield);
                                assert_eq!(game.current_controller(id), Some(owner));
                            }
                            assert_eq!(game.object(foreign).unwrap().zone, Zone::Graveyard);
                            let mut queue = TriggerQueue::new();
                            ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                            assert_eq!(game.stack.len(), count);
                            for _ in 0..count {
                                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                            }
                            if game.player(owner).unwrap().life != 20 + gain + 2 * count as i32
                                || game.player(other).unwrap().life != 20
                            {
                                discrepancies.push(format!(
                                    "{label}: final replacement/ETB life results incorrect"
                                ));
                            }
                            game.validate_zone_consistency().unwrap();
                            cases += 1;
                        }
                    }
                }
            }
        }
    }
    assert_eq!(cases, 192);
    assert!(
        discrepancies.is_empty(),
        "CR614.13b: a card chosen to change zones for one entry replacement cannot be chosen again for another, even when a replacement leaves it in its original zone: {discrepancies:#?}"
    );
}

fn check_devour_quality(artifact: bool) {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::SelectObjectsContext;
    use ironsmith::effects::{DevourEffect, ReturnAllToBattlefieldEffect};
    use ironsmith::triggers::Trigger;
    use ironsmith::{
        Ability, CardId, CardType, CounterType, Effect, ObjectFilter, ObjectId, PowerToughness,
        StackEntry, StaticAbility, Subtype, TriggerQueue, Zone,
    };
    struct Feed {
        take: bool,
        owner: PlayerId,
        old: Vec<ObjectId>,
        resources: Vec<ObjectId>,
        selected: Vec<ObjectId>,
        errors: Vec<String>,
    }
    impl DecisionMaker for Feed {
        fn decide_objects(
            &mut self,
            game: &GameState,
            ctx: &SelectObjectsContext,
        ) -> Vec<ObjectId> {
            let legal: Vec<_> = ctx
                .candidates
                .iter()
                .filter(|c| c.legal)
                .map(|c| c.id)
                .collect();
            if ctx.player != self.owner
                || legal
                    .iter()
                    .any(|id| !self.resources.contains(id) || self.selected.contains(id))
            {
                self.errors
                    .push(format!("invalid devour-quality menu{legal:?}"));
            }
            if !self
                .old
                .iter()
                .all(|id| game.object(*id).is_some_and(|o| o.zone == Zone::Graveyard))
            {
                self.errors
                    .push("a quality entrant moved before later choices".into());
            }
            if self.take {
                self.selected.extend(legal.iter().copied());
                legal
            } else {
                vec![]
            }
        }
    }
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for count in [1usize, 3] {
        for available in 0usize..=2 {
            for multiplier in [1u32, 3] {
                for forbidden in [false, true] {
                    for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                        for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                            for take in [false, true] {
                                let mut game =
                                    GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                                let source = game.create_object_from_definition(
                                    &CardDefinitionBuilder::new(
                                        CardId::new(),
                                        "Devour-quality return instruction",
                                    )
                                    .card_types(vec![CardType::Enchantment])
                                    .build(),
                                    actor,
                                    Zone::Battlefield,
                                );
                                if forbidden {
                                    game.create_object_from_definition(&CardDefinitionBuilder::new(CardId::new(),"Sacrifice prohibition")
                .card_types(vec![CardType::Enchantment]).with_ability(Ability::static_ability(StaticAbility::permanents_you_control_cant_be_sacrificed())).build(),owner,Zone::Battlefield);
                                }
                                let mut resource_def = CardDefinitionBuilder::new(
                                    CardId::new(),
                                    "Matching devour-quality resource",
                                )
                                .card_types(vec![if artifact {
                                    CardType::Artifact
                                } else {
                                    CardType::Creature
                                }])
                                .power_toughness(PowerToughness::fixed(2, 3))
                                .with_trigger(
                                    Trigger::this_leaves_battlefield(),
                                    vec![Effect::gain_life(1)],
                                );
                                if !artifact {
                                    resource_def = resource_def.subtypes(vec![Subtype::Goblin]);
                                }
                                let resource_def = resource_def.build();
                                let mut resources = Vec::new();
                                let mut resource_stable = Vec::new();
                                for _ in 0..available {
                                    let id = game.create_object_from_definition(
                                        &resource_def,
                                        owner,
                                        Zone::Battlefield,
                                    );
                                    resources.push(id);
                                    resource_stable.push(game.object(id).unwrap().stable_id);
                                }
                                let other = PlayerId::from_index(1 - owner.index() as u8);
                                let foreign = game.create_object_from_definition(
                                    &resource_def,
                                    other,
                                    Zone::Battlefield,
                                );
                                let phased = game.create_object_from_definition(
                                    &resource_def,
                                    owner,
                                    Zone::Battlefield,
                                );
                                game.phase_out(phased);
                                let wrong = game.create_object_from_definition(
                                    &CardDefinitionBuilder::new(
                                        CardId::new(),
                                        "Wrong-quality friendly permanent",
                                    )
                                    .card_types(vec![if artifact {
                                        CardType::Creature
                                    } else {
                                        CardType::Artifact
                                    }])
                                    .power_toughness(PowerToughness::fixed(2, 3))
                                    .build(),
                                    owner,
                                    Zone::Battlefield,
                                );
                                let quality = if artifact {
                                    ObjectFilter::artifact()
                                } else {
                                    ObjectFilter::creature().with_subtype(Subtype::Goblin)
                                };
                                let mut old = Vec::new();
                                let mut stable = Vec::new();
                                for index in 0..count {
                                    let mut def = CardDefinitionBuilder::new(
                                        CardId::new(),
                                        format!("Devour-quality entrant{index}"),
                                    )
                                    .card_types(vec![
                                        CardType::Creature,
                                        CardType::Artifact,
                                        CardType::Land,
                                    ])
                                    .power_toughness(PowerToughness::fixed(3, 4))
                                    .with_trigger(
                                        Trigger::this_enters_battlefield(),
                                        vec![Effect::gain_life(2)],
                                    );
                                    if !artifact {
                                        def = def.subtypes(vec![Subtype::Goblin]);
                                    }
                                    let def=def.with_ability(Ability::static_ability(StaticAbility::from_model(ironsmith::static_abilities::CompiledStaticAbility::as_enters_effect_program(
                    vec![Effect::new(DevourEffect::with_quality(multiplier,quality.clone()))].into(),"this creature",false,false,None)))).build();
                                    let id = game.create_object_from_definition(
                                        &def,
                                        owner,
                                        Zone::Graveyard,
                                    );
                                    old.push(id);
                                    stable.push(game.object(id).unwrap().stable_id);
                                }
                                let mut dm = Feed {
                                    take,
                                    owner,
                                    old: old.clone(),
                                    resources: resources.clone(),
                                    selected: vec![],
                                    errors: vec![],
                                };
                                game.stack.push(StackEntry::ability(
                                    source,
                                    actor,
                                    vec![Effect::new(
                                        ReturnAllToBattlefieldEffect::new(
                                            ObjectFilter::land().in_zone(Zone::Graveyard),
                                            false,
                                        )
                                        .under_owner_control(),
                                    )],
                                ));
                                let label = format!(
                                    "artifact={artifact} count={count} available={available} multiplier={multiplier} forbidden={forbidden} owner={owner:?} actor={actor:?} take={take}"
                                );
                                if let Err(error) = ironsmith::game_loop::resolve_stack_entry_with(
                                    &mut game, &mut dm,
                                ) {
                                    discrepancies
                                        .push(format!("{label}: resolution error{error:?}"));
                                }
                                for error in dm.errors {
                                    discrepancies.push(format!("{label}: {error}"));
                                }
                                let paid = if take && !forbidden { available } else { 0 };
                                let mut counters = 0;
                                let mut remembered = 0;
                                let mut recipients = 0;
                                for (index, sid) in stable.iter().enumerate() {
                                    let id = game.find_object_by_stable_id(*sid).unwrap();
                                    assert_ne!(id, old[index]);
                                    assert_eq!(game.object(id).unwrap().zone, Zone::Battlefield);
                                    assert_eq!(game.current_controller(id), Some(owner));
                                    let n = game.counter_count(id, CounterType::PlusOnePlusOne);
                                    counters += n;
                                    recipients += usize::from(n > 0);
                                    remembered += game.devoured_count(id);
                                    if game.devoured_objects(id).len()
                                        != game.devoured_count(id) as usize
                                    {
                                        discrepancies.push(format!(
                                            "{label}: remembered objects/count disagree"
                                        ));
                                    }
                                }
                                if counters != multiplier * paid as u32
                                    || remembered != paid as u32
                                    || recipients > 1
                                    || dm.selected.len() != paid
                                {
                                    discrepancies.push(format!("{label}: counters{counters}/remembered{remembered}/recipients{recipients}/selected{}, required a single permitted payment of{paid}",dm.selected.len()));
                                }
                                for sid in resource_stable {
                                    assert_eq!(
                                        game.object(game.find_object_by_stable_id(sid).unwrap())
                                            .unwrap()
                                            .zone,
                                        if paid > 0 {
                                            Zone::Graveyard
                                        } else {
                                            Zone::Battlefield
                                        }
                                    );
                                }
                                for id in [foreign, phased, wrong] {
                                    assert_eq!(game.object(id).unwrap().zone, Zone::Battlefield);
                                }
                                assert!(game.is_phased_out(phased));
                                let mut queue = TriggerQueue::new();
                                ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                                let n = game.stack.len();
                                if n != count + paid {
                                    discrepancies.push(format!(
                                        "{label}: entry/LTB triggers{n}, required{}",
                                        count + paid
                                    ));
                                }
                                for _ in 0..n {
                                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                }
                                if game.player(owner).unwrap().life
                                    != 20 + 2 * count as i32 + paid as i32
                                    || game.player(other).unwrap().life != 20
                                {
                                    discrepancies.push(format!(
                                        "{label}: resolved entry/LTB life incorrect"
                                    ));
                                }
                                game.validate_zone_consistency().unwrap();
                                cases += 1;
                            }
                        }
                    }
                }
            }
        }
    }
    assert_eq!(cases, 192);
    assert!(
        discrepancies.is_empty(),
        "CR702.82c/614.13a/b: devour quality accepts only eligible existing friendly permanents, cannot consume entrants or reuse a resource, and gives counters/history for actual sacrifices: {discrepancies:#?}"
    );
}
#[test]
fn cr_702_82c_devour_artifact_checks_quality_control_phasing_and_sacrifice_legality() {
    check_devour_quality(true);
}
#[test]
fn cr_702_82c_devour_goblin_checks_quality_control_phasing_and_sacrifice_legality() {
    check_devour_quality(false);
}

#[test]
fn cr_614_14_607_2b_printed_as_enters_exile_pairs_survive_entry_and_feed_their_reader() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::{ExileEffect, MoveToZoneEffect};
    use ironsmith::resolution::ResolutionProgram;
    use ironsmith::triggers::Trigger;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, Effect, ObjectFilter, PowerToughness, StackEntry,
        StaticAbility, TriggerQueue, Value, Zone,
    };
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for origin in [Zone::Hand, Zone::Graveyard, Zone::Exile] {
        for amount in 0usize..=3 {
            for marked in [false, true] {
                for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        let instruction = game.create_object_from_definition(
                            &CardDefinitionBuilder::new(CardId::new(), "Linked entry instruction")
                                .card_types(vec![CardType::Enchantment])
                                .build(),
                            actor,
                            Zone::Battlefield,
                        );
                        let resource_def = CardDefinitionBuilder::new(
                            CardId::new(),
                            "Linked entry artifact resource",
                        )
                        .card_types(vec![CardType::Artifact])
                        .build();
                        let mut resources = Vec::new();
                        for _ in 0..amount {
                            let id = game.create_object_from_definition(
                                &resource_def,
                                actor,
                                Zone::Graveyard,
                            );
                            resources.push(game.object(id).unwrap().stable_id);
                        }
                        let other = PlayerId::from_index(1 - actor.index() as u8);
                        let foreign = game.create_object_from_definition(
                            &resource_def,
                            other,
                            Zone::Graveyard,
                        );
                        let unrelated =
                            game.create_object_from_definition(&resource_def, actor, Zone::Exile);
                        // These two printed abilities share one immutable definition/pair marker.
                        // Runtime acquisition must be captured by the actual entry/trigger owners.
                        let pair = ironsmith_core::LinkedExilePair {
                            definition: ironsmith_core::LinkedExileDefinition([177; 32]),
                            pair: 0,
                        };
                        let mut producer =
                            ResolutionProgram::from_effects(vec![Effect::new(ExileEffect::all(
                                ObjectFilter::artifact()
                                    .in_zone(Zone::Graveyard)
                                    .owned_by(PlayerFilter::You),
                            ))]);
                        let mut reader =
                            ResolutionProgram::from_effects(vec![Effect::gain_life(Value::Count(
                                ObjectFilter::tagged(ironsmith_core::tag::SOURCE_EXILED_TAG)
                                    .in_zone(Zone::Exile),
                            ))]);
                        if marked {
                            producer = producer.with_linked_exile_pair(pair);
                            reader = reader.with_linked_exile_pair(pair);
                        }
                        let def=CardDefinitionBuilder::new(CardId::new(),"Printed linked entry producer and reader")
                .card_types(vec![CardType::Creature]).power_toughness(PowerToughness::fixed(3,4))
                .with_ability(Ability::static_ability(StaticAbility::from_model(ironsmith::static_abilities::CompiledStaticAbility::as_enters_effect_program(
                    producer,"this creature",false,false,None))))
                .with_ability(Ability::triggered(Trigger::this_enters_battlefield(),reader)).build();
                        let old = game.create_object_from_definition(&def, owner, origin);
                        let stable = game.object(old).unwrap().stable_id;
                        game.stack.push(StackEntry::ability(
                            instruction,
                            actor,
                            vec![Effect::new(
                                MoveToZoneEffect::new(
                                    ChooseSpec::SpecificObject(old),
                                    Zone::Battlefield,
                                    false,
                                )
                                .under_you_control(),
                            )],
                        ));
                        let label = format!(
                            "origin={origin:?} amount={amount} marked={marked} owner={owner:?} actor={actor:?}"
                        );
                        if let Err(error) = ironsmith::game_loop::resolve_stack_entry(&mut game) {
                            discrepancies.push(format!(
                                "{label}: paired entry refused to resolve: {error:?}"
                            ));
                            cases += 1;
                            continue;
                        }
                        let current = game.find_object_by_stable_id(stable).unwrap();
                        if current == old
                            || game.object(current).unwrap().zone != Zone::Battlefield
                            || game.current_controller(current) != Some(actor)
                            || game.object(current).unwrap().owner != owner
                        {
                            discrepancies.push(format!("{label}: linked producer/reader creature failed to enter with proper identity/ownership/control"));
                        }
                        for sid in resources {
                            assert_eq!(
                                game.object(game.find_object_by_stable_id(sid).unwrap())
                                    .unwrap()
                                    .zone,
                                Zone::Exile
                            );
                        }
                        assert_eq!(game.object(foreign).unwrap().zone, Zone::Graveyard);
                        assert_eq!(game.object(unrelated).unwrap().zone, Zone::Exile);
                        let mut queue = TriggerQueue::new();
                        ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                        let n = game.stack.len();
                        if n != 1 {
                            discrepancies
                                .push(format!("{label}: linked ETB reader count{n}, required1"));
                        }
                        for _ in 0..n {
                            if let Err(error) = ironsmith::game_loop::resolve_stack_entry(&mut game)
                            {
                                discrepancies
                                    .push(format!("{label}: linked reader failed{error:?}"));
                            }
                        }
                        if game.player(actor).unwrap().life != 20 + amount as i32
                            || game.player(other).unwrap().life != 20
                        {
                            discrepancies.push(format!(
                                "{label}: linked reader life{}, required{}",
                                game.player(actor).unwrap().life,
                                20 + amount as i32
                            ));
                        }
                        game.validate_zone_consistency().unwrap();
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 96);
    assert!(
        discrepancies.is_empty(),
        "CR614.14/607.2b: the native as-enters owner must admit a printed linked exile producer and preserve its exact pair for the entering permanent's reader: {discrepancies:#?}"
    );
}

#[test]
fn cr_607_1c_self_linked_entry_triggers_exclude_exile_from_an_unrelated_ability() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::{ExileEffect, MoveToZoneEffect};
    use ironsmith::resolution::ResolutionProgram;
    use ironsmith::triggers::Trigger;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, Effect, ObjectFilter, PowerToughness, StackEntry,
        TriggerQueue, Value, Zone,
    };
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for amount in 0usize..=3 {
        for noise in [false, true] {
            for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                    let instruction = game.create_object_from_definition(
                        &CardDefinitionBuilder::new(CardId::new(), "Self-linked entry instruction")
                            .card_types(vec![CardType::Enchantment])
                            .build(),
                        actor,
                        Zone::Battlefield,
                    );
                    let resource_def =
                        CardDefinitionBuilder::new(CardId::new(), "Self-linked artifact resource")
                            .card_types(vec![CardType::Artifact])
                            .build();
                    let mut resources = Vec::new();
                    for _ in 0..amount {
                        let id = game.create_object_from_definition(
                            &resource_def,
                            actor,
                            Zone::Graveyard,
                        );
                        resources.push(game.object(id).unwrap().stable_id);
                    }
                    let other = PlayerId::from_index(1 - actor.index() as u8);
                    let foreign =
                        game.create_object_from_definition(&resource_def, other, Zone::Graveyard);
                    let unrelated = game.create_object_from_definition(
                        &CardDefinitionBuilder::new(CardId::new(), "Unrelated exile resource")
                            .card_types(vec![CardType::Enchantment])
                            .build(),
                        actor,
                        Zone::Graveyard,
                    );
                    let unrelated_stable = game.object(unrelated).unwrap().stable_id;
                    let pair = ironsmith_core::LinkedExilePair {
                        definition: ironsmith_core::LinkedExileDefinition([178; 32]),
                        pair: 0,
                    };
                    let program = ResolutionProgram::from_effects(vec![
                        Effect::new(ExileEffect::all(
                            ObjectFilter::artifact()
                                .in_zone(Zone::Graveyard)
                                .owned_by(PlayerFilter::You),
                        )),
                        Effect::gain_life(Value::Count(
                            ObjectFilter::tagged(ironsmith_core::tag::SOURCE_EXILED_TAG)
                                .in_zone(Zone::Exile),
                        )),
                    ])
                    .with_linked_exile_pair(pair);
                    let unrelated_program = vec![Effect::new(ExileEffect::all(
                        ObjectFilter::enchantment()
                            .in_zone(Zone::Graveyard)
                            .owned_by(PlayerFilter::You),
                    ))];
                    let def = CardDefinitionBuilder::new(
                        CardId::new(),
                        "Self-linked ETB with unrelated exile ability",
                    )
                    .card_types(vec![CardType::Creature])
                    .power_toughness(PowerToughness::fixed(3, 4))
                    .with_ability(Ability::triggered(
                        Trigger::this_enters_battlefield(),
                        program,
                    ))
                    .with_ability(Ability::activated(
                        ironsmith::cost::TotalCost::free(),
                        unrelated_program.clone(),
                    ))
                    .build();
                    let old = game.create_object_from_definition(&def, owner, Zone::Hand);
                    let stable = game.object(old).unwrap().stable_id;
                    game.stack.push(StackEntry::ability(
                        instruction,
                        actor,
                        vec![Effect::new(
                            MoveToZoneEffect::new(
                                ChooseSpec::SpecificObject(old),
                                Zone::Battlefield,
                                false,
                            )
                            .under_you_control(),
                        )],
                    ));
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    let current = game.find_object_by_stable_id(stable).unwrap();
                    assert_ne!(current, old);
                    assert_eq!(game.current_controller(current), Some(actor));
                    assert_eq!(game.object(current).unwrap().owner, owner);
                    let mut queue = TriggerQueue::new();
                    ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                    assert_eq!(game.stack.len(), 1);
                    let acquisition = game
                        .stack
                        .last()
                        .unwrap()
                        .linked_exile_owner
                        .clone()
                        .expect("real ETB admission must capture its printed pair");
                    assert_eq!(acquisition.host, current);
                    assert_eq!(acquisition.pair, pair);
                    if noise {
                        // Resolve the other printed free ability in response to the actual
                        // queued ETB. Do not inject any pair membership or runtime owner.
                        let mut activation = StackEntry::ability(current, actor, unrelated_program);
                        activation.ability_index = Some(1);
                        game.stack.push(activation);
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        assert_eq!(game.stack.len(), 1);
                    }
                    let label =
                        format!("amount={amount} noise={noise} owner={owner:?} actor={actor:?}");
                    if let Err(error) = ironsmith::game_loop::resolve_stack_entry(&mut game) {
                        discrepancies.push(format!("{label}: self-linked ETB failed{error:?}"));
                    }
                    let members = game.linked_exile_pair_members(&acquisition).unwrap();
                    if members.len() != amount
                        || game.player(actor).unwrap().life != 20 + amount as i32
                    {
                        discrepancies.push(format!(
                            "{label}: exact members{}/life{}, required{amount}/{}",
                            members.len(),
                            game.player(actor).unwrap().life,
                            20 + amount as i32
                        ));
                    }
                    if game.get_exiled_with_source_links(current).len()
                        != amount + usize::from(noise)
                    {
                        discrepancies.push(format!("{label}: source-wide exile control incorrect"));
                    }
                    for sid in resources {
                        assert_eq!(
                            game.object(game.find_object_by_stable_id(sid).unwrap())
                                .unwrap()
                                .zone,
                            Zone::Exile
                        );
                    }
                    assert_eq!(
                        game.object(game.find_object_by_stable_id(unrelated_stable).unwrap())
                            .unwrap()
                            .zone,
                        if noise { Zone::Exile } else { Zone::Graveyard }
                    );
                    assert_eq!(game.object(foreign).unwrap().zone, Zone::Graveyard);
                    assert_eq!(game.player(other).unwrap().life, 20);
                    game.validate_zone_consistency().unwrap();
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 32);
    assert!(
        discrepancies.is_empty(),
        "CR607.1c: a printed ability linked to itself refers only to its own exiled cards, excluding cards exiled by the same permanent's unrelated ability: {discrepancies:#?}"
    );
}

#[test]
fn cr_607_5_gained_producer_reader_pairs_link_only_within_the_same_effect() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::continuous::{EffectTarget, Modification};
    use ironsmith::decisions::context::OrderContext;
    use ironsmith::effects::{ApplyContinuousEffect, ExileEffect, TapEffect};
    use ironsmith::resolution::ResolutionProgram;
    use ironsmith::triggers::Trigger;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, Effect, ObjectFilter, ObjectId, PowerToughness,
        StackEntry, TriggerQueue, Until, Value, Zone,
    };
    struct ProducerFirst {
        holder: PlayerId,
        orders: usize,
    }
    impl DecisionMaker for ProducerFirst {
        fn decide_order(&mut self, _: &GameState, ctx: &OrderContext) -> Vec<ObjectId> {
            assert_eq!(ctx.player, self.holder);
            self.orders += 1;
            let mut rows = ctx.items.clone();
            assert_eq!(
                rows.iter()
                    .filter(|(_, label)| label.to_ascii_lowercase().contains("exile"))
                    .count(),
                1,
                "the actual trigger menu must identify the exile producer: {:?}",
                ctx.items
            );
            rows.sort_by_key(|(_, label)| !label.to_ascii_lowercase().contains("exile"));
            rows.into_iter().map(|(id, _)| id).collect()
        }
    }
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for mode in 0..4 {
        for amount in 0usize..=3 {
            for noise in [false, true] {
                for holder in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        let source_def = CardDefinitionBuilder::new(
                            CardId::new(),
                            "Linked ability grant source",
                        )
                        .card_types(vec![CardType::Enchantment])
                        .build();
                        let source = game.create_object_from_definition(
                            &source_def,
                            actor,
                            Zone::Battlefield,
                        );
                        let second_source = game.create_object_from_definition(
                            &source_def,
                            actor,
                            Zone::Battlefield,
                        );
                        let unrelated_program = vec![Effect::new(ExileEffect::all(
                            ObjectFilter::enchantment()
                                .in_zone(Zone::Graveyard)
                                .owned_by(PlayerFilter::You),
                        ))];
                        let subject = game.create_object_from_definition(
                            &CardDefinitionBuilder::new(
                                CardId::new(),
                                "Recipient of gained linked pair",
                            )
                            .card_types(vec![CardType::Creature])
                            .power_toughness(PowerToughness::fixed(3, 4))
                            .with_ability(Ability::activated(
                                ironsmith::cost::TotalCost::free(),
                                unrelated_program.clone(),
                            ))
                            .build(),
                            holder,
                            Zone::Battlefield,
                        );
                        let resource_def = CardDefinitionBuilder::new(
                            CardId::new(),
                            "Gained pair artifact resource",
                        )
                        .card_types(vec![CardType::Artifact])
                        .build();
                        let mut resources = Vec::new();
                        for _ in 0..amount {
                            let id = game.create_object_from_definition(
                                &resource_def,
                                holder,
                                Zone::Graveyard,
                            );
                            resources.push(game.object(id).unwrap().stable_id);
                        }
                        let other = PlayerId::from_index(1 - holder.index() as u8);
                        let foreign = game.create_object_from_definition(
                            &resource_def,
                            other,
                            Zone::Graveyard,
                        );
                        let unrelated = game.create_object_from_definition(
                            &source_def,
                            holder,
                            Zone::Graveyard,
                        );
                        let unrelated_stable = game.object(unrelated).unwrap().stable_id;
                        let pair = ironsmith_core::LinkedExilePair {
                            definition: ironsmith_core::LinkedExileDefinition([179; 32]),
                            pair: 0,
                        };
                        let producer = Ability::triggered(
                            Trigger::becomes_tapped(),
                            ResolutionProgram::from_effects(vec![Effect::new(ExileEffect::all(
                                ObjectFilter::artifact()
                                    .in_zone(Zone::Graveyard)
                                    .owned_by(PlayerFilter::You),
                            ))])
                            .with_linked_exile_pair(pair),
                        );
                        let reader = Ability::triggered(
                            Trigger::becomes_tapped(),
                            ResolutionProgram::from_effects(vec![Effect::gain_life(Value::Count(
                                ObjectFilter::tagged(ironsmith_core::tag::SOURCE_EXILED_TAG)
                                    .in_zone(Zone::Exile),
                            ))])
                            .with_linked_exile_pair(pair),
                        );
                        let first = ApplyContinuousEffect::new(
                            EffectTarget::Specific(subject),
                            Modification::AddAbilityGeneric(producer.clone()),
                            Until::EndOfTurn,
                        );
                        if mode == 0 {
                            game.stack.push(StackEntry::ability(
                                source,
                                actor,
                                vec![Effect::new(first.with_additional_modification(
                                    Modification::AddAbilityGeneric(reader),
                                ))],
                            ));
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        } else if mode == 3 {
                            let grouped = ApplyContinuousEffect::new(
                                EffectTarget::Specific(subject),
                                Modification::SetAbilities(vec![
                                    Ability::activated(
                                        ironsmith::cost::TotalCost::free(),
                                        unrelated_program.clone(),
                                    ),
                                    producer,
                                    reader,
                                ]),
                                Until::EndOfTurn,
                            );
                            game.stack.push(StackEntry::ability(
                                source,
                                actor,
                                vec![Effect::new(grouped)],
                            ));
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        } else {
                            game.stack.push(StackEntry::ability(
                                source,
                                actor,
                                vec![Effect::new(first)],
                            ));
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                            let second = ApplyContinuousEffect::new(
                                EffectTarget::Specific(subject),
                                Modification::AddAbilityGeneric(reader),
                                Until::EndOfTurn,
                            );
                            game.stack.push(StackEntry::ability(
                                if mode == 1 { source } else { second_source },
                                actor,
                                vec![Effect::new(second)],
                            ));
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        }
                        // Inspect the groups produced by the actual grant instruction.
                        // No group or acquisition metadata is supplied by this fixture.
                        let grants = game.effect_store.continuous_effects.effects();
                        assert_eq!(grants.len(), if mode == 3 { 1 } else { 2 });
                        if mode == 0 {
                            assert!(grants[0].group.is_some());
                            assert_eq!(grants[0].group, grants[1].group);
                        } else {
                            assert!(grants.iter().all(|grant| grant.group.is_none()));
                        }
                        if noise {
                            let mut activation =
                                StackEntry::ability(subject, holder, unrelated_program);
                            activation.ability_index = Some(0);
                            game.stack.push(activation);
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        }
                        game.stack.push(StackEntry::ability(
                            source,
                            actor,
                            vec![Effect::new(TapEffect::with_spec(
                                ChooseSpec::SpecificObject(subject),
                            ))],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        assert!(game.is_tapped(subject));
                        let mut queue = TriggerQueue::new();
                        let mut dm = ProducerFirst { holder, orders: 0 };
                        ironsmith::game_loop::put_triggers_on_stack_with_dm(
                            &mut game, &mut queue, &mut dm,
                        )
                        .unwrap();
                        assert_eq!(game.stack.len(), 2);
                        assert_eq!(dm.orders, 1);
                        let label = format!(
                            "mode={mode} amount={amount} noise={noise} holder={holder:?} actor={actor:?}"
                        );
                        let mut acquired = Vec::new();
                        for index in 0..2 {
                            let top = game.stack.last().unwrap();
                            let is_producer = top
                                .ability_effects
                                .as_ref()
                                .unwrap()
                                .all_effects()
                                .iter()
                                .any(|effect| effect.downcast_ref::<ExileEffect>().is_some());
                            assert_eq!(
                                is_producer,
                                index == 0,
                                "actual selected trigger order must resolve producer before reader"
                            );
                            let acquisition = top
                                .linked_exile_owner
                                .clone()
                                .expect("real granted trigger admission must capture its pair");
                            assert_eq!(acquisition.host, subject);
                            assert_eq!(acquisition.pair, pair);
                            acquired.push(acquisition);
                            if let Err(error) = ironsmith::game_loop::resolve_stack_entry(&mut game)
                            {
                                discrepancies.push(format!(
                                    "{label}: granted trigger{index} failed{error:?}"
                                ));
                            }
                        }
                        let same = acquired[0] == acquired[1];
                        if same != (mode == 0 || mode == 3) {
                            discrepancies.push(format!(
                                "{label}: acquisitions same={same}, required{}",
                                mode == 0 || mode == 3
                            ));
                        }
                        let expected = if mode == 0 || mode == 3 { amount } else { 0 };
                        let producer_members =
                            game.linked_exile_pair_members(&acquired[0]).unwrap().len();
                        let reader_members =
                            game.linked_exile_pair_members(&acquired[1]).unwrap().len();
                        if producer_members != amount
                            || reader_members != expected
                            || game.player(holder).unwrap().life != 20 + expected as i32
                        {
                            discrepancies.push(format!("{label}: producer/reader members{producer_members}/{reader_members}, life{}; required{amount}/{expected}/{}",game.player(holder).unwrap().life,20+expected as i32));
                        }
                        assert_eq!(
                            game.get_exiled_with_source_links(subject).len(),
                            amount + usize::from(noise)
                        );
                        for sid in resources {
                            assert_eq!(
                                game.object(game.find_object_by_stable_id(sid).unwrap())
                                    .unwrap()
                                    .zone,
                                Zone::Exile
                            );
                        }
                        assert_eq!(game.object(foreign).unwrap().zone, Zone::Graveyard);
                        assert_eq!(
                            game.object(game.find_object_by_stable_id(unrelated_stable).unwrap())
                                .unwrap()
                                .zone,
                            if noise { Zone::Exile } else { Zone::Graveyard }
                        );
                        assert_eq!(game.player(other).unwrap().life, 20);
                        game.validate_zone_consistency().unwrap();
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 128);
    assert!(
        discrepancies.is_empty(),
        "CR607.5: producer and reader gained together are linked, but identical pair definitions granted by separate effects remain different acquisitions and cannot read each other's cards: {discrepancies:#?}"
    );
}

#[test]
fn cr_607_5_separate_gained_self_linked_abilities_keep_distinct_exile_collections() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::continuous::{EffectTarget, Modification};
    use ironsmith::effects::{ApplyContinuousEffect, ExileEffect, TapEffect};
    use ironsmith::resolution::ResolutionProgram;
    use ironsmith::triggers::Trigger;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, Effect, ObjectFilter, PowerToughness, StackEntry,
        TriggerQueue, Until, Value, Zone,
    };
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for copies in 1usize..=3 {
        for amount in 0usize..=3 {
            for noise in [false, true] {
                for holder in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        let source_def =
                            CardDefinitionBuilder::new(CardId::new(), "Independent grant source")
                                .card_types(vec![CardType::Enchantment])
                                .build();
                        let source = game.create_object_from_definition(
                            &source_def,
                            actor,
                            Zone::Battlefield,
                        );
                        let unrelated_program = vec![Effect::new(ExileEffect::all(
                            ObjectFilter::enchantment()
                                .in_zone(Zone::Graveyard)
                                .owned_by(PlayerFilter::You),
                        ))];
                        let subject = game.create_object_from_definition(
                            &CardDefinitionBuilder::new(
                                CardId::new(),
                                "Recipient of distinct self-linked grants",
                            )
                            .card_types(vec![CardType::Creature])
                            .power_toughness(PowerToughness::fixed(3, 4))
                            .with_ability(Ability::activated(
                                ironsmith::cost::TotalCost::free(),
                                unrelated_program.clone(),
                            ))
                            .build(),
                            holder,
                            Zone::Battlefield,
                        );
                        let resource_def = CardDefinitionBuilder::new(
                            CardId::new(),
                            "Distinct grant artifact resource",
                        )
                        .card_types(vec![CardType::Artifact])
                        .build();
                        let mut resources = Vec::new();
                        for _ in 0..amount {
                            let id = game.create_object_from_definition(
                                &resource_def,
                                holder,
                                Zone::Graveyard,
                            );
                            resources.push(game.object(id).unwrap().stable_id);
                        }
                        let other = PlayerId::from_index(1 - holder.index() as u8);
                        let foreign = game.create_object_from_definition(
                            &resource_def,
                            other,
                            Zone::Graveyard,
                        );
                        let unrelated = game.create_object_from_definition(
                            &source_def,
                            holder,
                            Zone::Graveyard,
                        );
                        let unrelated_stable = game.object(unrelated).unwrap().stable_id;
                        let pair = ironsmith_core::LinkedExilePair {
                            definition: ironsmith_core::LinkedExileDefinition([180; 32]),
                            pair: 0,
                        };
                        let program = ResolutionProgram::from_effects(vec![
                            Effect::new(ExileEffect::all(
                                ObjectFilter::artifact()
                                    .in_zone(Zone::Graveyard)
                                    .owned_by(PlayerFilter::You),
                            )),
                            Effect::gain_life(Value::Count(
                                ObjectFilter::tagged(ironsmith_core::tag::SOURCE_EXILED_TAG)
                                    .in_zone(Zone::Exile),
                            )),
                        ])
                        .with_linked_exile_pair(pair);
                        for _ in 0..copies {
                            let grant = ApplyContinuousEffect::new(
                                EffectTarget::Specific(subject),
                                Modification::AddAbilityGeneric(Ability::triggered(
                                    Trigger::becomes_tapped(),
                                    program.clone(),
                                )),
                                Until::EndOfTurn,
                            );
                            game.stack.push(StackEntry::ability(
                                source,
                                actor,
                                vec![Effect::new(grant)],
                            ));
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        }
                        if noise {
                            let mut activation =
                                StackEntry::ability(subject, holder, unrelated_program);
                            activation.ability_index = Some(0);
                            game.stack.push(activation);
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        }
                        game.stack.push(StackEntry::ability(
                            source,
                            actor,
                            vec![Effect::new(TapEffect::with_spec(
                                ChooseSpec::SpecificObject(subject),
                            ))],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let mut queue = TriggerQueue::new();
                        ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                        assert_eq!(game.stack.len(), copies);
                        let label = format!(
                            "copies={copies} amount={amount} noise={noise} holder={holder:?} actor={actor:?}"
                        );
                        let mut owners = Vec::new();
                        for _ in 0..copies {
                            let acquisition = game
                                .stack
                                .last()
                                .unwrap()
                                .linked_exile_owner
                                .clone()
                                .expect("real gained trigger must capture its acquisition");
                            assert_eq!(acquisition.host, subject);
                            assert_eq!(acquisition.pair, pair);
                            if owners.contains(&acquisition) {
                                discrepancies.push(format!(
                                    "{label}: distinct grants share one runtime acquisition"
                                ));
                            }
                            owners.push(acquisition);
                            if let Err(error) = ironsmith::game_loop::resolve_stack_entry(&mut game)
                            {
                                discrepancies.push(format!(
                                    "{label}: gained self-linked trigger failed{error:?}"
                                ));
                            }
                        }
                        let counts: Vec<_> = owners
                            .iter()
                            .map(|owner| game.linked_exile_pair_members(owner).unwrap().len())
                            .collect();
                        if counts.iter().sum::<usize>() != amount
                            || counts.iter().filter(|n| **n > 0).count() > 1
                            || game.player(holder).unwrap().life != 20 + amount as i32
                        {
                            discrepancies.push(format!("{label}: member counts{counts:?}/life{}, required one acquisition to own{amount} cards and gain{amount}",game.player(holder).unwrap().life));
                        }
                        assert_eq!(
                            game.get_exiled_with_source_links(subject).len(),
                            amount + usize::from(noise)
                        );
                        for sid in resources {
                            assert_eq!(
                                game.object(game.find_object_by_stable_id(sid).unwrap())
                                    .unwrap()
                                    .zone,
                                Zone::Exile
                            );
                        }
                        assert_eq!(game.object(foreign).unwrap().zone, Zone::Graveyard);
                        assert_eq!(
                            game.object(game.find_object_by_stable_id(unrelated_stable).unwrap())
                                .unwrap()
                                .zone,
                            if noise { Zone::Exile } else { Zone::Graveyard }
                        );
                        assert_eq!(game.player(other).unwrap().life, 20);
                        game.validate_zone_consistency().unwrap();
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 96);
    assert!(
        discrepancies.is_empty(),
        "CR607.5/607.1c: separately acquired copies of a self-linked ability cannot share exile membership with another acquisition or an unrelated ability on the same permanent: {discrepancies:#?}"
    );
}

fn check_printed_linked_reference(mode: u8) {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::{OrderContext, SelectObjectsContext};
    use ironsmith::effects::{
        ChooseObjectsEffect, CreateTokenCopyEffect, ExileEffect, MoveToZoneEffect,
        PutCountersEffect, TapEffect,
    };
    use ironsmith::object::ObjectKind;
    use ironsmith::resolution::ResolutionProgram;
    use ironsmith::triggers::Trigger;
    use ironsmith::{
        Ability, CardId, CardType, ChoiceCount, ChooseSpec, Effect, ManaCost, ManaSymbol,
        ObjectFilter, ObjectId, PowerToughness, StackEntry, Subtype, TriggerQueue, Value, Zone,
    };
    struct Read {
        holder: PlayerId,
        last: bool,
        eligible: Vec<ObjectId>,
        errors: Vec<String>,
    }
    impl DecisionMaker for Read {
        fn decide_order(&mut self, _: &GameState, ctx: &OrderContext) -> Vec<ObjectId> {
            assert_eq!(ctx.player, self.holder);
            let mut rows = ctx.items.clone();
            let producer = |label: &String| {
                label.lines().any(|line| {
                    let text = line.trim().to_ascii_lowercase();
                    text == "exile"
                        || text.starts_with("exile ")
                        || text.ends_with(", exile")
                        || text.contains(", exile ")
                })
            };
            assert_eq!(
                rows.iter().filter(|(_, label)| producer(label)).count(),
                1,
                "native menu must distinguish producer: {:?}",
                ctx.items
            );
            rows.sort_by_key(|(_, label)| !producer(label));
            rows.into_iter().map(|(id, _)| id).collect()
        }
        fn decide_objects(&mut self, _: &GameState, ctx: &SelectObjectsContext) -> Vec<ObjectId> {
            let mut legal: Vec<_> = ctx
                .candidates
                .iter()
                .filter(|c| c.legal)
                .map(|c| c.id)
                .collect();
            let mut required = self.eligible.clone();
            legal.sort();
            required.sort();
            if ctx.player != self.holder || legal != required {
                self.errors.push(format!(
                    "a-card legal menu{legal:?}, required{required:?} for holder"
                ));
            }
            if self.last {
                legal.last().copied().into_iter().collect()
            } else {
                legal.first().copied().into_iter().collect()
            }
        }
    }
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for amount in 0usize..=3 {
        for depart in 0..3 {
            for noise in [false, true] {
                for holder in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                        for last in [false, true]
                            .into_iter()
                            .take(if mode == 8 { 2 } else { 1 })
                        {
                            let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                            let instruction = game.create_object_from_definition(
                                &CardDefinitionBuilder::new(
                                    CardId::new(),
                                    "Linked reference instruction",
                                )
                                .card_types(vec![CardType::Enchantment])
                                .build(),
                                actor,
                                Zone::Battlefield,
                            );
                            let mut stable = Vec::new();
                            let mut names = Vec::new();
                            for index in 0..amount {
                                let name = format!("Linked reference resource {index}");
                                let mut types = vec![CardType::Creature, CardType::Artifact];
                                if index == 2 {
                                    types.push(CardType::Enchantment);
                                }
                                let mut subtypes = vec![Subtype::Goblin];
                                if index == 1 {
                                    subtypes.push(Subtype::Warrior);
                                }
                                let mut symbols = vec![ManaSymbol::Generic(1)];
                                symbols.extend(
                                    [ManaSymbol::Red, ManaSymbol::Green, ManaSymbol::Blue]
                                        .into_iter()
                                        .take(index + 1),
                                );
                                let def = CardDefinitionBuilder::new(CardId::new(), name.clone())
                                    .card_types(types)
                                    .subtypes(subtypes)
                                    .mana_cost(ManaCost::from_symbols(symbols))
                                    .power_toughness(PowerToughness::fixed(
                                        index as i32 + 2,
                                        index as i32 + 4,
                                    ))
                                    .with_trigger(
                                        Trigger::this_enters_battlefield(),
                                        vec![Effect::gain_life(index as i32 + 1)],
                                    )
                                    .build();
                                let id = game.create_object_from_definition(
                                    &def,
                                    holder,
                                    Zone::Graveyard,
                                );
                                stable.push(game.object(id).unwrap().stable_id);
                                names.push(name);
                            }
                            let other = PlayerId::from_index(1 - holder.index() as u8);
                            let foreign = game.create_object_from_definition(
                                &CardDefinitionBuilder::new(
                                    CardId::new(),
                                    "Foreign linked reference resource",
                                )
                                .card_types(vec![CardType::Creature])
                                .power_toughness(PowerToughness::fixed(8, 9))
                                .build(),
                                other,
                                Zone::Graveyard,
                            );
                            let unrelated = game.create_object_from_definition(
                                &CardDefinitionBuilder::new(
                                    CardId::new(),
                                    "Unrelated source-exiled land",
                                )
                                .card_types(vec![CardType::Land])
                                .build(),
                                holder,
                                Zone::Graveyard,
                            );
                            let unrelated_stable = game.object(unrelated).unwrap().stable_id;
                            let unrelated_program = vec![Effect::new(ExileEffect::all(
                                ObjectFilter::land()
                                    .in_zone(Zone::Graveyard)
                                    .owned_by(PlayerFilter::You),
                            ))];
                            let pair = ironsmith_core::LinkedExilePair {
                                definition: ironsmith_core::LinkedExileDefinition([181 + mode; 32]),
                                pair: 0,
                            };
                            let reference =
                                || ChooseSpec::tagged(ironsmith_core::tag::SOURCE_EXILED_TAG);
                            let pair_filter = || {
                                ObjectFilter::tagged(ironsmith_core::tag::SOURCE_EXILED_TAG)
                                    .in_zone(Zone::Exile)
                            };
                            let reader_effects = match mode {
                                0 => vec![Effect::gain_life(Value::Count(pair_filter()))],
                                1 => vec![Effect::gain_life(Value::PowerOf(Box::new(reference())))],
                                2 => vec![Effect::gain_life(Value::ToughnessOf(Box::new(
                                    reference(),
                                )))],
                                3 => vec![Effect::gain_life(Value::ManaValueOf(Box::new(
                                    reference(),
                                )))],
                                4 => {
                                    vec![Effect::gain_life(Value::ColorsOf(Box::new(reference())))]
                                }
                                5 => vec![Effect::gain_life(Value::TypeCountOf(Box::new(
                                    reference(),
                                )))],
                                6 => vec![Effect::new(CreateTokenCopyEffect::one(reference()))],
                                7 => vec![Effect::new(MoveToZoneEffect::new(
                                    reference(),
                                    Zone::Hand,
                                    false,
                                ))],
                                9 => vec![Effect::gain_life(Value::ManaSymbolsInManaCostOf {
                                    spec: Box::new(reference()),
                                    color: ironsmith::Color::Red,
                                })],
                                10 => vec![Effect::gain_life(Value::BasePowerOf(Box::new(
                                    reference(),
                                )))],
                                11 => vec![Effect::gain_life(Value::CountersOn(
                                    Box::new(reference()),
                                    Some(ironsmith::CounterType::Charge),
                                ))],
                                _ => vec![
                                    Effect::new(
                                        ChooseObjectsEffect::new(
                                            pair_filter(),
                                            ChoiceCount::up_to(1),
                                            PlayerFilter::You,
                                            "selected_linked_member",
                                        )
                                        .replace_tagged_objects(),
                                    ),
                                    Effect::new(MoveToZoneEffect::new(
                                        ChooseSpec::tagged("selected_linked_member"),
                                        Zone::Hand,
                                        false,
                                    )),
                                ],
                            };
                            let def = CardDefinitionBuilder::new(
                                CardId::new(),
                                "Printed linked reference subject",
                            )
                            .card_types(vec![CardType::Artifact])
                            .with_ability(Ability::triggered(
                                Trigger::becomes_tapped(),
                                ResolutionProgram::from_effects(vec![Effect::new(
                                    ExileEffect::all(
                                        ObjectFilter::creature()
                                            .in_zone(Zone::Graveyard)
                                            .owned_by(PlayerFilter::You),
                                    ),
                                )])
                                .with_linked_exile_pair(pair),
                            ))
                            .with_ability(Ability::triggered(
                                Trigger::becomes_tapped(),
                                ResolutionProgram::from_effects(reader_effects)
                                    .with_linked_exile_pair(pair),
                            ))
                            .with_ability(Ability::activated(
                                ironsmith::cost::TotalCost::free(),
                                unrelated_program.clone(),
                            ))
                            .build();
                            let subject =
                                game.create_object_from_definition(&def, holder, Zone::Battlefield);
                            if noise {
                                let mut activation =
                                    StackEntry::ability(subject, holder, unrelated_program);
                                activation.ability_index = Some(2);
                                game.stack.push(activation);
                                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                            }
                            game.stack.push(StackEntry::ability(
                                instruction,
                                actor,
                                vec![Effect::new(TapEffect::with_spec(
                                    ChooseSpec::SpecificObject(subject),
                                ))],
                            ));
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                            let mut dm = Read {
                                holder,
                                last,
                                eligible: vec![],
                                errors: vec![],
                            };
                            let mut queue = TriggerQueue::new();
                            ironsmith::game_loop::put_triggers_on_stack_with_dm(
                                &mut game, &mut queue, &mut dm,
                            )
                            .unwrap();
                            assert_eq!(game.stack.len(), 2);
                            assert!(
                                game.stack
                                    .last()
                                    .unwrap()
                                    .ability_effects
                                    .as_ref()
                                    .unwrap()
                                    .all_effects()
                                    .iter()
                                    .any(|effect| effect.downcast_ref::<ExileEffect>().is_some()),
                                "actual trigger order must put the producer on top"
                            );
                            let producer_owner = game
                                .stack
                                .last()
                                .unwrap()
                                .linked_exile_owner
                                .clone()
                                .expect("actual printed producer admission");
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                            assert_eq!(game.stack.len(), 1);
                            let reader_owner = game
                                .stack
                                .last()
                                .unwrap()
                                .linked_exile_owner
                                .clone()
                                .expect("actual printed reader admission");
                            assert_eq!(producer_owner, reader_owner);
                            assert_eq!(reader_owner.host, subject);
                            if mode == 11 {
                                for (index, sid) in stable.iter().enumerate() {
                                    let id = game.find_object_by_stable_id(*sid).unwrap();
                                    assert_eq!(game.object(id).unwrap().zone, Zone::Exile);
                                    assert_eq!(
                                        game.counter_count(id, ironsmith::CounterType::Charge),
                                        0
                                    );
                                    game.stack.push(StackEntry::ability(
                                        instruction,
                                        actor,
                                        vec![Effect::new(PutCountersEffect::new(
                                            ironsmith::CounterType::Charge,
                                            index as i32 + 1,
                                            ChooseSpec::SpecificObject(id),
                                        ))],
                                    ));
                                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                    assert_eq!(
                                        game.counter_count(id, ironsmith::CounterType::Charge),
                                        index as u32 + 1
                                    );
                                }
                            }
                            if amount > 0 && depart > 0 {
                                let old_exile = game.find_object_by_stable_id(stable[0]).unwrap();
                                game.stack.push(StackEntry::ability(
                                    instruction,
                                    actor,
                                    vec![Effect::new(MoveToZoneEffect::new(
                                        ChooseSpec::SpecificObject(old_exile),
                                        Zone::Hand,
                                        false,
                                    ))],
                                ));
                                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                let hand = game.find_object_by_stable_id(stable[0]).unwrap();
                                assert_ne!(hand, old_exile);
                                if depart == 2 {
                                    game.stack.push(StackEntry::ability(
                                        instruction,
                                        actor,
                                        vec![Effect::new(MoveToZoneEffect::new(
                                            ChooseSpec::SpecificObject(hand),
                                            Zone::Exile,
                                            false,
                                        ))],
                                    ));
                                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                    assert_ne!(
                                        game.find_object_by_stable_id(stable[0]).unwrap(),
                                        old_exile
                                    );
                                }
                            }
                            let survivors: Vec<_> =
                                (0..amount).filter(|i| *i != 0 || depart == 0).collect();
                            dm.eligible = survivors
                                .iter()
                                .map(|i| game.find_object_by_stable_id(stable[*i]).unwrap())
                                .collect();
                            let label = format!(
                                "mode={mode} amount={amount} depart={depart} noise={noise} holder={holder:?} actor={actor:?} last={last}"
                            );
                            let mut members = game
                                .linked_exile_pair_members(&reader_owner)
                                .unwrap()
                                .to_vec();
                            let mut expected_members = dm.eligible.clone();
                            members.sort();
                            expected_members.sort();
                            if members != expected_members {
                                discrepancies.push(format!("{label}: live linked collection{members:?}, required{expected_members:?}"));
                            }
                            let mut expected_gain = survivors
                                .iter()
                                .map(|i| match mode {
                                    0 => 1,
                                    1 => *i as i32 + 2,
                                    2 => *i as i32 + 4,
                                    3 => *i as i32 + 2,
                                    4 => *i as i32 + 1,
                                    5 => 3 + i32::from(*i > 0),
                                    9 => 1,
                                    10 => *i as i32 + 2,
                                    11 => *i as i32 + 1,
                                    _ => 0,
                                })
                                .sum::<i32>();
                            let moved: Vec<_> = if mode == 7 {
                                survivors.clone()
                            } else if mode == 8 {
                                let chosen = if last {
                                    expected_members.last()
                                } else {
                                    expected_members.first()
                                };
                                survivors
                                    .iter()
                                    .copied()
                                    .filter(|i| {
                                        Some(&game.find_object_by_stable_id(stable[*i]).unwrap())
                                            == chosen
                                    })
                                    .collect()
                            } else {
                                vec![]
                            };
                            if let Err(error) =
                                ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm)
                            {
                                discrepancies.push(format!(
                                    "{label}: linked reader refused to resolve{error:?}"
                                ));
                                cases += 1;
                                continue;
                            }
                            for error in dm.errors {
                                discrepancies.push(format!("{label}: {error}"));
                            }
                            for index in 0..amount {
                                let id = game.find_object_by_stable_id(stable[index]).unwrap();
                                let expected_zone =
                                    if index == 0 && depart == 1 || moved.contains(&index) {
                                        Zone::Hand
                                    } else {
                                        Zone::Exile
                                    };
                                if game.object(id).unwrap().zone != expected_zone {
                                    discrepancies.push(format!("{label}: resource{index} zone{:?}, required{expected_zone:?}",game.object(id).unwrap().zone));
                                }
                            }
                            let remaining =
                                game.linked_exile_pair_members(&reader_owner).unwrap().len();
                            if remaining != survivors.len() - moved.len() {
                                discrepancies.push(format!(
                                    "{label}: remaining linked members{remaining}, required{}",
                                    survivors.len() - moved.len()
                                ));
                            }
                            if mode == 6 {
                                let tokens: Vec<_> = game
                                    .battlefield
                                    .iter()
                                    .filter_map(|id| game.object(*id))
                                    .filter(|o| o.kind == ObjectKind::Token)
                                    .collect();
                                let mut actual: Vec<_> =
                                    tokens.iter().map(|o| o.name.clone()).collect();
                                let mut expected: Vec<_> =
                                    survivors.iter().map(|i| names[*i].clone()).collect();
                                actual.sort();
                                expected.sort();
                                if actual != expected
                                    || tokens.iter().any(|o| {
                                        o.owner != holder
                                            || game.current_controller(o.id) != Some(holder)
                                    })
                                {
                                    discrepancies.push(format!("{label}: token names{actual:?}, required{expected:?} under holder control"));
                                }
                                let mut token_queue = TriggerQueue::new();
                                ironsmith::put_triggers_on_stack(&mut game, &mut token_queue)
                                    .unwrap();
                                let n = game.stack.len();
                                if n != survivors.len() {
                                    discrepancies.push(format!(
                                        "{label}: copied ETB triggers{n}, required{}",
                                        survivors.len()
                                    ));
                                }
                                for _ in 0..n {
                                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                }
                                expected_gain = survivors.iter().map(|i| *i as i32 + 1).sum();
                            }
                            if game.player(holder).unwrap().life != 20 + expected_gain
                                || game.player(other).unwrap().life != 20
                            {
                                discrepancies.push(format!(
                                    "{label}: reader life{}, required{}",
                                    game.player(holder).unwrap().life,
                                    20 + expected_gain
                                ));
                            }
                            assert_eq!(game.object(foreign).unwrap().zone, Zone::Graveyard);
                            assert_eq!(
                                game.object(
                                    game.find_object_by_stable_id(unrelated_stable).unwrap()
                                )
                                .unwrap()
                                .zone,
                                if noise { Zone::Exile } else { Zone::Graveyard }
                            );
                            game.validate_zone_consistency().unwrap();
                            cases += 1;
                        }
                    }
                }
            }
        }
    }
    assert_eq!(cases, if mode == 8 { 192 } else { 96 });
    assert!(
        discrepancies.is_empty(),
        "CR607.2a/607.3/107.2: only live cards from the exact printed pair are readable; numeric answers sum all references, the-card actions apply to each, and a-card actions choose one: {discrepancies:#?}"
    );
}

