        cast(&mut g,&mut q,&mut d,actor,vec![Effect::conditional(Condition::PlayerCommittedCrimeThisTurn{player:PlayerFilter::You},vec![Effect::gain_life(2)],vec![])]);casts+=1;one(&mut g,&mut q,&mut d);probes+=1;let got=g.player(actor).unwrap().life;if got!=20+2*n {errors.push(format!("crime-domain-history {label} query=actor: got={got} expected={}",20+2*n));}
