        settle(&mut g,&mut q,&mut d);if matches!(kind,12|14) {let affected=g.battlefield.iter().copied().filter(|id|g.current_controller(*id)==Some(other) && g.current_has_card_type(*id,CardType::Artifact)).collect::<Vec<_>>();assert_eq!(affected.len(),3);assert_eq!(affected.iter().filter(|id|g.is_tapped(**id)).count(),if kind==12 {3}else{1});assert!(g.is_tapped(markers[other.index()]));}let own_life=g.player(actor).unwrap().life;let other_life=g.player(other).unwrap().life;if own_life!=20+3*n || other_life!=20+3*n {errors.push(format!("crime-domain-final {label}: actor={own_life} other={other_life} expected_each={}",20+3*n));}
