#[test]
fn cr_702_67a_full_garrison_fortify_requires_own_main_empty_stack_and_own_land() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::TargetsContext;
    use ironsmith::triggers::{Trigger,TriggerQueue};
    use ironsmith::{Ability,AbilityKind,CardId,CardType,ChooseSpec,Effect,LegalAction,ManaCost,ObjectFilter,ObjectId,Phase,Target,Zone,ManaSymbol,PowerToughness,CounterType,Color,ColorSet,Subtype,Supertype};
    struct Choices{wanted:Vec<Target>,targets:usize}
    impl DecisionMaker for Choices {
        fn decide_targets(&mut self,_:&GameState,c:&TargetsContext)->Vec<Target>{let mut chosen=vec![];for r in &c.requirements {let t=self.wanted.iter().find(|t|r.legal_targets.contains(t)).expect("selected real public target is legal for this requirement").clone();chosen.push(t);}self.targets+=chosen.len();chosen}
        fn decide_options(&mut self,_:&GameState,c:&SelectOptionsContext)->Vec<usize>{c.options.iter().filter(|o|o.legal).take(c.min).map(|o|o.index).collect()}
    }
    fn priority(g:&mut GameState,q:&mut TriggerQueue,d:&mut Choices,p:PlayerId){let mut s=ironsmith::PriorityLoopState::new(g.players_in_game());for _ in 0..g.players_in_game(){if g.turn.priority_player==Some(p){return;}ironsmith::game_loop::apply_priority_response_with_dm(g,q,&mut s,&ironsmith::PriorityResponse::PriorityAction(LegalAction::PassPriority),d).unwrap();}assert_eq!(g.turn.priority_player,Some(p));}
    fn one(g:&mut GameState,q:&mut TriggerQueue,d:&mut Choices){assert!(!g.stack.is_empty());let mut s=ironsmith::PriorityLoopState::new(g.players_in_game());for _ in 0..g.players_in_game(){ironsmith::game_loop::apply_priority_response_with_dm(g,q,&mut s,&ironsmith::PriorityResponse::PriorityAction(LegalAction::PassPriority),d).unwrap();}ironsmith::game_loop::advance_priority_with_dm(g,q,d).unwrap();}
    fn settle(g:&mut GameState,q:&mut TriggerQueue,d:&mut Choices){for _ in 0..160 {ironsmith::game_loop::advance_priority_with_dm(g,q,d).unwrap();if g.stack.is_empty(){return;}one(g,q,d);}panic!("finite crime target fixture");}
    use ironsmith::continuous::Modification;use ironsmith::effects::ApplyContinuousEffect;use ironsmith::Until;
    fn cast(g:&mut GameState,q:&mut TriggerQueue,d:&mut Choices,p:PlayerId,effects:Vec<Effect>)->ObjectId {priority(g,q,d,p);let def=CardDefinitionBuilder::new(CardId::new(),"Native equipment contract instruction").card_types(vec![CardType::Instant]).mana_cost(ManaCost::new()).with_spell_effect(effects).build();let hand=g.create_object_from_definition(&def,p,Zone::Hand);let stable=g.object(hand).unwrap().stable_id;let a=ironsmith::compute_legal_actions(g,p).unwrap().into_iter().find(|a|matches!(a,LegalAction::CastSpell{spell_id,..}if *spell_id==hand)).expect("actual contract instruction cast is legal");cr_audit_complete_priority_action_with_dm(g,p,a,d,q).unwrap();g.find_object_by_stable_id(stable).unwrap()}
    let definition=ironsmith_compiler_runtime::compile_to_runtime_definition("Darksteel Garrison","Mana cost: {2}\nType: Artifact — Fortification\nFirst printed set: Future Sight\nFortified land has indestructible.\nWhenever fortified land becomes tapped, target creature gets +1/+1 until end of turn.\nFortify {3} ({3}: Attach to target land you control. Fortify only as a sorcery. This card enters unattached and stays on the battlefield if the land leaves.)",false).unwrap();assert!(!ironsmith::cards::generated_definition_has_unimplemented_content(&definition));
    let(mut games,mut mana_actions,mut casts,mut activations,mut targets,mut paid,mut denied)=(0,0,0,0,0,0,0);let mut errors=vec![];
    for seat in 0u8..2{let actor=PlayerId::from_index(seat);let other=PlayerId::from_index(1-seat);for own_turn in [false,true]{let active=if own_turn{actor}else{other};for window in 0u8..3{for pending in [false,true]{for own_host in [false,true]{let controller=if own_host{actor}else{other};for kind in 0u8..3{
        let label=format!("actor={seat} own_turn={own_turn} window={window} pending={pending} own_host={own_host} kind={kind}");let expected=own_turn&&window<2&&!pending&&own_host&&kind==0;let mut g=GameState::new(vec!["A".into(),"B".into()],20);g.set_starting_player(active);g.turn.phase=match window{0=>Phase::FirstMain,1=>Phase::NextMain,_=>Phase::Beginning};g.turn.step=if window==2{Some(ironsmith::Step::Upkeep)}else{None};let turn=g.turn.turn_number;let device=g.create_object_from_definition(&definition,actor,Zone::Battlefield);let mut host=CardDefinitionBuilder::new(CardId::new(),"Fortify canonical timing target").card_types(vec![match kind{0=>CardType::Land,1=>CardType::Artifact,_=>CardType::Creature}]);if kind==2{host=host.power_toughness(PowerToughness::fixed(4,4));}let host=g.create_object_from_definition(&host.build(),controller,Zone::Battlefield);let stable=g.object(host).unwrap().stable_id;
        let keeper=CardDefinitionBuilder::new(CardId::new(),"Fortify timing real priority keeper").card_types(vec![CardType::Artifact]).with_ability(Ability::activated(ironsmith::cost::TotalCost::free(),vec![Effect::gain_life(0)])).build();for p in [actor,other]{g.create_object_from_definition(&keeper,p,Zone::Battlefield);}let mut mana=Ability::activated(ironsmith::cost::TotalCost::free(),vec![]);if let AbilityKind::Activated(a)=&mut mana.kind{a.mana_output=Some(vec![ManaSymbol::Colorless]);}let payer=g.create_object_from_definition(&CardDefinitionBuilder::new(CardId::new(),"Real fortify timing payer").card_types(vec![CardType::Artifact]).with_ability(mana).build(),actor,Zone::Battlefield);let mut q=TriggerQueue::new();let mut d=Choices{wanted:vec![Target::Object(host)],targets:0};let background=if pending{cast(&mut g,&mut q,&mut d,active,vec![Effect::gain_life(0)]);casts+=1;Some(g.stack.last().unwrap().target_id())}else{None};priority(&mut g,&mut q,&mut d,actor);
        for amount in 1u32..=3{let action=ironsmith::compute_legal_actions(&g,actor).unwrap().into_iter().find(|a|matches!(a,LegalAction::ActivateManaAbility{source,..}if *source==payer)).unwrap();cr_audit_complete_priority_action_with_dm(&mut g,actor,action,&mut d,&mut q).unwrap();mana_actions+=1;assert_eq!(g.player(actor).unwrap().mana_pool.total(),amount);}assert_eq!(g.turn.priority_player,Some(actor));assert_eq!(g.stack.len(),usize::from(pending));assert_eq!(g.stack.last().map(|e|e.target_id()),background);
        let abilities=g.current_abilities(device).unwrap();let variants=abilities.iter().enumerate().filter_map(|(i,a)|if let AbilityKind::Activated(a)=&a.kind{Some((i,a.mana_cost.mana_cost().unwrap().generic_mana_total()))}else{None}).collect::<Vec<_>>();assert_eq!(variants.len(),1);let(index,cost)=variants[0];assert_eq!(cost,3);let actions=ironsmith::compute_legal_actions(&g,actor).unwrap().into_iter().filter(|a|matches!(a,LegalAction::ActivateAbility{source,..}if *source==device)).collect::<Vec<_>>();assert!(actions.len()<=1);let action=actions.into_iter().find(|a|matches!(a,LegalAction::ActivateAbility{ability_index,..}if *ability_index==index));let offered=action.is_some();if offered!=expected{errors.push(format!("fortify-timing-admission {label}: offered={offered} expected={expected}"));}
        let mut spent=0;if offered&&expected{cr_audit_complete_priority_action_with_dm(&mut g,actor,action.unwrap(),&mut d,&mut q).unwrap();activations+=1;let e=g.stack.last().unwrap();assert_eq!(e.object_id,device);assert_eq!(e.ability_index,Some(index));assert_eq!(e.targets,vec![Target::Object(host)]);spent=e.mana_spent_on_activation.total();assert_eq!(spent,3);paid+=spent;settle(&mut g,&mut q,&mut d);if g.object(device).unwrap().attached_to!=Some(ironsmith::object::AttachmentTarget::Object(host)){errors.push(format!("fortify-timing-attachment {label}: expected attached"));}}else{denied+=1;assert!(g.object(device).unwrap().attached_to.is_none());settle(&mut g,&mut q,&mut d);}
        assert_eq!(g.player(actor).unwrap().mana_pool.total(),3-spent);assert_eq!(d.targets,usize::from(offered&&expected));targets+=d.targets;assert_eq!(g.current_controller(host),Some(controller));assert_eq!(g.current_controller(device),Some(actor));assert_eq!(g.find_object_by_stable_id(stable),Some(host));for id in [device,host]{assert_eq!(g.object(id).unwrap().zone,Zone::Battlefield);}for p in &g.players{assert_eq!(p.life,20);}assert_eq!(g.turn.turn_number,turn);assert_eq!(g.turn.active_player,active);assert!(g.stack.is_empty());g.validate_zone_consistency().unwrap();games+=1;eprintln!("fortify-timing-observed {label} offered={offered} expected={expected} paid={spent}");
    }}}}}}eprintln!("fortify-timing-summary games={games} mana_actions={mana_actions} casts={casts} activations={activations} targets={targets} paid={paid} denied={denied}");assert!(errors.is_empty(),"CR702.67a: fully funded full canonical Garrison fortify costs3, targets your land, and activates only on your own main phase with an empty stack: {}",errors.join("\n"));
}

