        let abilities=g.current_abilities(device).unwrap();let variants=abilities.iter().enumerate().filter_map(|(i,a)|if let AbilityKind::Activated(a)=&a.kind{Some((i,a.mana_cost.mana_cost().unwrap().generic_mana_total()))}else{None}).collect::<Vec<_>>();assert_eq!(variants.len(),1);let(index,cost)=variants[0];assert_eq!(cost,3);let a=ironsmith::compute_legal_actions(&g,actor).unwrap().into_iter().find(|a|matches!(a,LegalAction::ActivateAbility{source,ability_index}if *source==device&&*ability_index==index)).expect("own land fully funded actual fortify");cr_audit_complete_priority_action_with_dm(&mut g,actor,a,&mut d,&mut q).unwrap();activations+=1;assert_eq!(g.stack.len(),1);let e=g.stack.last().unwrap();assert_eq!(e.targets,vec![Target::Object(host)]);assert_eq!(e.mana_spent_on_activation.total(),3);let pending=e.target_id();assert_eq!(g.player(actor).unwrap().mana_pool.total(),0);
