        let departed=if source_leaves{device}else{host};let departed_stable=if source_leaves{device_stable}else{host_stable};d.wanted=vec![Target::Object(departed)];let chosen=ChooseSpec::target(ChooseSpec::Object(ObjectFilter::specific(departed).in_zone(Zone::Battlefield)));let effect=if exile{Effect::new(ExileEffect::with_spec(chosen))}else{Effect::new(DestroyEffect::with_spec(chosen))};cast(&mut g,&mut q,&mut d,actor,vec![effect]);casts+=1;assert_eq!(g.stack.len(),2);one(&mut g,&mut q,&mut d);assert_eq!(g.stack.len(),1);assert_eq!(g.stack.last().unwrap().target_id(),pending);assert_eq!(g.stack.last().unwrap().controller,actor);assert_eq!(g.stack.last().unwrap().object_id,device);assert_eq!(g.stack.last().unwrap().targets,vec![Target::Object(host)]);let away=g.find_object_by_stable_id(departed_stable).unwrap();assert_ne!(away,departed);assert!(g.object(departed).is_none());let away_zone=if exile{Zone::Exile}else{Zone::Graveyard};assert_eq!(g.object(away).unwrap().zone,away_zone);assert_eq!(g.object(away).unwrap().owner,actor);let mut responses=1;
        if returns{d.wanted=vec![Target::Object(away)];cast(&mut g,&mut q,&mut d,actor,vec![Effect::new(MoveToZoneEffect::new(ChooseSpec::target(ChooseSpec::Object(ObjectFilter::specific(away).in_zone(away_zone))),Zone::Battlefield,false))]);casts+=1;responses+=1;assert_eq!(g.stack.len(),2);one(&mut g,&mut q,&mut d);assert_eq!(g.stack.len(),1);let e=g.stack.last().unwrap();assert_eq!(e.target_id(),pending);assert_eq!(e.object_id,device);assert_eq!(e.controller,actor);assert_eq!(e.targets,vec![Target::Object(host)]);let returned=g.find_object_by_stable_id(departed_stable).unwrap();assert_ne!(returned,away);assert_ne!(returned,departed);assert_eq!(g.object(returned).unwrap().zone,Zone::Battlefield);assert_eq!(g.current_controller(returned),Some(actor));assert!(!g.is_tapped(returned));}
        let current_device=g.find_object_by_stable_id(device_stable).unwrap();let current_host=g.find_object_by_stable_id(host_stable).unwrap();let device_on_bf=!source_leaves||returns;let host_on_bf=source_leaves||returns;assert_eq!(g.object(current_device).unwrap().zone,if device_on_bf{Zone::Battlefield}else{away_zone});assert_eq!(g.object(current_host).unwrap().zone,if host_on_bf{Zone::Battlefield}else{away_zone});assert!(g.object(current_device).unwrap().attached_to.is_none());settle(&mut g,&mut q,&mut d);let old_attached=g.object(current_device).unwrap().attached_to.is_some();if old_attached{errors.push(format!("fortify-zone-old-incarnation {label}: old ability attached current source to {:?}",g.object(current_device).unwrap().attached_to));}if host_on_bf{let protected=g.object_has_ability(current_host,&ironsmith::static_abilities::StaticAbility::indestructible());if protected{errors.push(format!("fortify-zone-old-static {label}: current land is protected by an attachment that old ability must not make"));}}
