        let native=CardDefinitionBuilder::new(CardId::new(),"Native haste Sliver for independent trigger counter").card_types(vec![CardType::Creature]).subtypes(vec![Subtype::Sliver]).power_toughness(PowerToughness::fixed(3,7)).haste().build();let attacker=g.create_object_from_definition(&native,actor,Zone::Battlefield);let attacker_stable=g.object(attacker).unwrap().stable_id;
        let keeper=CardDefinitionBuilder::new(CardId::new(),"Native priority keeper for real Stifle response").card_types(vec![CardType::Artifact]).with_ability(Ability::activated(ironsmith::cost::TotalCost::free(),vec![Effect::gain_life(0)])).build();for p in [actor,other]{g.create_object_from_definition(&keeper,p,Zone::Battlefield);}
        let mana=CardDefinitionBuilder::new(CardId::new(),"Native tap for one blue artifact").card_types(vec![CardType::Artifact]).with_ability(Ability::mana(ironsmith::cost::TotalCost::free(),vec![ManaSymbol::Blue])).build();let payer=g.create_object_from_definition(&mana,caster,Zone::Battlefield);let hand=g.create_object_from_definition(&stifle,caster,Zone::Hand);let spell_stable=g.object(hand).unwrap().stable_id;
