                    priority(&mut g,&mut q,&mut dm,caster);assert_eq!(g.stack.len(),2);assert_eq!(g.player(caster).unwrap().mana_pool.total(),0);assert!(!g.is_tapped(payer));let action=ironsmith::compute_legal_actions(&g,caster).unwrap().into_iter().find(|a|matches!(a,LegalAction::ActivateManaAbility{source,ability_index:0}if *source==payer)).expect("actual tap-for-blue activation");cr_audit_complete_priority_action_with_dm(&mut g,caster,action,&mut dm,&mut q).unwrap();mana_actions+=1;assert!(g.is_tapped(payer));assert_eq!(g.player(caster).unwrap().mana_pool.total(),1);assert!(!ironsmith::compute_legal_actions(&g,caster).unwrap().iter().any(|a|matches!(a,LegalAction::ActivateManaAbility{source,..}if *source==payer)));assert_eq!(g.stack.len(),2);
