                    let expected=if mode<=1{1+copies}else{0};observed_frenzy=g.stack.len();let unique=g.stack.iter().map(|e|e.target_id()).collect::<std::collections::HashSet<_>>().len();if observed_frenzy!=expected||unique!=observed_frenzy||g.stack.iter().any(|e|e.object_id!=attacker||e.controller!=actor||!e.is_ability||!e.targets.is_empty()){errors.push(format!("frenzy-edge-stack {label}: entries={observed_frenzy} unique={unique} expected={expected}"));}frenzy_entries+=observed_frenzy;
