        let label=format!("actor={seat} prior_two={prior_two} late={late} change={change}");let mut g=GameState::new(vec!["A".into(),"B".into()],20);g.set_starting_player(actor);g.turn.phase=Phase::FirstMain;g.turn.step=None;let turn=g.turn.turn_number;keepers(&mut g);let relic=CardDefinitionBuilder::new(CardId::new(),"Native artifact for canonical Bitter Ordeal history").card_types(vec![CardType::Artifact]).build();let victims=[g.create_object_from_definition(&relic,actor,Zone::Battlefield),g.create_object_from_definition(&relic,other,Zone::Battlefield)];let late_victim=g.create_object_from_definition(&relic,other,Zone::Battlefield);for p in [actor,other]{for _ in 0..8{g.create_object_from_definition(&relic,p,Zone::Library);}}
