    struct Choices{actor:PlayerId,wanted:Option<Target>,change:bool,booleans:usize,targets:usize,searches:Vec<(ironsmith::ids::StableId,PlayerId)>}
    impl DecisionMaker for Choices {
        fn decide_targets(&mut self,_:&GameState,c:&TargetsContext)->Vec<Target>{assert_eq!(c.player,self.actor);if c.requirements.is_empty(){return vec![];}assert_eq!(c.requirements.len(),1);let t=self.wanted.expect("actual selected legal target");assert!(c.requirements[0].legal_targets.contains(&t),"actual chosen target belongs to public legal domain");self.targets+=1;vec![t]}
        fn decide_boolean(&mut self,_:&GameState,c:&BooleanContext)->bool{assert_eq!(c.player,self.actor);assert!(c.description.starts_with("Choose new targets for"),"only independent spell-copy retarget permission expected: {}",c.description);self.booleans+=1;self.change&&self.booleans%2==1}
        fn decide_options(&mut self,_:&GameState,c:&SelectOptionsContext)->Vec<usize>{c.options.iter().filter(|o|o.legal).take(c.min).map(|o|o.index).collect()}
        fn decide_objects(&mut self,g:&GameState,c:&SelectObjectsContext)->Vec<ObjectId>{assert_eq!(c.player,self.actor);let id=c.candidates.iter().find(|c|c.legal).expect("nonempty real library search").id;assert!(c.candidates.iter().filter(|c|c.legal).all(|c|g.object(c.id).unwrap().zone==Zone::Library));let o=g.object(id).unwrap();self.searches.push((o.stable_id,o.owner));vec![id]}
    }
    fn priority(g:&mut GameState,q:&mut TriggerQueue,d:&mut Choices,p:PlayerId){let mut s=ironsmith::PriorityLoopState::new(g.players_in_game());for _ in 0..g.players_in_game(){if g.turn.priority_player==Some(p){return;}ironsmith::game_loop::apply_priority_response_with_dm(g,q,&mut s,&ironsmith::PriorityResponse::PriorityAction(LegalAction::PassPriority),d).unwrap();}assert_eq!(g.turn.priority_player,Some(p));}
    fn one(g:&mut GameState,q:&mut TriggerQueue,d:&mut Choices){assert!(!g.stack.is_empty());let mut s=ironsmith::PriorityLoopState::new(g.players_in_game());for _ in 0..g.players_in_game(){ironsmith::game_loop::apply_priority_response_with_dm(g,q,&mut s,&ironsmith::PriorityResponse::PriorityAction(LegalAction::PassPriority),d).unwrap();}ironsmith::game_loop::advance_priority_with_dm(g,q,d).unwrap();}
    fn settle(g:&mut GameState,q:&mut TriggerQueue,d:&mut Choices){for _ in 0..160{ironsmith::game_loop::advance_priority_with_dm(g,q,d).unwrap();if g.stack.is_empty(){return;}one(g,q,d);}panic!("finite actual gravestorm instruction stack");}
    fn cast_hand(g:&mut GameState,q:&mut TriggerQueue,d:&mut Choices,hand:ObjectId)->ObjectId{let p=d.actor;priority(g,q,d,p);let stable=g.object(hand).unwrap().stable_id;let a=ironsmith::compute_legal_actions(g,p).unwrap().into_iter().find(|a|matches!(a,LegalAction::CastSpell{spell_id,..}if *spell_id==hand)).expect("actual native/canonical cast with legal cost and targets");cr_audit_complete_priority_action_with_dm(g,p,a,d,q).unwrap();g.find_object_by_stable_id(stable).unwrap()}
    fn move_by_spell(g:&mut GameState,q:&mut TriggerQueue,d:&mut Choices,id:ObjectId,from:Zone,to:Zone){let background=g.stack.len();let def=CardDefinitionBuilder::new(CardId::new(),"Native actual gravestorm history zone instruction").card_types(vec![CardType::Instant]).mana_cost(ManaCost::new()).with_spell_effect(vec![Effect::new(MoveToZoneEffect::new(ChooseSpec::target(ChooseSpec::Object(ObjectFilter::specific(id).in_zone(from))),to,false))]).build();let hand=g.create_object_from_definition(&def,d.actor,Zone::Hand);d.wanted=Some(Target::Object(id));cast_hand(g,q,d,hand);assert_eq!(g.stack.len(),background+1);one(g,q,d);}
    fn keepers(g:&mut GameState){let def=CardDefinitionBuilder::new(CardId::new(),"Native gravestorm genuine priority keeper").card_types(vec![CardType::Artifact]).with_ability(Ability::activated(ironsmith::cost::TotalCost::free(),vec![Effect::gain_life(0)])).build();for seat in 0u8..2{g.create_object_from_definition(&def,PlayerId::from_index(seat),Zone::Battlefield);}}
    use ironsmith::Subtype;
    use ironsmith::costs::Cost;
    use ironsmith::cost::TotalCost;
    use ironsmith::AbilityKind;
    let canonical=ironsmith_compiler_runtime::compile_to_runtime_definition("Virulent Sliver","Mana cost: {G}\nType: Creature — Sliver\nFirst printed set: Future Sight\nPower/Toughness: 1/1\nAll Sliver creatures have poisonous 1. (Whenever a Sliver deals combat damage to a player, that player gets a poison counter. A player with ten or more poison counters loses the game.)",false).expect("complete canonical Virulent Sliver compiles strictly");assert!(!ironsmith::cards::generated_definition_has_unimplemented_content(&canonical));
    let(mut games,mut activations,mut targets)=(0,0,0);let mut errors=vec![];
    for seat in 0u8..2{let actor=PlayerId::from_index(seat);let other=PlayerId::from_index(1-seat);for opposing_grant in [false,true]{let granter=if opposing_grant{other}else{actor};for copies in 0usize..=2{for native in 0u8..3{for infect in [false,true]{
        let label=format!("actor={seat} opposing_grant={opposing_grant} copies={copies} native={native} infect={infect}");let mut g=GameState::new(vec!["A".into(),"B".into()],20);g.set_starting_player(actor);g.turn.phase=Phase::FirstMain;g.turn.step=None;let turn=g.turn.turn_number;keepers(&mut g);let sources=(0..copies).map(|_|g.create_object_from_definition(&canonical,granter,Zone::Battlefield)).collect::<Vec<_>>();let effects=vec![Effect::deal_damage(1,ChooseSpec::target(ChooseSpec::Player(PlayerFilter::Any)))];let choices=effects.iter().filter_map(|e|e.0.get_target_spec().filter(|s|s.is_target()).cloned()).collect::<Vec<_>>();let mut a=Ability::activated(TotalCost::from_cost(Cost::tap()),effects);if let AbilityKind::Activated(a)=&mut a.kind{a.choices=choices;}let mut b=CardDefinitionBuilder::new(CardId::new(),"Native haste Sliver tap for actual noncombat damage").card_types(vec![CardType::Creature]).subtypes(vec![Subtype::Sliver]).power_toughness(PowerToughness::fixed(3,7)).haste().with_ability(a);if native>0{b=b.poisonous(if native==1{0}else{2});}if infect{b=b.infect();}let source=g.create_object_from_definition(&b.build(),actor,Zone::Battlefield);let stable=g.object(source).unwrap().stable_id;let instance_count=g.current_abilities(source).unwrap().iter().filter(|a|matches!(a.kind,AbilityKind::Triggered(_))).count();let expected_instances=copies+usize::from(native>0);if instance_count!=expected_instances{errors.push(format!("poisonous-noncombat-instances {label}: got={instance_count} expected={expected_instances}"));}
        let mut q=TriggerQueue::new();let mut d=Choices{actor,wanted:Some(Target::Player(other)),change:false,booleans:0,targets:0,searches:vec![]};ironsmith::game_loop::advance_priority_with_dm(&mut g,&mut q,&mut d).unwrap();assert!(g.stack.is_empty());priority(&mut g,&mut q,&mut d,actor);let abilities=g.current_abilities(source).unwrap();let indices=abilities.iter().enumerate().filter_map(|(i,a)|matches!(a.kind,AbilityKind::Activated(_)).then_some(i)).collect::<Vec<_>>();assert_eq!(indices.len(),1);let index=indices[0];assert!(!g.is_tapped(source));let action=ironsmith::compute_legal_actions(&g,actor).unwrap().into_iter().find(|a|matches!(a,LegalAction::ActivateAbility{source:s,ability_index}if *s==source&&*ability_index==index)).expect("native printedHaste legally permits actual tap-damage activation");cr_audit_complete_priority_action_with_dm(&mut g,actor,action,&mut d,&mut q).unwrap();activations+=1;assert!(g.is_tapped(source));assert_eq!(g.stack.len(),1);assert_eq!(g.stack[0].object_id,source);assert_eq!(g.stack[0].controller,actor);assert!(g.stack[0].is_ability&&g.stack[0].activation_cost_has_tap);assert_eq!(g.stack[0].targets,vec![Target::Player(other)]);for p in &g.players{assert_eq!(p.life,20);assert_eq!(p.poison_counters,0);}one(&mut g,&mut q,&mut d);let post_stack=g.stack.len();let before_poison=g.player(other).unwrap().poison_counters;let before_life=g.player(other).unwrap().life;let expected_poison=u32::from(infect);let expected_life=if infect{20}else{19};if post_stack!=0||before_poison!=expected_poison||before_life!=expected_life{errors.push(format!("poisonous-noncombat-damage {label}: stack={post_stack} poison={before_poison} life={before_life} expected=0/{expected_poison}/{expected_life}"));}settle(&mut g,&mut q,&mut d);let after=g.player(other).unwrap().poison_counters;if after!=expected_poison||g.player(other).unwrap().life!=expected_life||g.player(actor).unwrap().poison_counters!=0{errors.push(format!("poisonous-noncombat-final {label}: poison={after} life={} actor_poison={} expected={expected_poison}/{expected_life}/0",g.player(other).unwrap().life,g.player(actor).unwrap().poison_counters));}assert_eq!(g.player(actor).unwrap().life,20);assert_eq!(d.targets,1);assert_eq!(d.booleans,0);assert!(d.searches.is_empty());targets+=d.targets;assert_eq!(g.find_object_by_stable_id(stable),Some(source));assert!(g.is_tapped(source));assert_eq!((g.current_power(source),g.current_toughness(source)),(Some(3),Some(7)));for id in sources{assert_eq!(g.object(id).unwrap().zone,Zone::Battlefield);assert_eq!(g.current_controller(id),Some(granter));}assert_eq!(g.turn.turn_number,turn);assert_eq!(g.turn.active_player,actor);assert_eq!(g.turn.phase,Phase::FirstMain);assert!(g.stack.is_empty());assert!(q.is_empty());for p in &g.players{assert_eq!(p.mana_pool.total(),0);}g.validate_zone_consistency().unwrap();games+=1;eprintln!("poisonous-noncombat-observed {label} instances={instance_count} expected_instances={expected_instances} post_stack={post_stack} poison={after} expected_poison={expected_poison} life={} expected_life={expected_life} targets={}",g.player(other).unwrap().life,d.targets);
    }}}}}eprintln!("poisonous-noncombat-summary games={games} activations={activations} targets={targets}");assert!(errors.is_empty(),"CR702.70a: actual noncombatdamage by a Sliver with intrinsic/granted Poisonous does not trigger it. A real tap ability targets/deals1toOpponent;ordinarydamage loses1life,infectdamage adds1poisonwithoutlifeloss,andneither producesanyPoisonousentry/additionalpoison despitefullcurrentVirulentSlivergrants. PrintedHaste andactualTapcostareused: {}",errors.join("\n"));
