    let white_def=ironsmith_compiler_runtime::compile_to_runtime_definition("Native actual white hand-card Evoke resource","Mana cost: {W}\nType: Artifact",false).unwrap();let black_def=ironsmith_compiler_runtime::compile_to_runtime_definition("Native black hand-card Evoke exclusion","Mana cost: {B}\nType: Artifact",false).unwrap();
    let observer=ironsmith_compiler_runtime::compile_to_runtime_definition("Native actual Solitude sacrifice observer","Mana cost: {0}\nType: Artifact\nWhenever a creature you control dies, you gain 1 life.",false).unwrap();assert!(!ironsmith::cards::generated_definition_has_unimplemented_content(&observer));
    let mut errors=Vec::new();let(mut games,mut mana_actions,mut casts,mut card_payments,mut sacrifices,mut targets)=(0,0,0,0,0,0);
    for seat in 0u8..2{let actor=PlayerId::from_index(seat);let other=PlayerId::from_index(1-seat);for second_main in [false,true]{for evoke in [false,true]{
        let label=format!("actor={seat} second_main={second_main} evoke={evoke}");let mut g=GameState::new(vec!["A".into(),"B".into()],20);g.set_starting_player(actor);g.turn.phase=if second_main{Phase::NextMain}else{Phase::FirstMain};g.turn.step=None;
        let keeper=CardDefinitionBuilder::new(CardId::new(),"Native Solitude priority keeper").card_types(vec![CardType::Artifact]).with_ability(Ability::activated(ironsmith::cost::TotalCost::free(),vec![Effect::gain_life(0)])).build();for p in [actor,other]{g.create_object_from_definition(&keeper,p,Zone::Battlefield);g.create_object_from_definition(&observer,p,Zone::Battlefield);}
        let white=g.create_object_from_definition(&white_def,actor,Zone::Hand);let white_stable=g.object(white).unwrap().stable_id;let wrong_color=g.create_object_from_definition(&black_def,actor,Zone::Hand);let wrong_zone=g.create_object_from_definition(&white_def,actor,Zone::Graveyard);let foreign=g.create_object_from_definition(&white_def,other,Zone::Hand);
        let victim_def=CardDefinitionBuilder::new(CardId::new(),"Native actual Solitude four-power exile subject").card_types(vec![CardType::Creature]).power_toughness(PowerToughness::fixed(4,8)).build();let victim=g.create_object_from_definition(&victim_def,other,Zone::Battlefield);let victim_stable=g.object(victim).unwrap().stable_id;
        let hand=g.create_object_from_definition(&definition,actor,Zone::Hand);let physical=g.object(hand).unwrap().stable_id;let mut payers=Vec::new();if !evoke{for symbol in [ManaSymbol::White,ManaSymbol::White,ManaSymbol::Colorless,ManaSymbol::Colorless,ManaSymbol::Colorless]{let payer=CardDefinitionBuilder::new(CardId::new(),"Native actual full Solitude3WW payer").card_types(vec![CardType::Artifact]).with_ability(Ability::mana(ironsmith::cost::TotalCost::free(),vec![symbol])).build();payers.push(g.create_object_from_definition(&payer,actor,Zone::Battlefield));}}
        let mut d=Choices{actor,white,victim,targets:0,cost_choices:0,errors:vec![]};let mut q=TriggerQueue::new();ironsmith::game_loop::advance_priority_with_dm(&mut g,&mut q,&mut d).unwrap();for payer in payers{let action=ironsmith::compute_legal_actions(&g,actor).unwrap().into_iter().find(|a|matches!(a,LegalAction::ActivateManaAbility{source,ability_index:0}if *source==payer)).unwrap();cr_audit_complete_priority_action_with_dm(&mut g,actor,action,&mut d,&mut q).unwrap();assert!(g.is_tapped(payer));mana_actions+=1;}
        let cost=if evoke{0}else{5};let method=if evoke{CastingMethod::Alternative(0)}else{CastingMethod::Normal};assert_eq!(g.player(actor).unwrap().mana_pool.total(),cost);let action=ironsmith::compute_legal_actions(&g,actor).unwrap().into_iter().find(|a|matches!(a,LegalAction::CastSpell{spell_id,casting_method,from_zone:Zone::Hand}if *spell_id==hand&&*casting_method==method)).expect("realwhite-handcardEvokecostornormal3WWisavailable");cr_audit_complete_priority_action_with_dm(&mut g,actor,action,&mut d,&mut q).unwrap();casts+=1;let spell=g.find_object_by_stable_id(physical).unwrap();assert_eq!(g.object(spell).unwrap().mana_spent_to_cast.total(),cost);assert_eq!(g.stack.len(),1);let paid_zone=g.object(g.find_object_by_stable_id(white_stable).unwrap()).unwrap().zone;let expected_paid_zone=if evoke{Zone::Exile}else{Zone::Hand};if paid_zone!=expected_paid_zone{errors.push(format!("solitude-card-cost {label} white={paid_zone:?} expected={expected_paid_zone:?}"));}if paid_zone==Zone::Exile{card_payments+=1;}
        for _ in 0..32{ironsmith::game_loop::advance_priority_with_dm(&mut g,&mut q,&mut d).unwrap();if g.stack.is_empty(){break;}one(&mut g,&mut q,&mut d);}assert!(g.stack.is_empty()&&q.is_empty());let source_zone=g.object(g.find_object_by_stable_id(physical).unwrap()).unwrap().zone;let victim_zone=g.object(g.find_object_by_stable_id(victim_stable).unwrap()).unwrap().zone;let actor_life=g.player(actor).unwrap().life;let other_life=g.player(other).unwrap().life;
        if source_zone!=if evoke{Zone::Graveyard}else{Zone::Battlefield}||victim_zone!=Zone::Exile||actor_life!=20+i32::from(evoke)||other_life!=24{errors.push(format!("solitude-result {label} source={source_zone:?} victim={victim_zone:?} actor_life={actor_life} other_life={other_life} expected_source={} expected_victim=Exile expected_life={}/24",if evoke{"Graveyard"}else{"Battlefield"},20+i32::from(evoke)));}if source_zone==Zone::Graveyard{sacrifices+=1;}
        assert_eq!(g.object(wrong_color).unwrap().zone,Zone::Hand);assert_eq!(g.object(wrong_zone).unwrap().zone,Zone::Graveyard);assert_eq!(g.object(foreign).unwrap().zone,Zone::Hand);assert_eq!(g.object(foreign).unwrap().owner,other);assert_eq!(d.targets,1);targets+=d.targets;for issue in d.errors{errors.push(format!("{label} {issue}"));}for p in &g.players{assert_eq!(p.mana_pool.total(),0);assert_eq!(p.poison_counters,0);}g.validate_zone_consistency().unwrap();games+=1;
        eprintln!("solitude-evoke-observed {label} paid_mana={cost} white={paid_zone:?} source={source_zone:?} victim={victim_zone:?} actor_life={actor_life} other_life={other_life} targets={}",d.targets);
    }}}
