        let mut payers=Vec::new();if previously_evoked{for symbol in [ManaSymbol::Blue,ManaSymbol::Colorless,ManaSymbol::Colorless]{let payer=CardDefinitionBuilder::new(CardId::new(),"Native actual pre-reanimation Evoke payer").card_types(vec![CardType::Artifact]).with_ability(Ability::mana(ironsmith::cost::TotalCost::free(),vec![symbol])).build();payers.push(g.create_object_from_definition(&payer,actor,Zone::Battlefield));}}
        let black_def=CardDefinitionBuilder::new(CardId::new(),"Native actual Reanimate black payer").card_types(vec![CardType::Artifact]).with_ability(Ability::mana(ironsmith::cost::TotalCost::free(),vec![ManaSymbol::Black])).build();let black=g.create_object_from_definition(&black_def,actor,Zone::Battlefield);let card=g.create_object_from_definition(&definition,actor,if previously_evoked{Zone::Hand}else{Zone::Graveyard});let physical=g.object(card).unwrap().stable_id;let spell_hand=g.create_object_from_definition(&reanimate,actor,Zone::Hand);let reanimate_physical=g.object(spell_hand).unwrap().stable_id;let mut d=Choices{actor,target:card,targets:0};let mut q=TriggerQueue::new();ironsmith::game_loop::advance_priority_with_dm(&mut g,&mut q,&mut d).unwrap();
        if previously_evoked{for payer in payers{let action=ironsmith::compute_legal_actions(&g,actor).unwrap().into_iter().find(|a|matches!(a,LegalAction::ActivateManaAbility{source,ability_index:0}if *source==payer)).unwrap();cr_audit_complete_priority_action_with_dm(&mut g,actor,action,&mut d,&mut q).unwrap();assert!(g.is_tapped(payer));mana_actions+=1;}let action=ironsmith::compute_legal_actions(&g,actor).unwrap().into_iter().find(|a|matches!(a,LegalAction::CastSpell{spell_id,casting_method:CastingMethod::Alternative(0),..}if *spell_id==card)).unwrap();cr_audit_complete_priority_action_with_dm(&mut g,actor,action,&mut d,&mut q).unwrap();casts+=1;let spell=g.find_object_by_stable_id(physical).unwrap();assert_eq!(g.object(spell).unwrap().mana_spent_to_cast.total(),3);drain(&mut g,&mut q,&mut d);assert_eq!(g.object(g.find_object_by_stable_id(physical).unwrap()).unwrap().zone,Zone::Graveyard);assert_eq!(library.iter().filter(|stable|g.object(g.find_object_by_stable_id(**stable).unwrap()).unwrap().zone==Zone::Hand).count(),2);old_sacrifices+=1;}
        assert_eq!(g.player(actor).unwrap().life,20);let grave=g.find_object_by_stable_id(physical).unwrap();assert_eq!(g.object(grave).unwrap().zone,Zone::Graveyard);d.target=grave;let action=ironsmith::compute_legal_actions(&g,actor).unwrap().into_iter().find(|a|matches!(a,LegalAction::ActivateManaAbility{source,ability_index:0}if *source==black)).unwrap();cr_audit_complete_priority_action_with_dm(&mut g,actor,action,&mut d,&mut q).unwrap();assert!(g.is_tapped(black));mana_actions+=1;let action=ironsmith::compute_legal_actions(&g,actor).unwrap().into_iter().find(|a|matches!(a,LegalAction::CastSpell{spell_id,casting_method:CastingMethod::Normal,..}if *spell_id==spell_hand)).expect("actual full Reanimate costs one black and has actual graveyard target");cr_audit_complete_priority_action_with_dm(&mut g,actor,action,&mut d,&mut q).unwrap();casts+=1;let spell=g.find_object_by_stable_id(reanimate_physical).unwrap();assert_eq!(g.object(spell).unwrap().mana_spent_to_cast.total(),1);one(&mut g,&mut q,&mut d);let source=g.find_object_by_stable_id(physical).unwrap();assert_eq!(g.object(source).unwrap().zone,Zone::Battlefield);assert_ne!(source,grave);reanimations+=1;let entries=g.stack.iter().filter(|e|e.is_ability&&e.object_id==source).count();if entries!=1{errors.push(format!("evoke-reanimation-condition {label} pending={entries} expected_draw_only=1"));}drain(&mut g,&mut q,&mut d);
