        let draw_def=CardDefinitionBuilder::new(CardId::new(),"Native funded Evoke timing draw witness").card_types(vec![CardType::Artifact]).build();let mut library=Vec::new();for _ in 0..4{let id=g.create_object_from_definition(&draw_def,actor,Zone::Library);library.push(g.object(id).unwrap().stable_id);}
