    let mut errors=Vec::new();let(mut games,mut completed,mut mana_actions,mut casts,mut land_plays,mut looked,mut exiled,mut bottomed)=(0,0,0,0,0,0,0,0);
    for seat in 0u8..2{let actor=PlayerId::from_index(seat);let other=PlayerId::from_index(1-seat);for second_main in [false,true]{for (kind,definition) in definitions.iter().enumerate(){'case:for size in [0usize,1,3,4,5,8]{
        let label=format!("actor={seat} second_main={second_main} kind={kind} size={size}");let n=if kind==2{4}else{5};games+=1;let mut g=GameState::new(vec!["A".into(),"B".into()],20);g.set_starting_player(actor);g.turn.phase=if second_main{Phase::NextMain}else{Phase::FirstMain};g.turn.step=None;
        let keeper=CardDefinitionBuilder::new(CardId::new(),"Native canonical Hideaway priority keeper").card_types(vec![CardType::Artifact]).with_ability(Ability::activated(ironsmith::cost::TotalCost::free(),vec![Effect::gain_life(0)])).build();let shuffle=CardDefinitionBuilder::new(CardId::new(),"Native Hideaway must not shuffle whole library observer").card_types(vec![CardType::Artifact]).with_ability(Ability::triggered(Trigger::player_shuffles_library(PlayerFilter::You,false,false),vec![Effect::gain_life(1)])).build();for p in [actor,other]{g.create_object_from_definition(&keeper,p,Zone::Battlefield);g.create_object_from_definition(&shuffle,p,Zone::Battlefield);}
        for index in 0..size{let mut b=CardDefinitionBuilder::new(CardId::new(),format!("Native Hideaway mixed library witness {index}"));b=match index%4{0=>b.card_types(vec![CardType::Creature]).power_toughness(PowerToughness::fixed(2,8)),1=>b.card_types(vec![CardType::Land]),2=>b.card_types(vec![CardType::Instant]),_=>b.card_types(vec![CardType::Artifact])};g.create_object_from_definition(&b.build(),actor,Zone::Library);}
        let foreign_def=CardDefinitionBuilder::new(CardId::new(),"Native unrelated opponent library witness").card_types(vec![CardType::Artifact]).build();for _ in 0..2{g.create_object_from_definition(&foreign_def,other,Zone::Library);}let foreign_library=g.player(other).unwrap().library.clone();let original=g.player(actor).unwrap().library.clone();let top=original.iter().rev().take(n).copied().collect::<Vec<_>>();let wanted=top.get(usize::from(top.len()>1)).copied();let wanted_stable=wanted.map(|id|g.object(id).unwrap().stable_id);let mut d=Choices{actor,top:top.clone(),wanted,views:vec![],choices:0,targets:0,errors:vec![]};let mut q=TriggerQueue::new();
        let mut payers=Vec::new();if kind!=2{for symbol in [if kind==0{ManaSymbol::Green}else{ManaSymbol::Red},ManaSymbol::Colorless,ManaSymbol::Colorless]{let payer=CardDefinitionBuilder::new(CardId::new(),"Native actual canonical Hideaway mana payer").card_types(vec![CardType::Artifact]).with_ability(Ability::mana(ironsmith::cost::TotalCost::free(),vec![symbol])).build();payers.push(g.create_object_from_definition(&payer,actor,Zone::Battlefield));}}
        let hand=g.create_object_from_definition(definition,actor,Zone::Hand);let physical=g.object(hand).unwrap().stable_id;ironsmith::game_loop::advance_priority_with_dm(&mut g,&mut q,&mut d).unwrap();for payer in payers{let a=ironsmith::compute_legal_actions(&g,actor).unwrap().into_iter().find(|a|matches!(a,LegalAction::ActivateManaAbility{source,ability_index:0}if *source==payer)).unwrap();cr_audit_complete_priority_action_with_dm(&mut g,actor,a,&mut d,&mut q).unwrap();assert!(g.is_tapped(payer));mana_actions+=1;}
        if kind==2{let a=ironsmith::compute_legal_actions(&g,actor).unwrap().into_iter().find(|a|matches!(a,LegalAction::PlayLand{land_id,..}if *land_id==hand)).expect("full Mosswort Bridge actually played as a land");cr_audit_complete_priority_action_with_dm(&mut g,actor,a,&mut d,&mut q).unwrap();land_plays+=1;}else{let a=ironsmith::compute_legal_actions(&g,actor).unwrap().into_iter().find(|a|matches!(a,LegalAction::CastSpell{spell_id,..}if *spell_id==hand)).expect("full canonical Hideaway enchantment actually cast for printed three mana");cr_audit_complete_priority_action_with_dm(&mut g,actor,a,&mut d,&mut q).unwrap();casts+=1;let spell=g.find_object_by_stable_id(physical).unwrap();assert_eq!(g.object(spell).unwrap().mana_spent_to_cast.total(),3);if let Err(e)=one(&mut g,&mut q,&mut d){errors.push(format!("hideaway-resolution-error {label} source-entry {e}"));eprintln!("hideaway-error-observed {label} stage=source-entry");continue 'case;}}
        ironsmith::game_loop::advance_priority_with_dm(&mut g,&mut q,&mut d).unwrap();let source=g.find_object_by_stable_id(physical).unwrap();assert_eq!(g.object(source).unwrap().zone,Zone::Battlefield);let entries=g.stack.iter().filter(|e|e.is_ability&&e.object_id==source).count();if entries!=1{errors.push(format!("hideaway-entry-count {label} entries={entries} expected=1"));}for _ in 0..32{if g.stack.is_empty(){break;}if let Err(e)=one(&mut g,&mut q,&mut d){errors.push(format!("hideaway-resolution-error {label} hideaway {e}"));eprintln!("hideaway-error-observed {label} stage=hideaway");continue 'case;}}assert!(g.stack.is_empty()&&q.is_empty());
        let expected_views=if top.is_empty(){vec![]}else{vec![top.clone()]};if d.views!=expected_views{errors.push(format!("hideaway-view-set {label} views={:?} expected={expected_views:?}",d.views));}looked+=d.views.iter().map(|v|v.len()).sum::<usize>();let mut permission_ok=true;let mut face_down=true;
        if let Some(stable)=wanted_stable{let id=g.find_object_by_stable_id(stable).unwrap();let zone=g.object(id).unwrap().zone;face_down=g.is_face_down(id);permission_ok=g.can_player_look_at_face_down_exiled_card(id,actor)&&!g.can_player_look_at_face_down_exiled_card(id,other);if zone!=Zone::Exile||!face_down||!permission_ok{errors.push(format!("hideaway-selected-card {label} zone={zone:?} face_down={face_down} permission_ok={permission_ok}"));}if zone==Zone::Exile{exiled+=1;assert_ne!(Some(id),wanted);}assert_eq!(g.object(id).unwrap().owner,actor);}else if !g.exile.is_empty(){errors.push(format!("hideaway-empty-exile {label} unexpected_exile={:?}",g.exile));}
        let after=g.player(actor).unwrap().library.clone();let untouched=&original[..original.len()-top.len()];let mut remainder=top.iter().copied().filter(|id|Some(*id)!=wanted).collect::<Vec<_>>();let bottom_len=remainder.len();let order_ok=after.len()==original.len()-usize::from(wanted.is_some())&&after.as_slice().get(bottom_len..)==Some(untouched);let mut actual_bottom=after.iter().take(bottom_len).copied().collect::<Vec<_>>();actual_bottom.sort();remainder.sort();let bottom_ok=order_ok&&actual_bottom==remainder;if !bottom_ok{errors.push(format!("hideaway-bottom {label} before={original:?} top={top:?} wanted={wanted:?} after={after:?} expected_bottom_set={remainder:?} expected_untouched={untouched:?}"));}bottomed+=bottom_len;let tapped=g.is_tapped(source);if tapped!=(kind==2){errors.push(format!("hideaway-tapped {label} tapped={tapped} expected={}",kind==2));}assert_eq!(g.player(other).unwrap().library,foreign_library);assert_eq!(g.find_object_by_stable_id(physical),Some(source));assert_eq!(g.current_controller(source),Some(actor));for p in &g.players{if p.life!=20{errors.push(format!("hideaway-unwanted-shuffle {label} player={:?} life={} expected=20",p.id,p.life));}assert_eq!(p.mana_pool.total(),0);assert_eq!(p.poison_counters,0);}for issue in d.errors{errors.push(format!("{label} {issue}"));}assert_eq!(d.targets,0);g.validate_zone_consistency().unwrap();completed+=1;eprintln!("hideaway-canonical-observed {label} n={n} looked={} selected={} bottomed={bottom_len} bottom_ok={bottom_ok} face_down={face_down} permission_ok={permission_ok} tapped={tapped} targets={}",top.len(),usize::from(wanted.is_some()),d.targets);
    }}}}
    eprintln!("hideaway-canonical-summary games={games} completed={completed} mana_actions={mana_actions} casts={casts} land_plays={land_plays} looked={looked} exiled={exiled} bottomed={bottomed}");assert!(errors.is_empty(),"CR702.75a/b,406.3 and609.3: full paid current Hideaway enchantments and actual Mosswort Bridge land plays privately look at topN or all available,choose one without targeting,actually exile it face down with the correct look permission,and put only the remaining looked cards on the bottom while preserving untouched library order. Empty libraries do nothing. Bottoming randomly is not shuffling the whole library. Modern Hideaway alone does not tap its source;Mosswort's separate enters-tapped clause does: {}",errors.join("\n"));
